const IMGBB_API_KEY = "041ef46fbbddcd8d6ce23a4797538ae4";

export const uploadToImgbb = async (file: File): Promise<string> => {
  const formData = new FormData();
  formData.append('image', file);

  try {
    const response = await fetch(`https://api.imgbb.com/1/upload?key=${IMGBB_API_KEY}`, {
      method: 'POST',
      body: formData,
    });
    const result = await response.json();
    if (result.success) {
      return result.data.url;
    } else {
      throw new Error(result.error.message || 'Upload failed');
    }
  } catch (error) {
    console.error('Error uploading to Imgbb:', error);
    throw error;
  }
};

import React, { useState, useEffect, createContext, useContext } from 'react';

type ToastType = 'success' | 'error' | 'info';

interface Toast {
  id: number;
  message: string;
  type: ToastType;
}

interface ToastContextType {
  notify: (message: string, type?: ToastType) => void;
}

const ToastContext = createContext<ToastContextType | undefined>(undefined);

export const ToastProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [toasts, setToasts] = useState<Toast[]>([]);

  const notify = (message: string, type: ToastType = 'info') => {
    const id = Date.now();
    setToasts((prev) => [...prev, { id, message, type }]);
    setTimeout(() => {
      setToasts((prev) => prev.filter((t) => t.id !== id));
    }, 4000);
  };

  return (
    <ToastContext.Provider value={{ notify }}>
      {children}
      <div className="fixed top-5 right-5 z-[9999] flex flex-col gap-3">
        {toasts.map((toast) => (
          <div
            key={toast.id}
            className={`px-6 py-4 rounded-xl shadow-2xl flex items-center justify-between min-w-[300px] animate-slide-in 
              ${toast.type === 'success' ? 'bg-green-600' : toast.type === 'error' ? 'bg-red-600' : 'bg-[#1F2029]'} 
              text-white transition-all`}
          >
            <p className="font-medium">{toast.message}</p>
            <button onClick={() => setToasts(prev => prev.filter(t => t.id !== toast.id))} className="ml-4 opacity-70 hover:opacity-100">
              ✕
            </button>
          </div>
        ))}
      </div>
    </ToastContext.Provider>
  );
};

export const useNotify = () => {
  const context = useContext(ToastContext);
  if (!context) throw new Error("useNotify must be used within ToastProvider");
  return context.notify;
};

import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Navigate, Link, useLocation, useNavigate } from 'react-router-dom';
import { onAuthStateChanged, User } from 'firebase/auth';
import { doc, getDoc, setDoc, collection, onSnapshot, query, where } from 'firebase/firestore';
import { auth, db } from './firebase';
import { ToastProvider, useNotify } from './components/Notifications';
import { UserProfile, Product, OrderStatus } from './types';

// Pages
import AuthPage from './pages/Auth';
import HomePage from './pages/Home';
import ProductDetails from './pages/ProductDetails';
import CartPage from './pages/Cart';
import CheckoutPage from './pages/Checkout';
import ProfilePage from './pages/Profile';
import OrderSuccess from './pages/OrderSuccess';
import MyOrders from './pages/MyOrders';
import NotificationsPage from './pages/Notifications';
import AdminDashboard from './pages/admin/Dashboard';
import ManageProducts from './pages/admin/ManageProducts';
import ManageUsers from './pages/admin/ManageUsers';
import ManageOrders from './pages/admin/ManageOrders';

const AppContent: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [userData, setUserData] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(true);
  const notify = useNotify();

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      setCurrentUser(user);
      if (user) {
        const userRef = doc(db, 'users', user.uid);
        const userSnap = await getDoc(userRef);
        if (userSnap.exists()) {
          const profile = userSnap.data() as UserProfile;
          if (profile.isBanned) {
            notify("Your account has been banned.", "error");
            auth.signOut();
            setUserData(null);
          } else {
            setUserData(profile);
          }
        }
      } else {
        setUserData(null);
      }
      setLoading(false);
    });
    return unsubscribe;
  }, []);

  if (loading) return <div className="flex h-screen items-center justify-center bg-white"><div className="w-12 h-12 border-4 border-[#704F38] border-t-transparent rounded-full animate-spin"></div></div>;

  return (
    <Router>
      <div className="min-h-screen pb-20 md:pb-0">
        <Routes>
          <Route path="/" element={<HomePage />} />
          <Route path="/auth" element={currentUser ? <Navigate to="/" /> : <AuthPage />} />
          <Route path="/product/:id" element={<ProductDetails />} />
          <Route path="/cart" element={<CartPage />} />
          <Route path="/checkout" element={currentUser ? <CheckoutPage /> : <Navigate to="/auth" />} />
          <Route path="/success" element={<OrderSuccess />} />
          <Route path="/orders" element={currentUser ? <MyOrders /> : <Navigate to="/auth" />} />
          <Route path="/profile" element={currentUser ? <ProfilePage userData={userData} /> : <Navigate to="/auth" />} />
          <Route path="/notifications" element={currentUser ? <NotificationsPage /> : <Navigate to="/auth" />} />

          {/* Admin Routes */}
          <Route path="/admin" element={userData?.role === 'admin' ? <AdminDashboard /> : <Navigate to="/" />} />
          <Route path="/admin/products" element={userData?.role === 'admin' ? <ManageProducts /> : <Navigate to="/" />} />
          <Route path="/admin/users" element={userData?.role === 'admin' ? <ManageUsers /> : <Navigate to="/" />} />
          <Route path="/admin/orders" element={userData?.role === 'admin' ? <ManageOrders /> : <Navigate to="/" />} />
        </Routes>

        {/* Responsive Bottom Navbar for Mobile */}
        <MobileNav isAdmin={userData?.role === 'admin'} />
      </div>
    </Router>
  );
};

