import React, { useState, useEffect } from 'react';
import { collection, addDoc, getDocs, deleteDoc, doc, updateDoc } from 'firebase/firestore';
import { db } from '../../firebase';
import { uploadToImgbb } from '../../services/imgbb';
import { useNotify } from '../../components/Notifications';
import { Product } from '../../types';

const ManageProducts: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [loading, setLoading] = useState(false);
  const notify = useNotify();

  const [formData, setFormData] = useState({
    name: '',
    price: 0,
    description: '',
    category: 'Cases',
    stock: 10,
    imageFile: null as File | null
  });

  const fetchProducts = async () => {
    const snap = await getDocs(collection(db, 'products'));
    setProducts(snap.docs.map(d => ({ id: d.id, ...d.data() } as Product)));
  };

  useEffect(() => { fetchProducts(); }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.imageFile) return notify("Please select an image", "error");

    setLoading(true);
    try {
      const imageUrl = await uploadToImgbb(formData.imageFile);
      const productData = {
        name: formData.name,
        price: Number(formData.price),
        description: formData.description,
        category: formData.category,
        stock: Number(formData.stock),
        image: imageUrl,
        rating: 4.5,
      };
      await addDoc(collection(db, 'products'), productData);
      notify("Product added!", "success");
      setIsAdding(false);
      fetchProducts();
    } catch (err) {
      notify("Failed to add product", "error");
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (window.confirm("Delete this product?")) {
      await deleteDoc(doc(db, 'products', id));
      notify("Deleted", "info");
      fetchProducts();
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <div className="flex justify-between items-center mb-8">
        <h1 className="text-2xl font-bold">Manage Products</h1>
        <button 
          onClick={() => setIsAdding(!isAdding)}
          className="bg-[#1F2029] text-white px-6 py-2 rounded-xl font-bold"
        >
          {isAdding ? "Cancel" : "Add New Product"}
        </button>
      </div>

      {isAdding && (
        <form onSubmit={handleSubmit} className="bg-white p-8 rounded-3xl shadow-sm mb-12 space-y-4 max-w-2xl mx-auto">
          <div>
            <label className="block text-sm font-medium mb-1">Product Name</label>
            <input 
              type="text" className="w-full p-4 bg-gray-50 rounded-xl" required
              onChange={e => setFormData({...formData, name: e.target.value})}
            />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium mb-1">Price (৳)</label>
              <input 
                type="number" className="w-full p-4 bg-gray-50 rounded-xl" required
                onChange={e => setFormData({...formData, price: Number(e.target.value)})}
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Stock</label>
              <input 
                type="number" className="w-full p-4 bg-gray-50 rounded-xl" required
                onChange={e => setFormData({...formData, stock: Number(e.target.value)})}
              />
            </div>
          </div>
          <div>
            <label className="block text-sm font-medium mb-1">Category</label>
            <select 
              className="w-full p-4 bg-gray-50 rounded-xl"
              onChange={e => setFormData({...formData, category: e.target.value})}
            >
              <option>Cases</option>
              <option>Chargers</option>
              <option>Headphones</option>
              <option>Smartwatches</option>
              <option>Gadgets</option>
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium mb-1">Image</label>
            <input 
              type="file" className="w-full p-4 bg-gray-50 rounded-xl" accept="image/*"
              onChange={e => setFormData({...formData, imageFile: e.target.files?.[0] || null})}
            />
          </div>
          <div>
            <label className="block text-sm font-medium mb-1">Description</label>
            <textarea 
              className="w-full p-4 bg-gray-50 rounded-xl h-24"
              onChange={e => setFormData({...formData, description: e.target.value})}
            />
          </div>
          <button 
            disabled={loading}
            className="w-full py-4 bg-[#704F38] text-white rounded-2xl font-bold disabled:opacity-50"
          >
            {loading ? "Uploading..." : "Publish Product"}
          </button>
        </form>
      )}

      <div className="bg-white rounded-3xl shadow-sm overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-gray-50 text-xs font-bold uppercase text-gray-400">
            <tr>
              <th className="px-6 py-4">Product</th>
              <th className="px-6 py-4">Price</th>
              <th className="px-6 py-4">Stock</th>
              <th className="px-6 py-4">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {products.map(p => (
              <tr key={p.id}>
                <td className="px-6 py-4 flex items-center space-x-3">
                  <img src={p.image} className="w-10 h-10 rounded-lg object-cover" alt="" />
                  <span className="font-bold text-sm">{p.name}</span>
                </td>
                <td className="px-6 py-4 text-sm font-bold text-[#704F38]">৳{p.price}</td>
                <td className="px-6 py-4 text-sm">{p.stock}</td>
                <td className="px-6 py-4">
                  <button onClick={() => handleDelete(p.id)} className="text-red-500 hover:text-red-700 transition-colors">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M9 2a1 1 0 00-.894.553L7.382 4H4a1 1 0 000 2v10a2 2 0 002 2h8a2 2 0 002-2V6a1 1 0 100-2h-3.382l-.724-1.447A1 1 0 0011 2H9zM7 8a1 1 0 012 0v6a1 1 0 11-2 0V8zm5-1a1 1 0 00-1 1v6a1 1 0 102 0V8a1 1 0 00-1-1z" clipRule="evenodd" />
                    </svg>
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default ManageProducts;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { doc, getDoc } from 'firebase/firestore';
import { db } from '../firebase';
import { Product } from '../types';
import { useNotify } from '../components/Notifications';

const ProductDetails: React.FC = () => {
  const { id } = useParams();
  const [product, setProduct] = useState<Product | null>(null);
  const [quantity, setQuantity] = useState(1);
  const notify = useNotify();
  const navigate = useNavigate();

  useEffect(() => {
    const fetchProduct = async () => {
      if (!id) return;
      const snap = await getDoc(doc(db, 'products', id));
      if (snap.exists()) setProduct({ id: snap.id, ...snap.data() } as Product);
    };
    fetchProduct();
  }, [id]);

  const addToCart = () => {
    const cart = JSON.parse(localStorage.getItem('vibe_cart') || '[]');
    const existing = cart.find((item: any) => item.productId === product?.id);
    if (existing) {
      existing.quantity += quantity;
    } else {
      cart.push({
        productId: product?.id,
        quantity,
        priceAtPurchase: product?.price,
        name: product?.name,
        image: product?.image
      });
    }
    localStorage.setItem('vibe_cart', JSON.stringify(cart));
    notify("Added to cart!", "success");
    navigate('/cart');
  };

  if (!product) return null;

  return (
    <div className="bg-white min-h-screen">
      <div className="relative">
        <button onClick={() => navigate(-1)} className="absolute top-6 left-6 z-10 p-3 bg-white/80 backdrop-blur rounded-2xl shadow-sm">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
        </button>
        <img src={product.image} className="w-full aspect-[4/5] object-cover" alt="" />
      </div>

      <div className="px-6 py-8 -mt-10 bg-white rounded-t-[40px] relative">
        <div className="flex justify-between items-start mb-4">
          <div>
            <h1 className="text-2xl font-bold text-[#1F2029] mb-1">{product.name}</h1>
            <div className="flex items-center text-sm text-gray-400">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-yellow-400 mr-1" viewBox="0 0 20 20" fill="currentColor"><path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" /></svg>
              <span className="font-bold text-[#1F2029] mr-1">{product.rating}</span>
              (120+ Reviews)
            </div>
          </div>
          <span className="text-2xl font-bold text-[#704F38]">৳{product.price}</span>
        </div>

        <p className="text-gray-500 text-sm leading-relaxed mb-8">
          {product.description || "Premium quality mobile accessory designed for durability and style. This gadget ensures seamless compatibility with your devices while adding a touch of elegance to your tech stack."}
        </p>

        <div className="mb-8">
          <h3 className="font-bold mb-3">Quantity</h3>
          <div className="flex items-center space-x-6">
            <div className="flex items-center bg-gray-100 rounded-2xl p-1">
              <button 
                onClick={() => setQuantity(q => Math.max(1, q-1))}
                className="w-10 h-10 flex items-center justify-center bg-white rounded-xl shadow-sm text-xl font-bold"
              >
                −
              </button>
              <span className="w-12 text-center font-bold">{quantity}</span>
              <button 
                onClick={() => setQuantity(q => q + 1)}
                className="w-10 h-10 flex items-center justify-center bg-white rounded-xl shadow-sm text-xl font-bold"
              >
                +
              </button>
            </div>
            <p className="text-xs text-gray-400">Available: {product.stock} pcs</p>
