          </button>
          <button 
            onClick={addToCart}
            className="flex-1 py-4 bg-[#1F2029] text-white rounded-2xl font-bold shadow-lg shadow-black/20"
          >
            Add to Cart
          </button>
        </div>
      </div>
    </div>
  );
};

