import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { CartItem } from '../types';

const CartPage: React.FC = () => {
  const [items, setItems] = useState<CartItem[]>([]);
  const navigate = useNavigate();

  useEffect(() => {
    const cart = JSON.parse(localStorage.getItem('vibe_cart') || '[]');
    setItems(cart);
  }, []);

  const updateQty = (id: string, delta: number) => {
    const updated = items.map(item => {
      if (item.productId === id) {
        return { ...item, quantity: Math.max(1, item.quantity + delta) };
      }
      return item;
    });
    setItems(updated);
    localStorage.setItem('vibe_cart', JSON.stringify(updated));
  };

  const removeItem = (id: string) => {
    const updated = items.filter(i => i.productId !== id);
    setItems(updated);
    localStorage.setItem('vibe_cart', JSON.stringify(updated));
  };

  const subtotal = items.reduce((acc, curr) => acc + (curr.priceAtPurchase * curr.quantity), 0);

  return (
    <div className="max-w-7xl mx-auto px-4 pt-6 pb-24 min-h-screen">
      <div className="flex items-center space-x-4 mb-8">
        <button onClick={() => navigate(-1)} className="p-2 bg-white rounded-xl shadow-sm">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
        </button>
        <h1 className="text-2xl font-bold">My Cart</h1>
      </div>

      {items.length === 0 ? (
        <div className="text-center py-20">
          <div className="w-24 h-24 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-6 text-4xl">🛒</div>
          <h2 className="text-xl font-bold mb-2">Cart is empty</h2>
          <p className="text-gray-400 mb-8">Looks like you haven't added anything yet.</p>
          <Link to="/" className="px-8 py-3 bg-[#1F2029] text-white rounded-xl font-bold">Shop Gadgets</Link>
        </div>
      ) : (
        <>
          <div className="space-y-4 mb-8">
            {items.map(item => (
              <div key={item.productId} className="bg-white p-4 rounded-3xl flex space-x-4 shadow-sm">
                <img src={item.image} className="w-24 h-24 rounded-2xl object-cover" alt="" />
                <div className="flex-1 flex flex-col justify-between py-1">
                  <div>
                    <div className="flex justify-between">
                      <h3 className="font-bold text-sm line-clamp-1">{item.name}</h3>
                      <button onClick={() => removeItem(item.productId)} className="text-gray-300">✕</button>
                    </div>
                    <p className="text-[#704F38] font-bold mt-1">৳{item.priceAtPurchase}</p>
                  </div>
                  <div className="flex justify-end items-center space-x-3">
                    <button onClick={() => updateQty(item.productId, -1)} className="w-8 h-8 bg-gray-100 rounded-lg font-bold">−</button>
                    <span className="font-bold">{item.quantity}</span>
                    <button onClick={() => updateQty(item.productId, 1)} className="w-8 h-8 bg-gray-100 rounded-lg font-bold">+</button>
                  </div>
                </div>
              </div>
            ))}
          </div>

          <div className="bg-white p-8 rounded-t-[40px] fixed bottom-0 left-0 right-0 shadow-[0_-10px_40px_rgba(0,0,0,0.05)] md:relative md:rounded-3xl md:mt-12">
            <div className="flex justify-between items-center mb-6">
              <span className="text-gray-400 font-medium">Subtotal</span>
              <span className="text-xl font-bold text-[#1F2029]">৳{subtotal}</span>
            </div>
            <Link 
              to="/checkout"
              className="w-full block text-center py-4 bg-[#1F2029] text-white rounded-2xl font-bold shadow-lg shadow-black/20"
            >
              Checkout
            </Link>
          </div>
        </>
      )}
    </div>
  );
};

