import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { auth, db } from '../firebase';
import { collection, addDoc, doc, getDoc } from 'firebase/firestore';
import { useNotify } from '../components/Notifications';
import { CartItem, OrderStatus, UserProfile } from '../types';

const CheckoutPage: React.FC = () => {
  const [items, setItems] = useState<CartItem[]>([]);
  const [userData, setUserData] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(false);

  const [shipping, setShipping] = useState({
    address: '',
    phone: '',
    payment: 'Cash on Delivery'
  });

  const navigate = useNavigate();
  const notify = useNotify();

  useEffect(() => {
    const cart = JSON.parse(localStorage.getItem('vibe_cart') || '[]');
    if (cart.length === 0) navigate('/');
    setItems(cart);

    const fetchUser = async () => {
      if (!auth.currentUser) return;
      const snap = await getDoc(doc(db, 'users', auth.currentUser.uid));
      if (snap.exists()) {
        const data = snap.data() as UserProfile;
        setUserData(data);
        setShipping(s => ({ ...s, address: data.address || '', phone: data.phoneNumber || '' }));
      }
    };
    fetchUser();
  }, []);

  const total = items.reduce((acc, curr) => acc + (curr.priceAtPurchase * curr.quantity), 0);

  const placeOrder = async () => {
    if (!shipping.address || !shipping.phone) return notify("Please fill all details", "error");

    setLoading(true);
    try {
      const orderData = {
        userId: auth.currentUser?.uid,
        customerName: userData?.displayName,
        items,
        total,
        status: OrderStatus.PROCESSING,
        paymentMethod: shipping.payment,
        shippingAddress: shipping.address,
        contactNumber: shipping.phone,
        createdAt: Date.now()
      };

      await addDoc(collection(db, 'orders'), orderData);
      localStorage.removeItem('vibe_cart');
      notify("Order placed successfully!", "success");
      navigate('/success');
    } catch (err) {
      notify("Order failed", "error");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto px-6 py-8 pb-24">
      <h1 className="text-2xl font-bold mb-8">Checkout</h1>

      <div className="space-y-6">
        <section className="bg-white p-6 rounded-3xl shadow-sm">
          <h2 className="font-bold mb-4 flex items-center">
