import React, { useState, useEffect } from 'react';
import { auth, db } from '../firebase';
import { doc, getDoc, updateDoc } from 'firebase/firestore';
import { updateProfile } from 'firebase/auth';
import { UserProfile } from '../types';
import { useNotify } from '../components/Notifications';
import { uploadToImgbb } from '../services/imgbb';
import { useNavigate, Link } from 'react-router-dom';

const ProfilePage: React.FC<{ userData: UserProfile | null }> = ({ userData }) => {
  const [profile, setProfile] = useState<UserProfile | null>(userData);
  const [loading, setLoading] = useState(false);
  const [editing, setEditing] = useState(false);
  const notify = useNotify();
  const navigate = useNavigate();

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    try {
      const url = await uploadToImgbb(file);
      if (auth.currentUser) {
        await updateProfile(auth.currentUser, { photoURL: url });
        await updateDoc(doc(db, 'users', auth.currentUser.uid), { photoURL: url });
        setProfile(prev => prev ? { ...prev, photoURL: url } : null);
        notify("Profile picture updated!", "success");
      }
    } catch (err) {
      notify("Failed to upload image", "error");
    } finally {
      setLoading(false);
    }
  };

  const handleUpdateDetails = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!profile || !auth.currentUser) return;

    setLoading(true);
    try {
      await updateDoc(doc(db, 'users', auth.currentUser.uid), {
        displayName: profile.displayName,
        address: profile.address || '',
        phoneNumber: profile.phoneNumber || ''
      });
      await updateProfile(auth.currentUser, { displayName: profile.displayName });
      setEditing(false);
      notify("Profile updated successfully", "success");
    } catch (err) {
      notify("Update failed", "error");
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    auth.signOut();
    navigate('/auth');
  };

  if (!profile) return null;

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 pb-24">
      <div className="bg-white rounded-[40px] shadow-sm overflow-hidden mb-6">
        <div className="h-32 vibe-brown relative">
          <button 
            onClick={() => navigate(-1)}
            className="absolute top-4 left-4 p-2 bg-white/20 backdrop-blur rounded-xl text-white"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
          </button>
        </div>
        <div className="px-8 pb-8 flex flex-col items-center">
          <div className="relative -mt-16 mb-4">
            <div className="w-32 h-32 rounded-[32px] overflow-hidden border-4 border-white shadow-xl bg-gray-100">
              {loading ? (
                <div className="w-full h-full flex items-center justify-center"><div className="w-8 h-8 border-4 border-[#704F38] border-t-transparent rounded-full animate-spin"></div></div>
              ) : (
                <img src={profile.photoURL || `https://ui-avatars.com/api/?name=${profile.displayName}&background=704F38&color=fff`} className="w-full h-full object-cover" alt="" />
              )}
            </div>
            <label className="absolute bottom-0 right-0 p-2 bg-[#1F2029] text-white rounded-xl shadow-lg cursor-pointer hover:scale-110 transition-transform">
              <input type="file" className="hidden" accept="image/*" onChange={handleImageUpload} disabled={loading} />
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
            </label>
          </div>
          <h2 className="text-2xl font-bold text-[#1F2029]">{profile.displayName}</h2>
          <p className="text-gray-400 text-sm mb-6">{profile.email}</p>

          <div className="w-full grid grid-cols-2 gap-4 mb-8">
            <Link to="/orders" className="p-4 bg-gray-50 rounded-2xl text-center hover:bg-gray-100 transition-all">
              <span className="block text-xl mb-1">📦</span>
              <span className="text-xs font-bold text-gray-500 uppercase tracking-wider">My Orders</span>
            </Link>
            <Link to="/notifications" className="p-4 bg-gray-50 rounded-2xl text-center hover:bg-gray-100 transition-all">
              <span className="block text-xl mb-1">🔔</span>
              <span className="text-xs font-bold text-gray-500 uppercase tracking-wider">Notifs</span>
            </Link>
          </div>

          {!editing ? (
            <div className="w-full space-y-4">
              <div className="bg-gray-50 p-6 rounded-3xl">
                <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-4">Contact Details</h3>
                <div className="space-y-3">
                  <div className="flex justify-between items-center">
                    <span className="text-sm text-gray-500">Phone</span>
                    <span className="text-sm font-bold">{profile.phoneNumber || 'Not added'}</span>
                  </div>
                  <div className="flex justify-between items-center">
                    <span className="text-sm text-gray-500">Address</span>
                    <span className="text-sm font-bold text-right max-w-[150px] truncate">{profile.address || 'Not added'}</span>
                  </div>
                </div>
              </div>
              <button onClick={() => setEditing(true)} className="w-full py-4 border-2 border-gray-100 text-gray-500 rounded-2xl font-bold">Edit Profile</button>
              <button onClick={handleLogout} className="w-full py-4 bg-red-50 text-red-500 rounded-2xl font-bold">Sign Out</button>
            </div>
          ) : (
            <form onSubmit={handleUpdateDetails} className="w-full space-y-4">
              <input 
                type="text" placeholder="Full Name" className="w-full p-4 bg-gray-50 rounded-2xl outline-none focus:ring-2 focus:ring-[#704F38]"
                value={profile.displayName} onChange={e => setProfile({...profile, displayName: e.target.value})}
              />
              <input 
                type="tel" placeholder="Phone Number" className="w-full p-4 bg-gray-50 rounded-2xl outline-none focus:ring-2 focus:ring-[#704F38]"
                value={profile.phoneNumber || ''} onChange={e => setProfile({...profile, phoneNumber: e.target.value})}
              />
              <textarea 
                placeholder="Shipping Address" className="w-full p-4 bg-gray-50 rounded-2xl outline-none h-24 focus:ring-2 focus:ring-[#704F38]"
                value={profile.address || ''} onChange={e => setProfile({...profile, address: e.target.value})}
              />
              <div className="flex space-x-3">
                <button type="button" onClick={() => setEditing(false)} className="flex-1 py-4 bg-gray-100 rounded-2xl font-bold">Cancel</button>
                <button type="submit" disabled={loading} className="flex-1 py-4 bg-[#1F2029] text-white rounded-2xl font-bold">Save Changes</button>
              </div>
            </form>
          )}
        </div>
      </div>

      {profile.role === 'admin' && (
        <Link to="/admin" className="block w-full p-6 bg-[#1F2029] text-white rounded-3xl shadow-xl shadow-black/10 text-center font-bold">
          Go to Admin Panel
        </Link>
      )}
    </div>
  );
};

export default ProfilePage;

import React, { useState, useEffect } from 'react';
import { auth, db } from '../firebase';
import { collection, query, where, onSnapshot, orderBy } from 'firebase/firestore';
import { Order, OrderStatus } from '../types';
import { useNavigate } from 'react-router-dom';

const MyOrders: React.FC = () => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    if (!auth.currentUser) return;

    const q = query(
      collection(db, 'orders'),
      where('userId', '==', auth.currentUser.uid),
      orderBy('createdAt', 'desc')
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      setOrders(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order)));
      setLoading(false);
    });

    return unsubscribe;
  }, []);

  const getStatusColor = (status: OrderStatus) => {
    switch(status) {
      case OrderStatus.DELIVERED: return 'bg-green-100 text-green-600';
      case OrderStatus.SHIPPED: return 'bg-blue-100 text-blue-600';
      case OrderStatus.PROCESSING: return 'bg-orange-100 text-orange-600';
      case OrderStatus.CANCELLED: return 'bg-red-100 text-red-600';
      default: return 'bg-gray-100 text-gray-600';
