                  <img key={idx} src={item.image} className="w-12 h-12 rounded-xl object-cover border-2 border-white shadow-sm" alt="" />
                ))}
                {order.items.length > 3 && (
                  <div className="w-12 h-12 rounded-xl bg-gray-100 border-2 border-white flex items-center justify-center text-xs font-bold text-gray-400">
                    +{order.items.length - 3}
