import React, { useState, useEffect } from 'react';
import { db } from '../../firebase';
import { collection, onSnapshot, query, orderBy, doc, updateDoc } from 'firebase/firestore';
import { Order, OrderStatus } from '../../types';
import { useNotify } from '../../components/Notifications';

const ManageOrders: React.FC = () => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const notify = useNotify();

  useEffect(() => {
    const q = query(collection(db, 'orders'), orderBy('createdAt', 'desc'));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      setOrders(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order)));
      setLoading(false);
    });
    return unsubscribe;
  }, []);

  const updateStatus = async (orderId: string, newStatus: OrderStatus) => {
    try {
      await updateDoc(doc(db, 'orders', orderId), { status: newStatus });
      notify("Order status updated", "success");
    } catch (err) {
      notify("Failed to update status", "error");
    }
  };

  const getStatusColor = (status: OrderStatus) => {
    switch(status) {
      case OrderStatus.DELIVERED: return 'bg-green-100 text-green-600';
      case OrderStatus.SHIPPED: return 'bg-blue-100 text-blue-600';
      case OrderStatus.PROCESSING: return 'bg-orange-100 text-orange-600';
      case OrderStatus.CANCELLED: return 'bg-red-100 text-red-600';
      default: return 'bg-gray-100 text-gray-600';
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <div className="mb-8">
        <h1 className="text-2xl font-bold">Order Management</h1>
        <p className="text-gray-500">View customer details and update delivery status</p>
      </div>

      <div className="space-y-6">
        {orders.map(order => (
          <div key={order.id} className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden">
            <div className="p-6 border-b border-gray-50 flex flex-wrap justify-between items-center gap-4">
              <div>
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Order ID</p>
                <p className="text-sm font-mono font-bold">#{order.id.toUpperCase()}</p>
              </div>
              <div>
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Customer</p>
                <p className="text-sm font-bold">{order.customerName}</p>
                <p className="text-[10px] text-gray-500">{order.contactNumber}</p>
              </div>
              <div>
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Method</p>
                <p className="text-sm font-bold">{order.paymentMethod}</p>
              </div>
              <div className="flex items-center space-x-2">
                <select 
                  value={order.status}
                  onChange={(e) => updateStatus(order.id, e.target.value as OrderStatus)}
                  className={`px-4 py-2 rounded-xl text-xs font-bold border-none outline-none cursor-pointer ${getStatusColor(order.status)}`}
                >
                  {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
            </div>

            <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-8">
              <div>
                <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Ordered Items</h4>
                <div className="space-y-3">
                  {order.items.map((item, idx) => (
                    <div key={idx} className="flex items-center space-x-3">
                      <img src={item.image} className="w-10 h-10 rounded-lg object-cover" alt="" />
                      <div className="flex-1">
                        <p className="text-sm font-bold truncate">{item.name}</p>
                        <p className="text-xs text-gray-400">Qty: {item.quantity} × ৳{item.priceAtPurchase}</p>
