import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { createUserWithEmailAndPassword, updateProfile } from 'firebase/auth';
import { doc, setDoc } from 'firebase/firestore';
import { auth, db } from '../firebase';
import { useNotify } from '../components/Notifications';

const SignUp: React.FC = () => {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [agree, setAgree] = useState(false);
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();
  const notify = useNotify();

  const handleSignUp = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!agree) return notify("Please agree to the terms", "error");

    setLoading(true);
    try {
      const userCred = await createUserWithEmailAndPassword(auth, email, password);
      await updateProfile(userCred.user, { displayName: name });
      await setDoc(doc(db, 'users', userCred.user.uid), {
        uid: userCred.user.uid,
        email,
        displayName: name,
        role: 'user',
        isBanned: false,
        createdAt: Date.now()
      });
      notify("Account created!", "success");
      navigate('/verify');
    } catch (err: any) {
      notify(err.message, "error");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-white p-8 flex flex-col animate-fade-in">
      <div className="flex-1">
        <h1 className="text-3xl font-bold mb-2">Create Account</h1>
        <p className="text-f-gray text-sm mb-10">Fill your information below or register with your social account.</p>

        <form onSubmit={handleSignUp} className="space-y-6">
          <div>
            <label className="block text-sm font-bold mb-2">Name</label>
            <input 
              type="text" 
              placeholder="John Doe" 
              className="w-full bg-f-gray p-4 rounded-2xl outline-none"
              value={name}
              onChange={(e) => setName(e.target.value)}
              required
            />
          </div>
          <div>
            <label className="block text-sm font-bold mb-2">Email</label>
            <input 
              type="email" 
              placeholder="example@gmail.com" 
              className="w-full bg-f-gray p-4 rounded-2xl outline-none"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>
          <div>
            <label className="block text-sm font-bold mb-2">Password</label>
            <div className="relative">
              <input 
                type="password" 
                placeholder="••••••••••••" 
                className="w-full bg-f-gray p-4 rounded-2xl outline-none"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
              />
            </div>
          </div>

          <div className="flex items-center space-x-2">
            <input 
              type="checkbox" 
              id="terms" 
              className="w-5 h-5 accent-black" 
              checked={agree}
              onChange={(e) => setAgree(e.target.checked)}
            />
            <label htmlFor="terms" className="text-xs">Agree with <span className="font-bold underline">Terms & Condition</span></label>
          </div>

          <button disabled={loading} className="btn-primary w-full mt-8">
            {loading ? "Creating..." : "Sign Up"}
          </button>
        </form>

        <div className="mt-12">
          <div className="flex items-center space-x-4 mb-6">
            <div className="flex-1 h-px bg-gray-100"></div>
            <span className="text-xs text-gray-400">Or sign up with</span>
            <div className="flex-1 h-px bg-gray-100"></div>
          </div>
          <div className="flex justify-center space-x-6">
            <button className="w-12 h-12 bg-f-gray rounded-full flex items-center justify-center shadow-sm">f</button>
            <button className="w-12 h-12 bg-f-gray rounded-full flex items-center justify-center shadow-sm">g</button>
            <button className="w-12 h-12 bg-f-gray rounded-full flex items-center justify-center shadow-sm">a</button>
          </div>
        </div>
      </div>

      <p className="mt-8 text-center text-sm">
        Already have an account? <Link to="/signin" className="font-bold underline">Sign In</Link>
      </p>
    </div>
  );
};

export default SignUp;

