import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { auth, db } from '../firebase';
import { collection, addDoc, doc, getDoc } from 'firebase/firestore';
import { useNotify } from '../components/Notifications';
import { CartItem, OrderStatus, UserProfile } from '../types';

const CheckoutPage: React.FC = () => {
  const [items, setItems] = useState<any[]>([]);
  const [userData, setUserData] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(false);

  const [shipping, setShipping] = useState({
    address: '1212 Dhaka, Bangladesh',
    phone: '+880 123456789',
    payment: 'bKash'
  });

  const navigate = useNavigate();
  const notify = useNotify();

  useEffect(() => {
    const cart = JSON.parse(localStorage.getItem('f_cart') || '[]');
    if (cart.length === 0) {
        notify("Your cart is empty", "info");
        navigate('/');
        return;
    }
    setItems(cart);

    const fetchUser = async () => {
      if (!auth.currentUser) return;
      const snap = await getDoc(doc(db, 'users', auth.currentUser.uid));
      if (snap.exists()) {
        const data = snap.data() as UserProfile;
        setUserData(data);
        if(data.address) setShipping(s => ({ ...s, address: data.address || s.address }));
        if(data.phoneNumber) setShipping(s => ({ ...s, phone: data.phoneNumber || s.phone }));
      }
    };
    fetchUser();
  }, []);

  const total = items.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);

  const placeOrder = async () => {
    if (!shipping.address || !shipping.phone) return notify("Please fill all details", "error");

    setLoading(true);
    try {
      const orderData = {
        userId: auth.currentUser?.uid || 'guest',
        customerName: userData?.displayName || 'Guest',
        items: items.map(i => ({
            productId: i.id,
            quantity: i.quantity,
            priceAtPurchase: i.price,
            name: i.name,
            image: i.image
        })),
        total: total + 60, // Total including delivery fee
        status: OrderStatus.PROCESSING,
        paymentMethod: shipping.payment,
        shippingAddress: shipping.address,
        contactNumber: shipping.phone,
        createdAt: Date.now()
      };

      await addDoc(collection(db, 'orders'), orderData);
      localStorage.removeItem('f_cart');
      notify("Order placed successfully!", "success");
      navigate('/success');
    } catch (err) {
      notify("Order failed", "error");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-md mx-auto px-6 py-8 pb-24 animate-fade-in bg-white">
      <div className="flex items-center space-x-4 mb-8">
          <button onClick={() => navigate(-1)} className="p-2 bg-f-gray rounded-xl">
             <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7" /></svg>
          </button>
          <h1 className="text-xl font-bold">Checkout</h1>
      </div>

      <div className="space-y-6">
        <section className="bg-f-gray p-6 rounded-3xl shadow-sm border border-f-light">
          <div className="flex justify-between items-center mb-4">
            <h2 className="font-bold flex items-center">
              Shipping Address
            </h2>
            <button onClick={() => navigate('/shipping-address')} className="text-xs font-bold underline">Change</button>
          </div>
          <div className="space-y-3">
             <div className="flex items-start space-x-3">
                <div className="w-8 h-8 bg-white rounded-xl flex items-center justify-center shrink-0">📍</div>
                <div>
                   <p className="text-xs font-bold">Home</p>
                   <p className="text-[10px] text-f-gray">{shipping.address}</p>
                </div>
             </div>
          </div>
        </section>

        <section className="bg-f-gray p-6 rounded-3xl shadow-sm border border-f-light">
          <div className="flex justify-between items-center mb-4">
            <h2 className="font-bold">Payment Method</h2>
            <button onClick={() => navigate('/payment-methods')} className="text-xs font-bold underline">Change</button>
          </div>
          <div className="flex items-center space-x-3">
            <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center p-1">
                {shipping.payment === 'bKash' ? <img src="https://www.logo.wine/a/logo/BKash/BKash-Logo.wine.svg" className="w-full h-full object-contain" /> : 
                 shipping.payment === 'Nagad' ? <img src="https://www.logo.wine/a/logo/Nagad/Nagad-Logo.wine.svg" className="w-full h-full object-contain" /> : 
                 <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2z"/></svg>}
            </div>
            <span className="text-sm font-bold">{shipping.payment}</span>
          </div>
        </section>

        <section className="bg-f-gray p-6 rounded-3xl shadow-sm border border-f-light">
          <h2 className="font-bold mb-4">Order Summary</h2>
          <div className="space-y-2 mb-4">
            <div className="flex justify-between text-xs text-f-gray">
              <span>Sub-Total</span>
              <span className="text-black font-bold">৳{total}</span>
            </div>
            <div className="flex justify-between text-xs text-f-gray">
              <span>Delivery Fee</span>
              <span className="text-black font-bold">৳60</span>
            </div>
            <div className="flex justify-between text-xs text-f-gray">
              <span>Discount</span>
              <span className="text-black font-bold">-৳00</span>
            </div>
            <div className="h-px bg-white/50 my-2"></div>
            <div className="flex justify-between font-bold text-lg pt-2">
              <span>Total Cost</span>
              <span>৳{total + 60}</span>
            </div>
          </div>
        </section>
      </div>

      <button 
        disabled={loading}
        onClick={placeOrder}
        className="btn-primary w-full mt-10 disabled:opacity-50"
      >
        {loading ? "Confirming..." : `Confirm Order (৳${total + 60})`}
      </button>
    </div>
  );
};

export default CheckoutPage;

