              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6v6m0 0v6m0-6h6m-6 0H6" /></svg>
            </button>
          </div>
        </div>

        <form onSubmit={handleComplete} className="space-y-6">
          <div>
            <label className="block text-sm font-bold mb-2">Name</label>
            <input 
                type="text" 
                placeholder="John Doe" 
                className="w-full bg-f-gray p-4 rounded-2xl outline-none border border-transparent focus:border-black transition-all" 
                required 
                value={formData.name}
                onChange={e => setFormData({...formData, name: e.target.value})}
            />
          </div>
          <div>
            <label className="block text-sm font-bold mb-2">Phone Number</label>
            <div className="flex space-x-2">
              <div className="bg-f-gray p-4 rounded-2xl font-bold text-sm">+880</div>
              <input 
                type="tel" 
                placeholder="1XXXXXXXXX" 
                className="flex-1 bg-f-gray p-4 rounded-2xl outline-none border border-transparent focus:border-black transition-all" 
                required 
                value={formData.phone}
                onChange={e => setFormData({...formData, phone: e.target.value})}
              />
            </div>
          </div>
          <div>
            <label className="block text-sm font-bold mb-2">Gender</label>
            <select 
                className="w-full bg-f-gray p-4 rounded-2xl outline-none border border-transparent focus:border-black transition-all appearance-none" 
                required
                value={formData.gender}
                onChange={e => setFormData({...formData, gender: e.target.value})}
            >
              <option value="">Select</option>
              <option value="male">Male</option>
              <option value="female">Female</option>
              <option value="other">Other</option>
            </select>
          </div>

          <button disabled={loading} className="btn-primary w-full mt-10 disabled:opacity-50">
            {loading ? "Saving..." : "Complete Profile"}
          </button>
        </form>
      </div>
    </div>
  );
};

export default CompleteProfile;

import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Navigate, useLocation } from 'react-router-dom';
import { onAuthStateChanged, User } from 'firebase/auth';
import { doc, getDoc } from 'firebase/firestore';
import { auth, db } from './firebase';
import { ToastProvider } from './components/Notifications';
import { UserProfile } from './types';

// Page Imports
import Onboarding from './pages/Onboarding';
import AuthSelector from './pages/AuthSelector';
import SignIn from './pages/SignIn';
import SignUp from './pages/SignUp';
import VerifyCode from './pages/VerifyCode';
import CompleteProfile from './pages/CompleteProfile';
import NewPassword from './pages/NewPassword';
import LocationAccess from './pages/LocationAccess';
import Home from './pages/Home';
import ProductDetails from './pages/ProductDetails';
import Wishlist from './pages/Wishlist';
import Cart from './pages/Cart';
import Checkout from './pages/Checkout';
import ShippingAddress from './pages/ShippingAddress';
import Coupon from './pages/Coupon';
import PaymentMethods from './pages/PaymentMethods';
import AddCard from './pages/AddCard';
import PaymentSuccess from './pages/PaymentSuccess';
import Search from './pages/Search';
import MyOrders from './pages/MyOrders';
import TrackOrder from './pages/TrackOrder';
import LeaveReview from './pages/LeaveReview';
import EReceipt from './pages/EReceipt';
import NotificationsPage from './pages/Notifications';
import Profile from './pages/Profile';
import Settings from './pages/Settings';
import HelpCenter from './pages/HelpCenter';
import PrivacyPolicy from './pages/PrivacyPolicy';
import BottomNav from './components/BottomNav';

const AppContent: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [userData, setUserData] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(true);
  const location = useLocation();

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      setCurrentUser(user);
      if (user) {
        try {
            const userRef = doc(db, 'users', user.uid);
            const userSnap = await getDoc(userRef);
            if (userSnap.exists()) {
              setUserData(userSnap.data() as UserProfile);
            }
        } catch (e) {
            console.error("Error fetching user profile", e);
        }
      } else {
        setUserData(null);
      }
      setLoading(false);
    });
    return unsubscribe;
  }, []);

  const hideNavPaths = [
    '/onboarding', 
    '/auth-selector', 
    '/signin', 
    '/signup', 
    '/verify', 
    '/complete-profile', 
    '/new-password', 
    '/location', 
    '/success', 
    '/e-receipt'
  ];

  const isAuthPath = ['/auth-selector', '/signin', '/signup', '/onboarding'].some(path => location.pathname.startsWith(path));
  const showBottomNav = !hideNavPaths.some(path => location.pathname.startsWith(path));

  if (loading) return (
    <div className="h-screen flex flex-col items-center justify-center bg-white">
        <div className="w-12 h-12 border-4 border-black border-t-transparent rounded-full animate-spin"></div>
        <p className="mt-4 font-bold text-sm tracking-widest uppercase opacity-20">Fashion.</p>
    </div>
  );

  // If not logged in and not on an auth path, redirect to onboarding/auth-selector
  if (!currentUser && !isAuthPath) {
      return <Navigate to="/onboarding" replace />;
  }

  return (
    <div className="max-w-md mx-auto min-h-screen bg-white shadow-xl relative overflow-hidden flex flex-col border-x border-f-light">
      <div className="flex-1 overflow-y-auto no-scrollbar">
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/onboarding" element={currentUser ? <Navigate to="/" /> : <Onboarding />} />
          <Route path="/auth-selector" element={currentUser ? <Navigate to="/" /> : <AuthSelector />} />
          <Route path="/signin" element={currentUser ? <Navigate to="/" /> : <SignIn />} />
          <Route path="/signup" element={currentUser ? <Navigate to="/" /> : <SignUp />} />
          <Route path="/verify" element={<VerifyCode />} />
          <Route path="/complete-profile" element={<CompleteProfile />} />
          <Route path="/new-password" element={<NewPassword />} />
          <Route path="/location" element={<LocationAccess />} />
          <Route path="/product/:id" element={<ProductDetails />} />
          <Route path="/wishlist" element={<Wishlist />} />
          <Route path="/cart" element={<Cart />} />
          <Route path="/checkout" element={<Checkout />} />
          <Route path="/shipping-address" element={<ShippingAddress />} />
          <Route path="/coupon" element={<Coupon />} />
          <Route path="/payment-methods" element={<PaymentMethods />} />
          <Route path="/add-card" element={<AddCard />} />
          <Route path="/success" element={<PaymentSuccess />} />
          <Route path="/search" element={<Search />} />
          <Route path="/orders" element={<MyOrders />} />
          <Route path="/track-order/:id" element={<TrackOrder />} />
          <Route path="/leave-review/:id" element={<LeaveReview />} />
          <Route path="/e-receipt/:id" element={<EReceipt />} />
          <Route path="/notifications" element={<NotificationsPage />} />
          <Route path="/profile" element={<Profile userData={userData} />} />
          <Route path="/settings" element={<Settings />} />
          <Route path="/help-center" element={<HelpCenter />} />
          <Route path="/privacy-policy" element={<PrivacyPolicy />} />
          <Route path="*" element={<Navigate to="/" />} />
        </Routes>
      </div>
      {showBottomNav && <BottomNav />}
    </div>
  );
};

const App: React.FC = () => {
  return (
    <ToastProvider>
      <Router>
        <AppContent />
      </Router>
    </ToastProvider>
  );
};

export default App;

