import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { auth, db } from '../firebase';
import { collection, addDoc, doc, getDoc } from 'firebase/firestore';
import { useNotify } from '../components/Notifications';
import { CartItem, OrderStatus, UserProfile } from '../types';

const CheckoutPage: React.FC = () => {
  const [items, setItems] = useState<any[]>([]);
  const [userData, setUserData] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(false);
  const [payFull, setPayFull] = useState(false);

  const [shipping, setShipping] = useState({
    address: 'Dhaka, Bangladesh',
    phone: '',
    payment: 'bKash'
  });

  const navigate = useNavigate();
  const notify = useNotify();

  useEffect(() => {
    const cart = JSON.parse(localStorage.getItem('f_cart') || '[]');
    if (cart.length === 0) {
        notify("Your cart is empty", "info");
        navigate('/');
        return;
    }
    setItems(cart);

    const fetchUser = async () => {
      if (!auth.currentUser) return;
      const snap = await getDoc(doc(db, 'users', auth.currentUser.uid));
      if (snap.exists()) {
        const data = snap.data() as UserProfile;
        setUserData(data);
        if(data.address) setShipping(s => ({ ...s, address: data.address || s.address }));
        if(data.phoneNumber) setShipping(s => ({ ...s, phone: data.phoneNumber || s.phone }));
      }
    };
    fetchUser();
  }, []);

  const subTotal = items.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
  const deliveryFee = 60;
  const currentPayable = (shipping.payment === 'Cash on Delivery' || !payFull) ? deliveryFee : (subTotal + deliveryFee);

  const placeOrder = async () => {
    if (!shipping.address || !shipping.phone) return notify("Please fill all details", "error");

    setLoading(true);
    try {
      const orderData = {
        userId: auth.currentUser?.uid || 'guest',
        customerName: userData?.displayName || 'Guest',
        items: items.map(i => ({
            productId: i.id,
            quantity: i.quantity,
            priceAtPurchase: i.price,
            name: i.name,
            image: i.image
        })),
        total: subTotal + deliveryFee,
        paidAmount: currentPayable,
        status: OrderStatus.PROCESSING,
        paymentMethod: shipping.payment,
        paymentOption: payFull ? 'Full Payment' : 'Delivery Only',
        shippingAddress: shipping.address,
        contactNumber: shipping.phone,
        createdAt: Date.now()
      };

      await addDoc(collection(db, 'orders'), orderData);
      localStorage.removeItem('f_cart');
      notify("Order placed successfully!", "success");
      navigate('/success');
    } catch (err) {
      notify("Order failed", "error");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-md mx-auto px-6 py-8 pb-24 animate-fade-in bg-white">
      <div className="flex items-center space-x-4 mb-10">
          <button onClick={() => navigate(-1)} className="p-3 bg-f-gray rounded-2xl">
             <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" /></svg>
          </button>
          <h1 className="text-xl font-bold">Checkout Summary</h1>
      </div>

      <div className="space-y-6">
        <section className="bg-f-gray p-6 rounded-[32px] border border-f-light">
          <div className="flex justify-between items-center mb-6">
            <h2 className="font-bold text-sm tracking-tight flex items-center">
              Shipping Info
            </h2>
            <button onClick={() => navigate('/shipping-address')} className="text-[10px] font-bold uppercase tracking-wider text-gray-400">Edit</button>
          </div>
          <div className="space-y-4">
             <div className="flex items-start space-x-3">
                <div className="w-10 h-10 bg-white rounded-2xl flex items-center justify-center shrink-0">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M15 10.5a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" d="M19.5 10.5c0 7.142-7.5 11.25-7.5 11.25S4.5 17.642 4.5 10.5a7.5 7.5 0 1115 0z" /></svg>
                </div>
                <div>
                   <p className="text-[10px] font-bold text-gray-400 uppercase">Address</p>
                   <p className="text-xs font-bold leading-relaxed">{shipping.address}</p>
                </div>
             </div>
             <div className="flex items-start space-x-3">
                <div className="w-10 h-10 bg-white rounded-2xl flex items-center justify-center shrink-0">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M2.25 6.75c0 8.284 6.716 15 15 15h2.25a2.25 2.25 0 002.25-2.25v-1.372c0-.516-.351-.966-.852-1.091l-4.423-1.106c-.44-.11-.902.055-1.173.417l-.97 1.293c-.282.376-.769.542-1.21.38a12.035 12.035 0 01-7.143-7.143c-.162-.441.004-.928.38-1.21l1.293-.97c.363-.271.527-.734.417-1.173L6.963 3.102a1.125 1.125 0 00-1.091-.852H4.5A2.25 2.25 0 002.25 4.5v2.25z" /></svg>
                </div>
                <div>
                   <p className="text-[10px] font-bold text-gray-400 uppercase">Phone</p>
                   <p className="text-xs font-bold">{shipping.phone || 'Not provided'}</p>
                </div>
             </div>
          </div>
        </section>

