            <button onClick={() => navigate('/')} className="mt-8 text-black font-bold underline text-xs uppercase tracking-widest">Discover Gadgets</button>
         </div>
       ) : (
         <>
           <div className="space-y-4 mb-10">
             {items.map((item, idx) => (
               <div key={idx} className="bg-white p-4 rounded-[32px] flex items-center space-x-4 border border-f-light shadow-sm">
                  <div className="w-24 h-24 bg-f-gray rounded-3xl overflow-hidden shadow-inner">
