import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useNotify } from '../components/Notifications';
import { updatePassword, reauthenticateWithCredential, EmailAuthProvider } from 'firebase/auth';
import { auth } from '../firebase';

const PasswordManager: React.FC = () => {
  const navigate = useNavigate();
  const notify = useNotify();
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    oldPassword: '',
    newPassword: '',
    confirmPassword: ''
  });

  const handleChange = async (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.newPassword !== formData.confirmPassword) {
      return notify("New passwords do not match", "error");
    }
    if (formData.newPassword.length < 6) {
      return notify("Password must be at least 6 characters", "error");
    }

    setLoading(true);
    try {
      const user = auth.currentUser;
      if (!user || !user.email) throw new Error("No active session");

      // Re-authenticate user before password change
      const credential = EmailAuthProvider.credential(user.email, formData.oldPassword);
      await reauthenticateWithCredential(user, credential);

      await updatePassword(user, formData.newPassword);
      notify("Password updated successfully!", "success");
      navigate('/settings');
    } catch (err: any) {
      notify(err.message || "Failed to update password", "error");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-6 animate-fade-in bg-white max-w-md mx-auto min-h-screen flex flex-col">
       <div className="flex items-center space-x-4 mb-10">
          <button onClick={() => navigate(-1)} className="p-3 bg-f-gray rounded-2xl">
             <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" /></svg>
          </button>
          <h1 className="text-xl font-bold">Password Manager</h1>
       </div>

       <form onSubmit={handleChange} className="flex-1 space-y-6">
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-3">Current Password</label>
            <input 
              type="password" 
              className="w-full bg-f-gray p-5 rounded-[24px] outline-none border border-transparent focus:border-black transition-all"
              required
              value={formData.oldPassword}
              onChange={e => setFormData({...formData, oldPassword: e.target.value})}
            />
          </div>

          <div className="space-y-6 pt-4 border-t border-f-light">
             <div>
               <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-3">New Password</label>
               <input 
                 type="password" 
                 className="w-full bg-f-gray p-5 rounded-[24px] outline-none border border-transparent focus:border-black transition-all"
                 required
                 value={formData.newPassword}
                 onChange={e => setFormData({...formData, newPassword: e.target.value})}
               />
             </div>
             <div>
               <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-3">Confirm New Password</label>
               <input 
                 type="password" 
                 className="w-full bg-f-gray p-5 rounded-[24px] outline-none border border-transparent focus:border-black transition-all"
                 required
                 value={formData.confirmPassword}
                 onChange={e => setFormData({...formData, confirmPassword: e.target.value})}
               />
             </div>
          </div>

          <button 
            disabled={loading}
            className="btn-primary w-full mt-10 shadow-xl shadow-black/10 disabled:opacity-50"
          >
            {loading ? "Updating..." : "Update Password"}
          </button>
       </form>
    </div>
  );
};

export default PasswordManager;

import React, { useState, useEffect } from 'react';
import { auth, db } from '../firebase';
import { collection, query, where, onSnapshot } from 'firebase/firestore';
import { Order, OrderStatus } from '../types';
import { useNavigate } from 'react-router-dom';

const MyOrders: React.FC = () => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    if (!auth.currentUser) return;

    // We fetch all orders and sort them in JS to avoid "Missing Index" Firebase errors
    const q = query(
      collection(db, 'orders'),
      where('userId', '==', auth.currentUser.uid)
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));
      // Sort by creation date descending
      data.sort((a, b) => b.createdAt - a.createdAt);
      setOrders(data);
      setLoading(false);
    }, (error) => {
      console.error("Order fetch error:", error);
      setLoading(false);
    });

    return unsubscribe;
  }, []);

  const getStatusColor = (status: OrderStatus) => {
    switch(status) {
      case OrderStatus.DELIVERED: return 'bg-green-100 text-green-600';
      case OrderStatus.SHIPPED: return 'bg-blue-100 text-blue-600';
      case OrderStatus.PROCESSING: return 'bg-orange-100 text-orange-600';
      case OrderStatus.CANCELLED: return 'bg-red-100 text-red-600';
      default: return 'bg-gray-100 text-gray-600';
    }
  };

  return (
    <div className="max-w-md mx-auto px-6 py-8 pb-24 animate-fade-in min-h-screen bg-white">
      <div className="flex items-center space-x-4 mb-10">
        <button onClick={() => navigate(-1)} className="p-3 bg-f-gray rounded-2xl">
          <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" /></svg>
        </button>
        <h1 className="text-xl font-bold">Purchase History</h1>
      </div>

      {loading ? (
        <div className="flex justify-center py-20"><div className="w-10 h-10 border-4 border-black border-t-transparent rounded-full animate-spin"></div></div>
      ) : orders.length === 0 ? (
        <div className="text-center py-24">
          <div className="w-20 h-20 bg-f-gray rounded-[32px] flex items-center justify-center mx-auto mb-6">
             <svg className="w-8 h-8 text-gray-300" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M15.75 10.5V6a3.75 3.75 0 10-7.5 0v4.5m11.356-1.993l1.263 12c.07.665-.45 1.243-1.119 1.243H4.25a1.125 1.125 0 01-1.12-1.243l1.264-12A1.125 1.125 0 015.513 7.5h12.974c.576 0 1.059.435 1.119 1.007z" /></svg>
          </div>
          <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">No orders yet</p>
        </div>
      ) : (
        <div className="space-y-6">
          {orders.map(order => (
            <div key={order.id} onClick={() => navigate(`/track-order/${order.id}`)} className="bg-white p-6 rounded-[32px] border border-f-light shadow-sm hover:shadow-md transition-shadow cursor-pointer">
              <div className="flex justify-between items-start mb-6">
                <div>
                  <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">Receipt ID</p>
                  <p className="text-xs font-mono font-bold">#{order.id.slice(0, 8).toUpperCase()}</p>
                </div>
                <span className={`px-3 py-1.5 rounded-2xl text-[9px] font-bold uppercase tracking-wider ${getStatusColor(order.status)}`}>
                  {order.status}
                </span>
              </div>

              <div className="flex -space-x-4 mb-6">
                {order.items.map((item, idx) => (
                  <img key={idx} src={item.image} className="w-14 h-14 rounded-2xl object-cover border-4 border-white shadow-sm ring-1 ring-gray-100" alt="" />
                ))}
                {order.items.length > 3 && (
                  <div className="w-14 h-14 rounded-2xl bg-f-gray border-4 border-white flex items-center justify-center text-[10px] font-bold text-gray-400">
                    +{order.items.length - 3}
                  </div>
                )}
              </div>

              <div className="flex justify-between items-center border-t border-f-light pt-6">
                <div>
                  <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1">Total Paid</p>
                  <p className="text-lg font-bold">৳{order.total}</p>
                </div>
                <div className="text-right">
                  <p className="text-[9px] text-gray-400 font-bold uppercase tracking-widest mb-1">{new Date(order.createdAt).toLocaleDateString()}</p>
                  <div className="flex items-center space-x-1 text-black font-bold text-[10px] uppercase">
                     <span>Details</span>
                     <svg className="w-3 h-3" fill="none" stroke="currentColor" strokeWidth="3" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M8.25 4.5l7.5 7.5-7.5 7.5" /></svg>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

