            </button>
            <input type="file" hidden ref={fileInputRef} onChange={handleImageChange} accept="image/*" />
          </div>

          {isEditing ? (
            <div className="flex flex-col items-center w-full px-10">
               <input 
                  type="text" 
                  className="w-full text-center bg-f-gray p-2 rounded-xl font-bold mb-2 outline-none border border-transparent focus:border-black"
                  value={editName}
                  onChange={(e) => setEditName(e.target.value)}
