import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { signInWithEmailAndPassword } from 'firebase/auth';
import { auth } from '../firebase';
import { useNotify } from '../components/Notifications';

const SignIn: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();
  const notify = useNotify();

  const handleSignIn = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      await signInWithEmailAndPassword(auth, email, password);
      notify("Welcome back!", "success");
      navigate('/');
    } catch (err: any) {
      notify(err.message, "error");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-white p-8 flex flex-col animate-fade-in max-w-md mx-auto">
      <button onClick={() => navigate(-1)} className="p-3 bg-f-gray rounded-2xl self-start mb-10 shadow-sm active:scale-90 transition-transform">
        <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" /></svg>
      </button>

      <div className="flex-1">
        <h1 className="text-3xl font-bold mb-2 tracking-tighter">Vibe Gadget</h1>
        <p className="text-f-gray text-xs font-bold uppercase tracking-[0.2em] mb-10 opacity-60">Tech Account Login</p>

        <form onSubmit={handleSignIn} className="space-y-6">
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Auth Email</label>
            <input 
              type="email" 
              placeholder="user@vibegadget.com" 
              className="w-full bg-f-gray p-5 rounded-2xl border border-transparent focus:border-black outline-none transition-all font-medium text-sm"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Passkey</label>
            <div className="relative">
              <input 
                type="password" 
                placeholder="••••••••••••" 
                className="w-full bg-f-gray p-5 rounded-2xl border border-transparent focus:border-black outline-none transition-all font-medium text-sm"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
              />
