import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { createUserWithEmailAndPassword, updateProfile } from 'firebase/auth';
import { doc, setDoc } from 'firebase/firestore';
import { auth, db } from '../firebase';
import { useNotify } from '../components/Notifications';

const SignUp: React.FC = () => {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [agree, setAgree] = useState(false);
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();
  const notify = useNotify();

  const handleSignUp = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!agree) return notify("Please agree to the terms", "error");

    setLoading(true);
    try {
      const userCred = await createUserWithEmailAndPassword(auth, email, password);
      await updateProfile(userCred.user, { displayName: name });
      await setDoc(doc(db, 'users', userCred.user.uid), {
        uid: userCred.user.uid,
        email,
        displayName: name,
        role: 'user',
        isBanned: false,
        createdAt: Date.now()
      });
      notify("Account created!", "success");
      navigate('/verify');
    } catch (err: any) {
      notify(err.message, "error");
    } finally {
      setLoading(false);
    }
  };

  const socialNotice = () => notify("This feature isn’t available in your location", "info");

  return (
    <div className="min-h-screen bg-white p-8 flex flex-col animate-fade-in max-w-md mx-auto">
      <div className="flex-1">
        <h1 className="text-3xl font-bold mb-2 tracking-tighter">Join Vibe Hub</h1>
        <p className="text-f-gray text-sm mb-10 font-medium">Register your node for premium gadget access and logistics tracking.</p>

        <form onSubmit={handleSignUp} className="space-y-6">
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Display Identity</label>
            <input 
              type="text" 
              placeholder="Full Name" 
              className="w-full bg-f-gray p-4 rounded-2xl outline-none border border-transparent focus:border-black transition-all"
              value={name}
              onChange={(e) => setName(e.target.value)}
              required
            />
          </div>
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Auth Email</label>
            <input 
              type="email" 
              placeholder="example@gmail.com" 
              className="w-full bg-f-gray p-4 rounded-2xl outline-none border border-transparent focus:border-black transition-all"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Secure Passkey</label>
            <input 
              type="password" 
              placeholder="••••••••••••" 
              className="w-full bg-f-gray p-4 rounded-2xl outline-none border border-transparent focus:border-black transition-all"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>

          <div className="flex items-center space-x-3">
            <input 
              type="checkbox" 
