    if (!auth.currentUser || !editName.trim()) return;
    setUpdating(true);
    try {
      await updateProfile(auth.currentUser, { displayName: editName.trim() });
      const userRef = doc(db, 'users', auth.currentUser.uid);
      await updateDoc(userRef, { displayName: editName.trim() });
