const API_KEY = "joitjujewr5bxm27jcd6maeqrmwtmbld";
const SECRET_KEY = "qhxzuwgzdmo3qa3shamzuskd";
const BASE_URL = "https://portal.steadfast.com.bd/api/v1";

export const sendOrderToSteadfast = async (order: any) => {
  try {
    const response = await fetch(`${BASE_URL}/create_order`, {
      method: 'POST',
      mode: 'cors',
      headers: {
        'Content-Type': 'application/json',
        'Api-Key': API_KEY,
        'Secret-Key': SECRET_KEY,
        'Accept': 'application/json'
      },
      body: JSON.stringify({
        invoice: order.id,
        recipient_name: order.customerName,
        recipient_phone: order.contactNumber,
        recipient_address: order.shippingAddress,
        cod_amount: order.total,
        note: `Payment: ${order.paymentMethod}`
      })
    });

    const result = await response.json();
    return result;
  } catch (error) {
    console.error("Steadfast API error:", error);
    throw error;
  }
};

export const getSteadfastStatus = async (trackingCode: string) => {
  try {
    const response = await fetch(`${BASE_URL}/status_by_trackingcode/${trackingCode}`, {
      method: 'GET',
      mode: 'cors',
      headers: {
        'Api-Key': API_KEY,
        'Secret-Key': SECRET_KEY,
        'Accept': 'application/json'
      }
    });
    return await response.json();
  } catch (error) {
    console.error("Steadfast Status error:", error);
    return null;
  }
};

