import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { doc, getDoc, updateDoc } from 'firebase/firestore';
import { db } from '../firebase';
import { Order, OrderStatus } from '../types';
import { getSteadfastStatus } from '../services/steadfast';

const TrackOrder: React.FC = () => {
  const navigate = useNavigate();
  const { id } = useParams();
  const [order, setOrder] = useState<Order | null>(null);
  const [loading, setLoading] = useState(true);
  const [sfStatus, setSfStatus] = useState<string>('');

  useEffect(() => {
    const fetchData = async () => {
      if (!id) return;
      try {
        const snap = await getDoc(doc(db, 'orders', id));
        if (snap.exists()) {
          const orderData = { id: snap.id, ...snap.data() } as Order;
          setOrder(orderData);

          if (orderData.steadfastId) {
            const result = await getSteadfastStatus(orderData.steadfastId);
            // documentation says response format: { status: 200, delivery_status: "..." }
            if (result && result.status === 200 && result.delivery_status) {
                setSfStatus(result.delivery_status);

                // If local status differs from courier status, sync it
                if (result.delivery_status !== orderData.status) {
                    await updateDoc(doc(db, 'orders', id), { 
                        status: result.delivery_status,
                        steadfastStatus: result.delivery_status 
                    });
                    setOrder(prev => prev ? { ...prev, status: result.delivery_status } : null);
                }
            }
          }
        }
      } catch (e) {
        console.error("Error tracking order", e);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [id]);

  if (loading) return (
    <div className="h-screen flex items-center justify-center bg-white">
       <div className="w-8 h-8 border-4 border-black border-t-transparent rounded-full animate-spin"></div>
    </div>
  );

  if (!order) return (
    <div className="h-screen flex flex-col items-center justify-center p-10 text-center">
       <p className="font-bold mb-4">No tracking data found.</p>
       <button onClick={() => navigate('/')} className="btn-primary w-full">Back to Home</button>
    </div>
  );

  const steps = [
    { key: OrderStatus.PENDING, label: 'Order Received', active: true },
    { key: 'processing', label: 'Processing', active: ['processing', 'in_review', 'shipped', 'delivered'].includes(order.status.toLowerCase()) },
    { key: 'shipped', label: 'With Courier', active: ['shipped', 'delivered', 'partial_delivered'].includes(order.status.toLowerCase()) },
    { key: 'delivered', label: 'Delivered', active: ['delivered', 'partial_delivered'].includes(order.status.toLowerCase()) }
  ];

  return (
    <div className="p-6 pb-24 animate-fade-in min-h-screen bg-white max-w-md mx-auto">
       <div className="flex items-center space-x-4 mb-8">
          <button onClick={() => navigate(-1)} className="p-3 bg-f-gray rounded-2xl">
             <svg className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5L8.25 12l7.5-7.5" /></svg>
          </button>
          <h1 className="text-xl font-bold tracking-tight">Track Order</h1>
       </div>

       <div className="space-y-4 mb-10">
          {order.items.map((item, idx) => (
            <div key={idx} className="bg-f-gray p-4 rounded-[28px] flex items-center space-x-4 border border-f-light">
              <div className="w-14 h-14 bg-white rounded-xl overflow-hidden p-1 shadow-sm shrink-0">
                 <img src={item.image} className="w-full h-full object-contain" alt="" />
              </div>
              <div className="flex-1 min-w-0">
                 <h4 className="font-bold text-xs truncate">{item.name}</h4>
                 <p className="text-[10px] text-f-gray font-bold uppercase tracking-wider">Qty: {item.quantity} | ৳{item.priceAtPurchase}</p>
              </div>
            </div>
          ))}
       </div>

       <div className="space-y-8 mb-10 pl-8 border-l-2 border-f-gray relative ml-4 mt-6">
          {steps.map((step, i) => (
             <div key={i} className="relative">
                <div className={`absolute -left-[41px] top-0 w-5 h-5 rounded-full border-4 border-white z-10 ${step.active ? 'bg-black shadow-lg shadow-black/20' : 'bg-gray-200'}`}></div>
                <div className="flex justify-between items-start">
                   <div>
                      <h4 className={`font-bold text-sm mb-1 ${step.active ? 'text-black' : 'text-gray-300 opacity-60'}`}>{step.label}</h4>
                      <p className="text-[9px] text-f-gray font-bold uppercase tracking-widest">Sync Active</p>
                   </div>
                   {step.active && (
                      <div className="bg-green-50 text-green-600 p-1 rounded-lg">
                        <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"/></svg>
                      </div>
                   )}
                </div>
             </div>
          ))}
       </div>

       <div className="bg-f-gray p-6 rounded-[32px] border border-f-light">
          <div className="flex justify-between items-center mb-6">
             <h4 className="font-bold text-[10px] text-f-gray uppercase tracking-widest">Shipping Info</h4>
             <span className="bg-white px-3 py-1 rounded-xl text-[9px] font-bold uppercase tracking-tighter">Courier Sync</span>
          </div>
          <div className="space-y-4">
             <div className="flex justify-between items-center">
                <span className="text-[10px] font-bold text-f-gray uppercase">Provider</span>
                <span className="text-xs font-bold">Steadfast / Packzy</span>
             </div>
             <div className="flex justify-between items-center">
                <span className="text-[10px] font-bold text-f-gray uppercase">Courier Code</span>
                <span className="text-xs font-mono font-bold">{order.steadfastId || 'Preparing...'}</span>
             </div>
             <div className="flex justify-between items-center pt-4 border-t border-white/50">
                <span className="text-[10px] font-bold text-f-gray uppercase">Latest Status</span>
                <span className="text-xs font-bold text-blue-600 bg-blue-50 px-3 py-1 rounded-xl uppercase">{sfStatus || order.status}</span>
             </div>
          </div>
       </div>
    </div>
  );
};

