import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { auth, db } from '../firebase';
import { deleteUser } from 'firebase/auth';
import { doc, deleteDoc } from 'firebase/firestore';
import { useNotify } from '../components/Notifications';

const Settings: React.FC = () => {
  const navigate = useNavigate();
  const notify = useNotify();
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const handleDeleteAccount = async () => {
    const user = auth.currentUser;
    if (!user) return;

    setIsDeleting(true);
    try {
      // 1. Delete Firestore User Doc
      await deleteDoc(doc(db, 'users', user.uid));
      // 2. Delete Auth Account
      await deleteUser(user);

      notify("Account permanently deleted", "info");
      navigate('/auth-selector');
    } catch (err: any) {
      if (err.code === 'auth/requires-recent-login') {
        notify("Session expired. Please re-login to delete account.", "error");
        await auth.signOut();
        navigate('/signin');
      } else {
        notify("Process failed", "error");
      }
    } finally {
      setIsDeleting(false);
    }
  };

  const options = [
    { label: 'Notification Settings', path: '/notifications', icon: 'fas fa-bell' },
    { label: 'Password Manager', path: '/settings/password', icon: 'fas fa-lock' },
    { label: 'Privacy Policy', path: '/privacy', icon: 'fas fa-shield-alt' },
    { label: 'Delete Account', path: 'DELETE', danger: true, icon: 'fas fa-trash-alt' }
  ];

  return (
    <div className="p-6 pb-24 animate-fade-in min-h-screen bg-white max-w-md mx-auto">
       <div className="flex items-center space-x-4 mb-8">
          <button onClick={() => navigate(-1)} className="p-3 bg-f-gray rounded-2xl">
             <i className="fas fa-chevron-left text-sm"></i>
          </button>
          <h1 className="text-xl font-bold">Account Settings</h1>
       </div>

       <div className="space-y-4">
          {options.map((opt, i) => (
            <button 
               key={i} 
               onClick={() => opt.path === 'DELETE' ? setShowDeleteModal(true) : navigate(opt.path)}
               className={`w-full flex justify-between items-center p-5 bg-white border border-f-light rounded-[32px] hover:bg-f-gray transition-colors active:scale-95 ${opt.danger ? 'text-red-500 border-red-50 bg-red-50/10' : ''}`}
            >
               <div className="flex items-center space-x-4">
                  <i className={`${opt.icon} text-xs opacity-60`}></i>
                  <span className="font-bold text-sm">{opt.label}</span>
               </div>
               <i className="fas fa-chevron-right text-[10px] opacity-20"></i>
            </button>
          ))}
       </div>

       {showDeleteModal && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[1000] flex items-center justify-center p-8 animate-fade-in">
             <div className="bg-white rounded-[40px] p-8 w-full shadow-2xl border border-white/20">
                <div className="w-16 h-16 bg-red-50 text-red-500 rounded-3xl flex items-center justify-center mx-auto mb-6">
                   <i className="fas fa-exclamation-triangle text-2xl"></i>
                </div>
                <h3 className="text-xl font-bold text-center mb-2">Wait, are you sure?</h3>
                <p className="text-xs text-f-gray text-center font-medium leading-relaxed mb-8 px-4">
                   Deleting your account is permanent. All your order history and profile data will be erased from our database.
                </p>
                <div className="space-y-3">
                   <button 
                      disabled={isDeleting}
                      onClick={handleDeleteAccount}
                      className="w-full py-4 bg-red-500 text-white rounded-2xl font-bold text-xs uppercase tracking-widest active:scale-[0.98] transition-all disabled:opacity-50"
                   >
                      {isDeleting ? 'Deleting...' : 'Permanently Delete'}
                   </button>
                   <button 
                      onClick={() => setShowDeleteModal(false)}
                      className="w-full py-4 bg-f-gray text-black rounded-2xl font-bold text-xs uppercase tracking-widest active:scale-[0.98]"
                   >
                      Keep Account
                   </button>
                </div>
             </div>
          </div>
       )}
    </div>
  );
};

export default Settings;

import React, { useState, useRef, useEffect } from 'react';
import { UserProfile } from '../types';
import { useNavigate, Link } from 'react-router-dom';
import { auth, db } from '../firebase';
import { signOut, updateProfile } from 'firebase/auth';
import { doc, updateDoc } from 'firebase/firestore';
import { useNotify } from '../components/Notifications';
import { uploadToImgbb } from '../services/imgbb';

const Profile: React.FC<{ userData: UserProfile | null }> = ({ userData: initialUserData }) => {
  const navigate = useNavigate();
  const notify = useNotify();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [updating, setUpdating] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [localUserData, setLocalUserData] = useState<UserProfile | null>(initialUserData);
  const [editName, setEditName] = useState(initialUserData?.displayName || '');

  useEffect(() => {
    setLocalUserData(initialUserData);
    setEditName(initialUserData?.displayName || '');
  }, [initialUserData]);

  const handleUpdateProfile = async () => {
    if (!auth.currentUser || !editName.trim()) return;
    setUpdating(true);
    try {
      await updateProfile(auth.currentUser, { displayName: editName.trim() });
      await updateDoc(doc(db, 'users', auth.currentUser.uid), { displayName: editName.trim() });
      setLocalUserData(prev => prev ? { ...prev, displayName: editName.trim() } : null);
      notify("Identity updated", "success");
      setIsEditing(false);
    } catch (e) {
      notify("Sync failed", "error");
    } finally {
      setUpdating(false);
    }
  };

  const handleLogout = async () => {
    try {
        await signOut(auth);
        localStorage.removeItem('f_cart');
        localStorage.removeItem('vibe_recent_searches');
        navigate('/auth-selector');
    } catch (error) {
        console.error("Logout error", error);
    }
  };

  const menuItems = [
    { label: 'Purchases', icon: 'fas fa-shopping-bag', path: '/orders' },
    { label: 'Payment Hub', icon: 'fas fa-credit-card', path: '/payment-methods' },
    { label: 'Settings', icon: 'fas fa-cog', path: '/settings' },
    { label: 'Support Desk', icon: 'fas fa-headset', path: '/help-center' }
  ];

  return (
    <div className="p-6 pb-24 animate-fade-in bg-white max-w-md mx-auto min-h-screen">
       {localUserData ? (
          <>
            <div className="flex flex-col items-center mb-12">
              <div className="relative mb-6">
                <div className="w-28 h-28 rounded-[40px] bg-f-gray border-4 border-white shadow-2xl overflow-hidden ring-1 ring-gray-100">
                   <img src={localUserData?.photoURL || `https://ui-avatars.com/api/?name=${localUserData.displayName}&background=f3f3f3&color=000`} className="w-full h-full object-cover" alt="" />
                </div>
                <button 
                    onClick={() => fileInputRef.current?.click()}
                    disabled={updating}
                    className="absolute -bottom-2 -right-2 w-10 h-10 bg-black rounded-2xl flex items-center justify-center border-4 border-white shadow-lg active:scale-95 transition-transform"
                >
                    <i className="fas fa-camera text-white text-xs"></i>
                </button>
                <input type="file" hidden ref={fileInputRef} onChange={async (e) => {
                    const file = e.target.files?.[0];
                    if (!file || !auth.currentUser) return;
                    setUpdating(true);
                    try {
                        const url = await uploadToImgbb(file);
                        await updateProfile(auth.currentUser, { photoURL: url });
                        await updateDoc(doc(db, 'users', auth.currentUser.uid), { photoURL: url });
                        setLocalUserData(prev => prev ? { ...prev, photoURL: url } : null);
                        notify("Avatar updated", "success");
                    } catch(e) { notify("Upload failed", "error"); } finally { setUpdating(false); }
                }} accept="image/*" />
              </div>

              <div className="text-center">
                 <h2 className="text-2xl font-bold tracking-tight mb-1">{localUserData?.displayName}</h2>
                 <p className="text-[10px] font-bold text-f-gray uppercase tracking-widest opacity-60">{localUserData?.email}</p>
              </div>
           </div>

           <div className="space-y-4">
              {menuItems.map((item, idx) => (
                <Link 
                  key={idx} 
                  to={item.path} 
                  className="flex justify-between items-center p-5 bg-white border border-f-light rounded-[32px] hover:bg-f-gray transition-all active:scale-[0.98]"
                >
                   <div className="flex items-center space-x-4">
                      <div className="w-10 h-10 bg-f-gray rounded-2xl flex items-center justify-center">
                        <i className={`${item.icon} text-sm`}></i>
                      </div>
                      <span className="font-bold text-sm">{item.label}</span>
                   </div>
                   <i className="fas fa-chevron-right text-[10px] text-gray-300"></i>
                </Link>
              ))}

              <button 
                onClick={handleLogout}
                className="w-full flex justify-between items-center p-5 text-red-500 bg-red-50/10 border border-red-50 rounded-[32px] active:scale-[0.98] transition-all"
              >
                 <div className="flex items-center space-x-4">
                    <div className="w-10 h-10 bg-red-50 rounded-2xl flex items-center justify-center">
                        <i className="fas fa-sign-out-alt"></i>
                    </div>
                    <span className="font-bold text-sm">Log Out Terminal</span>
                 </div>
              </button>
           </div>
          </>
       ) : (
          <div className="flex flex-col items-center justify-center py-24 text-center">
             <div className="w-24 h-24 bg-f-gray rounded-[40px] flex items-center justify-center mb-8">
                <i className="fas fa-user-circle text-4xl text-gray-300"></i>
             </div>
             <h2 className="text-xl font-bold mb-2">Access Portal</h2>
             <p className="text-xs text-f-gray mb-10 px-10">Sign in to VibeGadget to manage your premium tech purchases.</p>
             <button onClick={() => navigate('/auth-selector')} className="btn-primary w-full shadow-lg">Login / Register</button>
          </div>
       )}
    </div>
  );
};

