        <Route path="/privacy" element={<PrivacyPolicy />} />

        <Route path="/shipping-address" element={<ShippingAddress />} />
        <Route path="/payment-methods" element={<PaymentMethods />} />
        <Route path="/coupon" element={<Coupon />} />
        <Route path="/add-card" element={<AddCard />} />
        <Route path="/new-password" element={<NewPassword />} />

        {/* Admin Routes */}
        <Route path="/admin" element={userData?.role === 'admin' ? <AdminDashboard /> : <Navigate to="/" />} />
        <Route path="/admin/products" element={userData?.role === 'admin' ? <ManageProducts /> : <Navigate to="/" />} />
        <Route path="/admin/users" element={userData?.role === 'admin' ? <ManageUsers /> : <Navigate to="/" />} />
        <Route path="/admin/orders" element={userData?.role === 'admin' ? <ManageOrders /> : <Navigate to="/" />} />
        <Route path="/admin/banners" element={userData?.role === 'admin' ? <ManageBanners /> : <Navigate to="/" />} />

        <Route path="*" element={<Navigate to="/" />} />
      </Routes>
      {!hideNav && <BottomNav />}
    </div>
  );
};

