  const navigate = useNavigate();
  const [messages, setMessages] = useState<{ role: 'user' | 'bot'; text: string }[]>([
    { role: 'bot', text: 'আসসালামু আলাইকুম! আমি VibeGadget AI। আপনার টেক বা গ্যাজেট সংক্রান্ত যেকোনো প্রয়োজনে আমি সাহায্য করতে পারি। আমি আপনার জন্য কি করতে পারি?' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isTyping]);

  const handleSendMessage = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage = input.trim();
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setInput('');
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: userMessage,
        config: {
          systemInstruction: `আপনি VibeGadget AI। আপনার মালিক হলো VibeGadget। আপনার লোকেশন হলো: Room Number: 54, F.T.C Market Ground Floor, Dagonbhuiyan, Feni। আপনি একজন টেক এক্সপার্ট এবং কাস্টমার সাপোর্ট এজেন্ট হিসেবে কাজ করবেন। সর্বদা বাংলায় উত্তর দিবেন এবং খুব বিনয়ী হবেন। আপনার কাজ হলো VibeGadget এর কাস্টমারদের গ্যাজেট সজেশন এবং শপ রিলেটেড তথ্য দিয়ে সাহায্য করা।`,
          temperature: 0.7,
        },
      });

      const botText = response.text || "দুঃখিত, আমি এই মুহূর্তে উত্তর দিতে পারছি না। আবার চেষ্টা করুন।";
      setMessages(prev => [...prev, { role: 'bot', text: botText }]);
    } catch (error) {
      console.error("AI Error:", error);
      setMessages(prev => [...prev, { role: 'bot', text: "নেটওয়ার্ক সমস্যার কারণে উত্তর দিতে পারছি না। অনুগ্রহ করে কিছুক্ষণ পর আবার চেষ্টা করুন।" }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="flex flex-col h-screen bg-white max-w-md mx-auto animate-fade-in">
      {/* Header */}
      <div className="px-6 py-5 flex items-center justify-between border-b border-f-light bg-white/80 backdrop-blur-md sticky top-0 z-50">
        <div className="flex items-center space-x-4">
          <button onClick={() => navigate(-1)} className="p-3 bg-f-gray rounded-2xl active:scale-90 transition-transform">
            <i className="fas fa-chevron-left text-sm"></i>
          </button>
          <div>
            <h2 className="font-bold text-base tracking-tight">Vibe AI Assistant</h2>
            <div className="flex items-center">
              <span className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse mr-2"></span>
              <span className="text-[9px] font-bold text-gray-400 uppercase tracking-widest">Active Now</span>
            </div>
          </div>
        </div>
        <button onClick={() => setMessages([{ role: 'bot', text: 'চ্যাট হিস্টোরি ক্লিয়ার করা হয়েছে। আমি আপনাকে কিভাবে সাহায্য করতে পারি?' }])} className="p-2 text-gray-300 hover:text-black">
          <i className="fas fa-redo-alt text-xs"></i>
        </button>
      </div>

      {/* Messages Area */}
      <div className="flex-1 overflow-y-auto p-6 space-y-6 no-scrollbar">
        {messages.map((msg, i) => (
          <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-fade-in`}>
            <div className={`max-w-[85%] px-5 py-4 rounded-[28px] text-sm leading-relaxed shadow-sm ${
              msg.role === 'user' 
              ? 'bg-black text-white rounded-tr-none' 
              : 'bg-f-gray text-black rounded-tl-none border border-f-light'
            }`}>
              {msg.text}
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex justify-start animate-fade-in">
            <div className="bg-f-gray px-6 py-4 rounded-[28px] rounded-tl-none flex space-x-1.5 border border-f-light">
               <div className="w-1.5 h-1.5 bg-gray-300 rounded-full animate-bounce"></div>
               <div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce delay-75"></div>
               <div className="w-1.5 h-1.5 bg-gray-300 rounded-full animate-bounce delay-150"></div>
            </div>
          </div>
        )}
        <div ref={scrollRef} />
      </div>

      {/* Input Area */}
      <div className="p-6 bg-white border-t border-f-light">
        <div className="flex items-center bg-f-gray rounded-[24px] p-2 pr-3 shadow-inner border border-f-light">
          <input 
            type="text" 
            placeholder="গ্যাজেট নিয়ে প্রশ্ন করুন..." 
            className="flex-1 bg-transparent px-4 py-3 outline-none text-sm font-medium"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSendMessage()}
          />
          <button 
            onClick={handleSendMessage}
            disabled={!input.trim() || isTyping}
            className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${
              input.trim() ? 'bg-black text-white shadow-xl scale-100' : 'bg-gray-200 text-gray-400 scale-95'
            }`}
          >
            <i className="fas fa-paper-plane text-sm"></i>
          </button>
        </div>
        <p className="text-[8px] text-center mt-4 text-f-gray font-bold uppercase tracking-[0.2em] opacity-40">Powered by Vibe AI - Dagonbhuiyan, Feni</p>
      </div>
    </div>
  );
};

