      <div className="columns-2 gap-4 space-y-4">
        {filteredProducts.map((product, index) => (
          <Link 
            to={`/product/${product.id}`} 
            key={product.id} 
            className="block break-inside-avoid animate-fade-in group"
            style={{ animationDelay: `${index * 50}ms` }}
