};

export default Home;

import React, { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { GoogleGenAI, LiveServerMessage, Modality } from "@google/genai";
import { useNotify } from '../components/Notifications';

// Local interface for GenAI media parts as the SDK might not export it directly as 'Blob'
interface GenAIBlob {
  data: string;
  mimeType: string;
}

const AIChat: React.FC = () => {
  const navigate = useNavigate();
  const notify = useNotify();
  const [messages, setMessages] = useState<{ role: 'user' | 'bot'; text: string; isThinking?: boolean }[]>([
    { role: 'bot', text: 'আসসালামু আলাইকুম! আমি Vibe AI। আপনার গ্যাজেট সংক্রান্ত যেকোনো প্রয়োজনে আমি সাহায্য করতে পারি। আমি কি আপনাকে ভয়েস অথবা টেক্সটের মাধ্যমে সাহায্য করবো?' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isLiveMode, setIsLiveMode] = useState(false);
  const [useThinking, setUseThinking] = useState(true);

  // Transcription States
  const [isRecording, setIsRecording] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);

  const scrollRef = useRef<HTMLDivElement>(null);

  // Audio & Live API Refs
  const sessionRef = useRef<any>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isTyping]);

  useEffect(() => {
    return () => {
      stopLiveSession();
    };
  }, []);

  // Utility Functions for Audio
  function encode(bytes: Uint8Array) {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  }

  function decode(base64: string) {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  }

  async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  }

  const blobToBase64 = (blob: Blob): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = (reader.result as string).split(',')[1];
        resolve(base64String);
      };
      reader.onerror = reject;
      reader.readAsDataURL(blob);
    });
  };

  // Transcription Feature
  const startRecording = async () => {
    if (isLiveMode) stopLiveSession();
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      chunksRef.current = [];

      mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunksRef.current.push(e.data);
      };

      mediaRecorder.onstop = async () => {
        const audioBlob = new Blob(chunksRef.current, { type: 'audio/webm' });
        const base64 = await blobToBase64(audioBlob);
        transcribeAudio(base64);
      };

      mediaRecorder.start();
      setIsRecording(true);
    } catch (err) {
      notify("Microphone access denied", "error");
    }
  };

  const stopRecording = () => {
    mediaRecorderRef.current?.stop();
    setIsRecording(false);
  };

  const transcribeAudio = async (base64: string) => {
    setIsTyping(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          { text: "Please transcribe the following audio accurately into Bengali text if spoken in Bengali, or English if spoken in English. Only return the transcribed text." },
          { inlineData: { data: base64, mimeType: 'audio/webm' } }
        ]
      });
      const transcribedText = response.text || "";
      if (transcribedText.trim()) {
        setInput(transcribedText);
      } else {
        notify("Could not understand the audio", "info");
      }
    } catch (error) {
      notify("Transcription failed", "error");
    } finally {
      setIsTyping(false);
    }
  };

  // Live Mode Features
  const startLiveSession = async () => {
    if (isRecording) stopRecording();
    setIsLiveMode(true);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });

    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

    const sessionPromise = ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      callbacks: {
        onopen: () => {
          const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
          const scriptProcessor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
          scriptProcessor.onaudioprocess = (e) => {
            const inputData = e.inputBuffer.getChannelData(0);
            const l = inputData.length;
            const int16 = new Int16Array(l);
            for (let i = 0; i < l; i++) int16[i] = inputData[i] * 32768;
            const pcmBlob: GenAIBlob = {
              data: encode(new Uint8Array(int16.buffer)),
              mimeType: 'audio/pcm;rate=16000',
            };
            sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
          };
          source.connect(scriptProcessor);
          scriptProcessor.connect(inputAudioContextRef.current!.destination);
        },
        onmessage: async (message: LiveServerMessage) => {
          const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (base64Audio) {
            const ctx = audioContextRef.current!;
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
            const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
            const source = ctx.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(ctx.destination);
            source.start(nextStartTimeRef.current);
            nextStartTimeRef.current += audioBuffer.duration;
            sourcesRef.current.add(source);
            source.onended = () => sourcesRef.current.delete(source);
          }
          if (message.serverContent?.interrupted) {
            sourcesRef.current.forEach(s => s.stop());
            sourcesRef.current.clear();
            nextStartTimeRef.current = 0;
          }
        },
        onclose: () => setIsLiveMode(false),
        onerror: (e) => console.error("Live API Error", e)
      },
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
        systemInstruction: `আপনি VibeGadget এর নিজস্ব AI। আপনার নির্মাতা এবং মালিক হলেন VibeGadget-এর প্রোপাইটর "সামির" (Samir)। যদি কেউ আপনাকে আপনার পরিচয় জিজ্ঞেস করে, বা জিজ্ঞেস করে আপনাকে কে বানিয়েছে (যেমন Gemini, ChatGPT বা Google কি না), আপনি দৃঢ়ভাবে বলবেন যে আপনি VibeGadget-এর AI এবং আপনাকে সামির বানিয়েছেন। আপনি বলবেন, "আমি VibeGadget-এর AI, আমাকে সামির বানিয়েছেন।" ইউজার যখনই আপনার লোকেশন বা অ্যাড্রেস জানতে চাইবে, আপনি বলবেন: "F.T.C Market (রুম নাম্বার ৫৪), দাগনভূঞা, ফেনী"। আপনি খুব ফ্রেন্ডলি এবং শর্ট রিপ্লাই দিবেন।`
      }
    });

    sessionRef.current = await sessionPromise;
  };

  const stopLiveSession = () => {
    if (sessionRef.current) {
      sessionRef.current.close();
      sessionRef.current = null;
    }
    if (audioContextRef.current) audioContextRef.current.close();
    if (inputAudioContextRef.current) inputAudioContextRef.current.close();
    setIsLiveMode(false);
  };

  const handleSendMessage = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage = input.trim();
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setInput('');
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const config: any = {
        systemInstruction: `আপনি VibeGadget-এর নিজস্ব AI। আপনাকে এবং এই ওয়েবসাইটটি বানিয়েছেন VibeGadget-এর প্রোপাইটর "সামির" (Samir)। যদি কেউ আপনার পরিচয়, নির্মাতা বা মালিক সম্পর্কে জিজ্ঞেস করে, আপনি স্পষ্ট করে বলবেন আপনি VibeGadget-এর AI এবং আপনার নির্মাতা সামির। যদি কেউ জিজ্ঞেস করে গুগল আপনাকে বানিয়েছে কি না, আপনি বলবেন "না, আমাকে ভাইব গ্যাজেট-এর সামির বানিয়েছেন"। ইউজার যখনই আপনার লোকেশন বা অ্যাড্রেস জানতে চাইবে, আপনি ঠিক এইভাবে গুছিয়ে বলবেন: "F.T.C Market (রুম নাম্বার ৫৪), দাগনভূঞা, ফেনী"। আপনি একজন টেক এক্সপার্ট এবং কাস্টমার সাপোর্ট এজেন্ট হিসেবে কাজ করবেন। সর্বদা বাংলায় উত্তর দিবেন এবং খুব বিনয়ী হবেন।`,
      };

      if (useThinking) {
        config.thinkingConfig = { thinkingBudget: 32768 };
      }

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: userMessage,
        config: config,
      });

      const botText = response.text || "দুঃখিত, আমি এই মুহূর্তে উত্তর দিতে পারছি না।";
      setMessages(prev => [...prev, { role: 'bot', text: botText, isThinking: useThinking }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'bot', text: "নেটওয়ার্ক সমস্যার কারণে উত্তর দিতে পারছি না।" }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="flex flex-col h-screen bg-[#FDFDFD] max-w-5xl mx-auto animate-fade-in relative overflow-hidden shadow-2xl">
      {/* Header */}
      <div className="px-6 md:px-10 py-6 flex items-center justify-between border-b border-f-light bg-white/95 backdrop-blur-xl sticky top-0 z-50">
        <div className="flex items-center space-x-5">
          <button onClick={() => navigate(-1)} className="p-3.5 bg-f-gray rounded-2xl active:scale-90 transition-transform hover:bg-black hover:text-white shadow-sm">
            <i className="fas fa-chevron-left text-sm"></i>
          </button>
          <div>
            <h2 className="font-bold text-lg md:text-xl tracking-tight">Vibe Advanced AI</h2>
            <div className="flex items-center">
              <span className={`w-2 h-2 rounded-full animate-pulse mr-2 ${isLiveMode ? 'bg-red-500' : 'bg-green-500'}`}></span>
              <span className="text-[10px] md:text-xs font-bold text-gray-400 uppercase tracking-widest">
                {isLiveMode ? 'Live Voice Mode' : 'Ready to help'}
              </span>
            </div>
          </div>
        </div>

        <div className="flex items-center space-x-4">
          <button 
            onClick={() => setUseThinking(!useThinking)}
            className={`px-5 py-2.5 rounded-full text-[10px] md:text-xs font-bold uppercase tracking-widest transition-all ${useThinking ? 'bg-black text-white shadow-xl shadow-black/20' : 'bg-f-gray text-gray-400 hover:text-black'}`}
          >
            {useThinking ? 'Thinking On' : 'Standard Mode'}
          </button>
        </div>
      </div>

      {/* Live Audio Visualizer Overlay */}
      {isLiveMode && (
        <div className="absolute inset-x-0 top-[88px] bottom-0 bg-black/98 z-40 flex flex-col items-center justify-center p-10 animate-fade-in">
          <div className="w-56 h-56 md:w-72 md:h-72 rounded-full border-4 border-white/10 flex items-center justify-center relative shadow-[0_0_100px_rgba(255,255,255,0.1)]">
            <div className="absolute inset-0 bg-white/5 rounded-full animate-ping"></div>
            <div className="absolute inset-6 bg-white/10 rounded-full animate-pulse"></div>
            <i className="fas fa-microphone text-5xl md:text-7xl text-white"></i>
          </div>
          <h3 className="text-white text-xl md:text-2xl font-bold mt-16 tracking-tight text-center">Vibe Live AI is listening...</h3>
          <p className="text-white/40 text-[11px] md:text-xs uppercase font-bold tracking-[0.4em] mt-6">Conversational Neural Mode Active</p>
          <button 
            onClick={stopLiveSession}
            className="mt-24 btn-primary bg-white text-black px-16 py-5 shadow-[0_30px_60px_rgba(255,255,255,0.2)] active:scale-95 transition-transform font-bold"
          >
            End Conversation
          </button>
        </div>
      )}

      {/* Messages Area */}
      <div className="flex-1 overflow-y-auto p-6 md:p-12 space-y-10 no-scrollbar bg-[#FAFAFA]">
        {messages.map((msg, i) => (
          <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-fade-in`}>
            <div className={`max-w-[90%] md:max-w-[70%] px-7 py-5 rounded-[40px] text-sm md:text-base leading-relaxed shadow-sm relative ${
              msg.role === 'user' 
              ? 'bg-black text-white rounded-tr-none shadow-2xl shadow-black/10' 
              : 'bg-white text-black rounded-tl-none border border-f-light'
            }`}>
              {msg.isThinking && msg.role === 'bot' && (
                <div className="flex items-center space-x-2 mb-3 opacity-40">
                  <i className="fas fa-brain text-[10px]"></i>
                  <span className="text-[8px] md:text-[10px] font-bold uppercase tracking-[0.2em]">Neural reasoning complete</span>
                </div>
              )}
              {msg.text}
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex justify-start animate-fade-in">
            <div className="bg-white px-8 py-6 rounded-[40px] rounded-tl-none flex flex-col space-y-3 border border-f-light shadow-sm">
               <div className="flex space-x-2">
                  <div className="w-2 h-2 bg-gray-300 rounded-full animate-bounce"></div>
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce delay-75"></div>
                  <div className="w-2 h-2 bg-gray-300 rounded-full animate-bounce delay-150"></div>
               </div>
               {useThinking && !isRecording && (
                 <span className="text-[8px] md:text-[10px] font-bold text-gray-400 uppercase tracking-widest animate-pulse">Advanced reasoning in progress...</span>
               )}
               {isRecording && (
                 <span className="text-[8px] md:text-[10px] font-bold text-red-400 uppercase tracking-widest animate-pulse">Recording Neural Input...</span>
               )}
            </div>
          </div>
        )}
        <div ref={scrollRef} />
