import React, { useState, createContext, useContext } from 'react';

type ToastType = 'success' | 'error' | 'info';

interface Toast {
  id: number;
  message: string;
  type: ToastType;
}

interface ConfirmOptions {
  title: string;
  message: string;
  onConfirm: () => void;
  onCancel?: () => void;
  confirmText?: string;
  cancelText?: string;
}

interface ToastContextType {
  notify: (message: string, type?: ToastType) => void;
  confirm: (options: ConfirmOptions) => void;
}

const ToastContext = createContext<ToastContextType | undefined>(undefined);

export const ToastProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [confirmModal, setConfirmModal] = useState<ConfirmOptions | null>(null);

  const notify = (message: string, type: ToastType = 'info') => {
    const id = Date.now();
    setToasts((prev) => [...prev, { id, message, type }]);
    setTimeout(() => {
      setToasts((prev) => prev.filter((t) => t.id !== id));
    }, 4000);
  };

  const confirm = (options: ConfirmOptions) => {
    setConfirmModal(options);
  };

  return (
    <ToastContext.Provider value={{ notify, confirm }}>
      {children}

      {/* Toasts */}
      <div className="fixed top-5 right-5 z-[9999] flex flex-col gap-3 max-w-[90%] md:max-w-md">
        {toasts.map((toast) => (
          <div
            key={toast.id}
            className={`px-6 py-4 rounded-2xl shadow-2xl flex items-center justify-between min-w-[300px] animate-fade-in 
              ${toast.type === 'success' ? 'bg-black border border-white/20' : toast.type === 'error' ? 'bg-red-600' : 'bg-[#1F2029]'} 
              text-white transition-all`}
          >
            <p className="font-bold text-sm">{toast.message}</p>
            <button onClick={() => setToasts(prev => prev.filter(t => t.id !== toast.id))} className="ml-4 opacity-70 hover:opacity-100">
              ✕
            </button>
          </div>
        ))}
      </div>

      {/* Confirmation Modal */}
      {confirmModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[10000] flex items-center justify-center p-8 animate-fade-in">
          <div className="bg-white rounded-[40px] p-8 w-full max-w-sm shadow-2xl border border-white/20 text-center">
            <div className="w-16 h-16 bg-f-gray rounded-3xl flex items-center justify-center mx-auto mb-6">
               <i className="fas fa-question text-2xl text-black"></i>
            </div>
            <h3 className="text-xl font-bold mb-2 tracking-tight">{confirmModal.title}</h3>
            <p className="text-[11px] text-f-gray font-medium leading-relaxed mb-8 px-2">{confirmModal.message}</p>
            <div className="space-y-3">
              <button 
                onClick={() => { confirmModal.onConfirm(); setConfirmModal(null); }}
                className="w-full py-4 bg-black text-white rounded-2xl font-bold text-xs uppercase tracking-widest active:scale-[0.98] shadow-xl shadow-black/10"
              >
                {confirmModal.confirmText || 'Confirm'}
              </button>
              <button 
                onClick={() => { if(confirmModal.onCancel) confirmModal.onCancel(); setConfirmModal(null); }}
                className="w-full py-4 text-gray-400 font-bold text-[10px] uppercase tracking-widest active:scale-[0.98]"
              >
                {confirmModal.cancelText || 'Cancel'}
              </button>
            </div>
          </div>
        </div>
      )}
    </ToastContext.Provider>
  );
};

export const useNotify = () => {
  const context = useContext(ToastContext);
  if (!context) throw new Error("useNotify must be used within ToastProvider");
  return context.notify;
};

export const useConfirm = () => {
  const context = useContext(ToastContext);
  if (!context) throw new Error("useConfirm must be used within ToastProvider");
  return context.confirm;
};

import React, { useState, useEffect } from 'react';
import { collection, addDoc, getDocs, deleteDoc, doc, updateDoc } from 'firebase/firestore';
import { db } from '../../firebase';
import { uploadToImgbb } from '../../services/imgbb';
import { useNotify, useConfirm } from '../../components/Notifications';
import { Product } from '../../types';

const ManageProducts: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const notify = useNotify();
  const confirm = useConfirm();

  const [formData, setFormData] = useState({
    name: '',
    price: 0,
    description: '',
    category: 'Mobile',
    stock: 10,
    imageFiles: [] as File[]
  });

  const fetchProducts = async () => {
    const snap = await getDocs(collection(db, 'products'));
    setProducts(snap.docs.map(d => ({ id: d.id, ...d.data() } as Product)));
  };

  useEffect(() => { fetchProducts(); }, []);

  const handleEdit = (product: Product) => {
    setEditingId(product.id);
    setFormData({
      name: product.name,
      price: product.price,
      description: product.description,
      category: product.category,
      stock: product.stock,
      imageFiles: []
    });
    setIsAdding(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      let imageUrls: string[] = [];
      if (formData.imageFiles.length > 0) {
        for (const file of formData.imageFiles) {
          const url = await uploadToImgbb(file);
          imageUrls.push(url);
        }
      }

      const productData: any = {
        name: formData.name,
        price: Number(formData.price),
        description: formData.description,
        category: formData.category,
        stock: Number(formData.stock),
      };

      if (imageUrls.length > 0) {
        productData.image = imageUrls[0];
        productData.images = imageUrls;
      }

      if (editingId) {
        await updateDoc(doc(db, 'products', editingId), productData);
        notify("Product updated!", "success");
      } else {
        productData.rating = 5;
        productData.numReviews = 0;
        await addDoc(collection(db, 'products'), productData);
        notify("Product published!", "success");
      }

      setIsAdding(false);
      setEditingId(null);
      fetchProducts();
    } catch (err) {
      notify("Failed to save product", "error");
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = (id: string) => {
    confirm({
      title: "Delete Product?",
      message: "This will permanently remove the gadget from inventory.",
      onConfirm: async () => {
        await deleteDoc(doc(db, 'products', id));
        notify("Deleted", "info");
        fetchProducts();
      }
    });
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 bg-white min-h-screen">
      <div className="flex justify-between items-center mb-10">
        <h1 className="text-3xl font-bold tracking-tight">Vibe Inventory</h1>
        <button 
          onClick={() => { setIsAdding(!isAdding); setEditingId(null); }}
          className="bg-black text-white px-8 py-3 rounded-2xl font-bold uppercase text-[10px] tracking-widest shadow-xl shadow-black/20 active:scale-95 transition-all"
        >
          {isAdding ? "Cancel Action" : "+ Add New Product"}
        </button>
      </div>

      {isAdding && (
        <form onSubmit={handleSubmit} className="bg-f-gray p-8 rounded-[40px] shadow-sm mb-12 space-y-6 max-w-3xl mx-auto border border-f-light animate-fade-in">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Product Name</label>
              <input 
                type="text" className="w-full p-4 bg-white rounded-2xl outline-none focus:ring-1 focus:ring-black" required
                value={formData.name}
                onChange={e => setFormData({...formData, name: e.target.value})}
              />
            </div>
            <div>
              <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Category</label>
              <select 
                className="w-full p-4 bg-white rounded-2xl outline-none focus:ring-1 focus:ring-black"
                value={formData.category}
                onChange={e => setFormData({...formData, category: e.target.value})}
              >
                <option>Mobile</option>
                <option>Accessories</option>
                <option>Gadgets</option>
                <option>Chargers</option>
              </select>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-6">
            <div>
              <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Price (৳)</label>
              <input 
                type="number" className="w-full p-4 bg-white rounded-2xl outline-none focus:ring-1 focus:ring-black" required
                value={formData.price}
                onChange={e => setFormData({...formData, price: Number(e.target.value)})}
              />
            </div>
            <div>
              <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Stock Count</label>
              <input 
                type="number" className="w-full p-4 bg-white rounded-2xl outline-none focus:ring-1 focus:ring-black" required
                value={formData.stock}
                onChange={e => setFormData({...formData, stock: Number(e.target.value)})}
              />
            </div>
          </div>

          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Upload Assets (Multiple Supported)</label>
            <input 
              type="file" className="w-full p-4 bg-white rounded-2xl outline-none text-xs" accept="image/*" multiple
              onChange={e => {
                if (e.target.files) {
                  setFormData({...formData, imageFiles: Array.from(e.target.files)});
                }
              }}
            />
            {editingId && <p className="text-[9px] text-f-gray mt-2 uppercase font-bold">* Leave empty to keep existing images</p>}
          </div>

          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Detailed Narrative</label>
            <textarea 
              className="w-full p-4 bg-white rounded-2xl h-32 outline-none focus:ring-1 focus:ring-black"
              value={formData.description}
              onChange={e => setFormData({...formData, description: e.target.value})}
            />
          </div>

          <button 
            disabled={loading}
            className="w-full py-5 bg-black text-white rounded-3xl font-bold uppercase tracking-widest text-xs disabled:opacity-50 shadow-2xl shadow-black/10"
          >
            {loading ? "Syncing with Cloud..." : (editingId ? "Update Gadget" : "Publish to Vibe Hub")}
          </button>
        </form>
      )}

      <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-6">
        {products.map(p => (
          <div key={p.id} className="bg-f-gray rounded-[40px] p-4 flex flex-col relative group overflow-hidden border border-f-light">
             <div className="aspect-square rounded-[32px] overflow-hidden mb-4 bg-white p-2">
