             <div className="absolute inset-0 bg-black/80 flex items-center justify-center space-x-4 opacity-0 group-hover:opacity-100 transition-opacity">
                <button onClick={() => handleEdit(p)} className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-black">
                   <i className="fas fa-edit"></i>
                </button>
                <button onClick={() => handleDelete(p.id)} className="w-10 h-10 bg-red-500 rounded-xl flex items-center justify-center text-white">
                   <i className="fas fa-trash"></i>
                </button>
