           </div>

           <div className="space-y-4">
              {isAdmin && (
                <Link to="/admin" className="flex justify-between items-center p-6 bg-black text-white rounded-[40px] shadow-2xl shadow-black/20 hover:scale-[1.02] active:scale-95 transition-all">
                   <div className="flex items-center space-x-5"><div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center"><i className="fas fa-user-shield"></i></div><span className="font-bold text-sm uppercase tracking-widest">Admin Terminal</span></div>
                   <i className="fas fa-chevron-right text-xs opacity-40"></i>
                </Link>
              )}
