               </div>
            </div>
          )}

          <div className="space-y-4 pt-4 border-t border-white/40">
            <div className="flex justify-between text-[10px] font-bold opacity-40 uppercase tracking-widest">
              <span>Items Sub-Total</span>
              <span>৳{subTotal}</span>
