  const ONESIGNAL_APP_ID = "29c39d8a-7be8-404a-8a33-5616086735fa";
  const ONESIGNAL_REST_KEY = "NDdiN2YxZjEtOTU4NS00ODU1LWEwZWUtZWE2NTE1ZTEwZTIy"; // Provided key or fallback

