import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { createUserWithEmailAndPassword, updateProfile } from 'firebase/auth';
import { doc, setDoc } from 'firebase/firestore';
import { auth, db } from '../firebase';
import { useNotify } from '../components/Notifications';
import { getReadableAddress } from '../services/location';

const SignUp: React.FC = () => {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [agree, setAgree] = useState(false);
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();
  const notify = useNotify();

  const handleSignUp = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!agree) return notify("Please agree to the terms", "error");

    setLoading(true);
    try {
      const userCred = await createUserWithEmailAndPassword(auth, email, password);
      const user = userCred.user;
      await updateProfile(user, { displayName: name });

      // Sync OneSignal
      const OneSignal = (window as any).OneSignal;
      if (OneSignal) {
        OneSignal.login(user.uid);
      }

      // Metadata collection
      let networkData = { ip: '0.0.0.0', isp: 'Unknown ISP' };
      try {
        const ipRes = await fetch('https://ipapi.co/json/');
        const data = await ipRes.json();
        networkData = { ip: data.ip, isp: data.org };
      } catch (e) {
        console.error("Network meta failed:", e);
      }

      let geo = { lat: 0, lng: 0, name: 'Dhaka, Bangladesh' };
      if (navigator.geolocation) {
         navigator.geolocation.getCurrentPosition(async (pos) => {
            geo.lat = pos.coords.latitude;
            geo.lng = pos.coords.longitude;
            geo.name = await getReadableAddress(geo.lat, geo.lng);
            await setDoc(doc(db, 'users', user.uid), { 
              locationName: geo.name,
              latitude: geo.lat,
              longitude: geo.lng
            }, { merge: true });
         });
      }

      const userAgent = navigator.userAgent;
      const userData = {
        uid: user.uid,
        email,
        displayName: name,
        role: 'user',
        isBanned: false,
        createdAt: Date.now(),
        registrationDate: Date.now(),
        // Technical Meta
        ipAddress: networkData.ip,
        isp: networkData.isp,
        deviceName: navigator.platform,
        osName: userAgent.split(')')[0].split('(')[1] || 'Unknown OS',
        browserName: userAgent.split(' ').pop() || 'Unknown Browser',
        screenResolution: `${window.screen.width}x${window.screen.height}`,
        platform: navigator.platform,
        userAgent: userAgent,
      };

      await setDoc(doc(db, 'users', user.uid), userData);

      notify("Welcome to VibeGadget!", "success");
      navigate('/');
    } catch (err: any) {
      notify(err.message, "error");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-white p-8 flex flex-col animate-fade-in max-w-md mx-auto">
      <div className="flex-1">
        <h1 className="text-3xl font-bold mb-2 tracking-tighter">Create Account</h1>
        <p className="text-f-gray text-sm mb-10 font-medium">Join us for the premium tech experience.</p>

        <form onSubmit={handleSignUp} className="space-y-6">
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Full Name</label>
            <input 
              type="text" 
              placeholder="Enter your name" 
              className="w-full bg-f-gray p-4 rounded-2xl outline-none border border-transparent focus:border-black transition-all"
              value={name}
              onChange={(e) => setName(e.target.value)}
              required
            />
          </div>
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Email Address</label>
            <input 
              type="email" 
              placeholder="example@gmail.com" 
              className="w-full bg-f-gray p-4 rounded-2xl outline-none border border-transparent focus:border-black transition-all"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Password</label>
            <input 
              type="password" 
              placeholder="Create a password" 
              className="w-full bg-f-gray p-4 rounded-2xl outline-none border border-transparent focus:border-black transition-all"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>

          <div className="flex items-center space-x-3">
            <input 
              type="checkbox" 
              id="terms" 
              className="w-5 h-5 accent-black rounded-lg" 
              checked={agree}
              onChange={(e) => setAgree(e.target.checked)}
            />
            <label htmlFor="terms" className="text-[10px] font-bold uppercase tracking-widest">I agree to the <span className="underline">Terms & Conditions</span></label>
          </div>

          <button disabled={loading} className="btn-primary w-full mt-8 shadow-xl shadow-black/10 transition-transform active:scale-[0.98]">
            {loading ? "Joining..." : "Sign Up"}
          </button>
        </form>
      </div>

      <p className="mt-8 text-center text-xs font-medium">
        Already have an account? <Link to="/signin" className="font-bold underline ml-1">Log In</Link>
      </p>
    </div>
  );
};

export default SignUp;

import React, { useState, useEffect } from 'react';
import { collection, getDocs, updateDoc, doc, addDoc } from 'firebase/firestore';
import { db } from '../../firebase';
import { UserProfile } from '../../types';
import { useNotify } from '../../components/Notifications';
import { uploadToImgbb } from '../../services/imgbb';
import { useNavigate } from 'react-router-dom';

const ManageUsers: React.FC = () => {
  const navigate = useNavigate();
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [search, setSearch] = useState('');

  const [notifModal, setNotifModal] = useState<{ isOpen: boolean; uid: string | 'all'; name: string }>({ isOpen: false, uid: '', name: '' });
  const [detailModal, setDetailModal] = useState<{ isOpen: boolean; user: UserProfile | null }>({ isOpen: false, user: null });

  const [notifContent, setNotifContent] = useState({ title: '', message: '' });
  const [notifImage, setNotifImage] = useState<File | null>(null);
  const [sending, setSending] = useState(false);
  const notify = useNotify();

  const ONESIGNAL_APP_ID = "29c39d8a-7be8-404a-8a33-5616086735fa";
  const ONESIGNAL_REST_KEY = "NDdiN2YxZjEtOTU4NS00ODU1LWEwZWUtZWE2NTE1ZTEwZTIy";

  // CORS Proxy to bypass browser security for OneSignal REST API
  const proxyUrl = "https://api.allorigins.win/raw?url=";
  const osApiUrl = "https://onesignal.com/api/v1/notifications";

  const fetchUsers = async () => {
    try {
      const snap = await getDocs(collection(db, 'users'));
      const userList = snap.docs.map(d => ({ ...d.data() } as UserProfile));
      userList.sort((a, b) => (b.registrationDate || b.createdAt) - (a.registrationDate || a.createdAt));
      setUsers(userList);
    } catch (e) {
      console.error("Fetch users error:", e);
    }
  };

  useEffect(() => { fetchUsers(); }, []);

  const toggleBan = async (uid: string, currentStatus: boolean) => {
    await updateDoc(doc(db, 'users', uid), { isBanned: !currentStatus });
    notify(currentStatus ? "User access restored" : "User access suspended", "info");
    fetchUsers();
  };

  const sendNotification = async () => {
    if (!notifContent.title || !notifContent.message) return;
    setSending(true);
    try {
        let imageUrl = '';
        if (notifImage) {
            imageUrl = await uploadToImgbb(notifImage);
        }

        // 1. Save to Firestore
        await addDoc(collection(db, 'notifications'), {
            title: notifContent.title,
            message: notifContent.message,
            image: imageUrl || null,
            userId: notifModal.uid,
            read: false,
            createdAt: Date.now()
        });

        // 2. Dispatch via OneSignal (using proxy to avoid CORS 'Load failed')
        const onesignalPayload: any = {
          app_id: ONESIGNAL_APP_ID,
          headings: { en: notifContent.title },
          contents: { en: notifContent.message },
          chrome_web_image: imageUrl || undefined,
          big_picture: imageUrl || undefined,
          ios_attachments: imageUrl ? { "id1": imageUrl } : undefined,
          web_buttons: [{ id: "read-more", text: "Read More", icon: "" }]
        };

        if (notifModal.uid === 'all') {
          onesignalPayload.included_segments = ["Subscribed Users"];
        } else {
          onesignalPayload.include_external_user_ids = [notifModal.uid];
        }

        // Use a more robust proxy approach or directly try if CORS is handled.
        // For browsers, direct REST API calls usually fail without a backend.
        // Attempting with simple fetch first, if it fails, notify user.
        const osResponse = await fetch(osApiUrl, {
          method: "POST",
          headers: {
            "Content-Type": "application/json; charset=utf-8",
            "Authorization": `Basic ${ONESIGNAL_REST_KEY}`
          },
          body: JSON.stringify(onesignalPayload)
        }).catch(() => {
          // If direct call fails, try proxy
          return fetch(`${proxyUrl}${encodeURIComponent(osApiUrl)}`, {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              "Authorization": `Basic ${ONESIGNAL_REST_KEY}`
            },
            body: JSON.stringify(onesignalPayload)
          });
        });

        notify("Dispatch Complete: App & Push Sent!", "success");
        setNotifModal({ isOpen: false, uid: '', name: '' });
        setNotifContent({ title: '', message: '' });
        setNotifImage(null);
    } catch(e: any) {
        console.error("Notification Dispatch Error:", e);
        notify("Push failed, but internal alert saved.", "error");
    } finally {
        setSending(false);
    }
  };

  const filteredUsers = users.filter(u => 
    u.displayName?.toLowerCase().includes(search.toLowerCase()) || 
    u.email.toLowerCase().includes(search.toLowerCase()) ||
    u.ipAddress?.includes(search)
  );

  const InfoRow = ({ label, value }: { label: string; value?: string | number }) => (
    <div className="flex flex-col space-y-1 py-3 border-b border-gray-50 last:border-0">
      <span className="text-[9px] font-bold text-gray-400 uppercase tracking-widest">{label}</span>
      <span className="text-xs font-bold text-black break-all">{value || 'Not Captured'}</span>
    </div>
  );

  return (
    <div className="max-w-7xl mx-auto px-6 py-10 bg-white min-h-screen">
      <div className="flex justify-between items-center mb-10">
        <div className="flex items-center space-x-4">
           <button onClick={() => navigate(-1)} className="p-3 bg-f-gray rounded-2xl active:scale-90 transition-all shadow-sm">
             <i className="fas fa-chevron-left text-sm"></i>
           </button>
           <div>
              <h1 className="text-3xl font-bold tracking-tight">System Users</h1>
              <p className="text-xs text-f-gray font-bold uppercase tracking-widest mt-1">Deep Metadata & Surveillance</p>
           </div>
        </div>
        <button 
           onClick={() => setNotifModal({ isOpen: true, uid: 'all', name: 'Global Broadcast' })}
           className="px-6 py-3 bg-black text-white rounded-2xl text-[10px] font-bold uppercase tracking-widest shadow-xl shadow-black/10 active:scale-95 transition-transform"
        >
           Broadcast Alert
        </button>
      </div>

      <div className="relative mb-8">
        <input 
          type="text" 
          placeholder="Search name, email, IP or device..." 
          className="w-full p-5 bg-f-gray rounded-[24px] outline-none border border-transparent focus:border-black transition-all font-medium text-sm pl-14 shadow-inner"
          value={search}
          onChange={e => setSearch(e.target.value)}
        />
        <i className="fas fa-search absolute left-5 top-1/2 -translate-y-1/2 text-gray-400"></i>
      </div>

      <div className="bg-f-gray rounded-[40px] overflow-hidden border border-f-light shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="text-[10px] font-bold uppercase tracking-[0.2em] text-gray-400">
              <tr className="border-b border-white/50">
                <th className="px-8 py-6">Identity</th>
