import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { signInWithEmailAndPassword } from 'firebase/auth';
import { auth, db } from '../firebase';
import { doc, updateDoc } from 'firebase/firestore';
import { useNotify } from '../components/Notifications';
import { getReadableAddress } from '../services/location';

const SignIn: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();
  const notify = useNotify();

  const handleSignIn = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const userCred = await signInWithEmailAndPassword(auth, email, password);
      const user = userCred.user;

      // Sync OneSignal External ID
      const OneSignal = (window as any).OneSignal;
      if (OneSignal) {
        OneSignal.login(user.uid);
      }

      // Collect Meta Data with resilient fetch
      let networkData = { ip: '0.0.0.0', isp: 'Unknown Network' };
      try {
        // Try multiple IP services in case one is blocked
        const ipRes = await fetch('https://api.ipify.org?format=json').catch(() => fetch('https://ipapi.co/json/'));
        const data = await ipRes.json();
        networkData.ip = data.ip || '0.0.0.0';
        if (data.org || data.isp) networkData.isp = data.org || data.isp;
      } catch (e) {
        console.warn("Network meta fallback triggered");
      }

      const userAgent = navigator.userAgent;
      const deviceMeta = {
        ipAddress: networkData.ip,
        isp: networkData.isp,
        deviceName: navigator.platform,
        osName: userAgent.split(')')[0].split('(')[1] || 'Unknown OS',
        browserName: userAgent.split(' ').pop() || 'Browser',
        screenResolution: `${window.screen.width}x${window.screen.height}`,
        platform: navigator.platform,
        userAgent: userAgent,
        lastLogin: Date.now()
      };

      await updateDoc(doc(db, 'users', user.uid), deviceMeta);

      // Handle location in background to avoid blocking sign-in
      if (navigator.geolocation) {
        navigator.geolocation.getCurrentPosition(async (pos) => {
           const lat = pos.coords.latitude;
           const lng = pos.coords.longitude;
           const name = await getReadableAddress(lat, lng);
           await updateDoc(doc(db, 'users', user.uid), { 
             locationName: name,
             latitude: lat,
             longitude: lng
           }).catch(() => {});
        });
      }

      notify("Welcome back to Vibe!", "success");
      navigate('/');
    } catch (err: any) {
      notify(err.message, "error");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-white p-8 flex flex-col animate-fade-in max-w-md mx-auto">
      <button onClick={() => navigate('/')} className="p-3 bg-f-gray rounded-2xl self-start mb-10 shadow-sm active:scale-90 transition-transform">
        <i className="fas fa-chevron-left text-sm"></i>
      </button>

      <div className="flex-1">
        <h1 className="text-3xl font-bold mb-2 tracking-tighter">Welcome Back</h1>
        <p className="text-f-gray text-sm mb-10 font-medium">Log in to your account to continue shopping.</p>

        <form onSubmit={handleSignIn} className="space-y-6">
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Email Address</label>
            <input 
              type="email" 
              placeholder="Enter your email" 
              className="w-full bg-f-gray p-5 rounded-2xl border border-transparent focus:border-black outline-none transition-all font-medium text-sm"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Password</label>
            <input 
              type="password" 
              placeholder="••••••••" 
              className="w-full bg-f-gray p-5 rounded-2xl border border-transparent focus:border-black outline-none transition-all font-medium text-sm"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>

          <button disabled={loading} className="btn-primary w-full mt-10 shadow-xl shadow-black/10 transition-transform active:scale-[0.98]">
            {loading ? "Authenticating..." : "Log In"}
          </button>
        </form>
      </div>

      <p className="mt-12 text-center text-xs font-medium">
        Don't have an account? <Link to="/signup" className="font-bold underline ml-1">Sign Up</Link>
      </p>
    </div>
  );
};

