import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { createUserWithEmailAndPassword, updateProfile } from 'firebase/auth';
import { doc, setDoc } from 'firebase/firestore';
import { auth, db } from '../firebase';
import { useNotify } from '../components/Notifications';
import { getReadableAddress } from '../services/location';

const SignUp: React.FC = () => {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [agree, setAgree] = useState(false);
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();
  const notify = useNotify();

  const handleSignUp = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!agree) return notify("Please agree to the terms", "error");

    setLoading(true);
    try {
      const userCred = await createUserWithEmailAndPassword(auth, email, password);
      const user = userCred.user;
      await updateProfile(user, { displayName: name });

      // Sync OneSignal
      const OneSignal = (window as any).OneSignal;
      if (OneSignal) {
        OneSignal.login(user.uid);
      }

      // Metadata collection with resilient fetch
      let networkData = { ip: '0.0.0.0', isp: 'Unknown Network' };
      try {
        const ipRes = await fetch('https://api.ipify.org?format=json').catch(() => fetch('https://ipapi.co/json/'));
        const data = await ipRes.json();
        networkData.ip = data.ip || '0.0.0.0';
        if (data.org || data.isp) networkData.isp = data.org || data.isp;
      } catch (e) {
        console.warn("SignUp metadata fetch issue");
      }

      const userAgent = navigator.userAgent;
      const userData = {
        uid: user.uid,
        email,
        displayName: name,
        role: 'user',
        isBanned: false,
        createdAt: Date.now(),
        registrationDate: Date.now(),
        // Technical Meta
        ipAddress: networkData.ip,
        isp: networkData.isp,
        deviceName: navigator.platform,
        osName: userAgent.split(')')[0].split('(')[1] || 'Unknown OS',
        browserName: userAgent.split(' ').pop() || 'Browser',
        screenResolution: `${window.screen.width}x${window.screen.height}`,
        platform: navigator.platform,
        userAgent: userAgent,
      };

      await setDoc(doc(db, 'users', user.uid), userData);

      // Background location fetch
      if (navigator.geolocation) {
         navigator.geolocation.getCurrentPosition(async (pos) => {
            const lat = pos.coords.latitude;
            const lng = pos.coords.longitude;
            const locName = await getReadableAddress(lat, lng);
            await setDoc(doc(db, 'users', user.uid), { 
              locationName: locName,
              latitude: lat,
              longitude: lng
            }, { merge: true }).catch(() => {});
         });
      }

      notify("Welcome to VibeGadget!", "success");
      navigate('/');
    } catch (err: any) {
      notify(err.message, "error");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-white p-8 flex flex-col animate-fade-in max-w-md mx-auto">
      <div className="flex-1">
        <h1 className="text-3xl font-bold mb-2 tracking-tighter">Create Account</h1>
        <p className="text-f-gray text-sm mb-10 font-medium">Join us for the premium tech experience.</p>

        <form onSubmit={handleSignUp} className="space-y-6">
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Full Name</label>
            <input 
              type="text" 
              placeholder="Enter your name" 
              className="w-full bg-f-gray p-4 rounded-2xl outline-none border border-transparent focus:border-black transition-all"
              value={name}
              onChange={(e) => setName(e.target.value)}
              required
            />
          </div>
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Email Address</label>
            <input 
              type="email" 
              placeholder="example@gmail.com" 
              className="w-full bg-f-gray p-4 rounded-2xl outline-none border border-transparent focus:border-black transition-all"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Password</label>
            <input 
              type="password" 
              placeholder="Create a password" 
              className="w-full bg-f-gray p-4 rounded-2xl outline-none border border-transparent focus:border-black transition-all"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>

          <div className="flex items-center space-x-3">
            <input 
              type="checkbox" 
