import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { signInWithEmailAndPassword } from 'firebase/auth';
import { auth, db } from '../firebase';
import { doc, updateDoc } from 'firebase/firestore';
import { useNotify } from '../components/Notifications';
import { getReadableAddress } from '../services/location';

const SignIn: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();
  const notify = useNotify();

  const handleSignIn = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const userCred = await signInWithEmailAndPassword(auth, email, password);
      const user = userCred.user;

      // OneSignal Sync
      const OneSignal = (window as any).OneSignal;
      if (OneSignal) OneSignal.login(user.uid);

      // 1. Fetch Network & Location Intelligence (A-Z Meta)
      let networkMeta: any = {};
      try {
        const response = await fetch('https://ipapi.co/json/');
        const data = await response.json();
        networkMeta = {
          ipAddress: data.ip || '0.0.0.0',
          isp: data.org || data.asn || 'Unknown Network',
          asn: data.asn || 'N/A',
          city: data.city || 'N/A',
          district: data.region || 'N/A',
          timeZone: data.timezone || 'UTC',
          latitude: data.latitude || 0,
          longitude: data.longitude || 0,
          locationName: `${data.city}, ${data.region}, ${data.country_name}`
        };
      } catch (err) {
        console.warn("Primary IP fetch failed, using fallback.");
        const fallback = await fetch('https://api.ipify.org?format=json');
        const fbData = await fallback.json();
        networkMeta = { ipAddress: fbData.ip, isp: 'Fallback Network' };
      }

      // 2. Hardware Fingerprinting (A-Z Specs)
      const ua = navigator.userAgent;
      const hardwareMeta = {
        platform: navigator.platform,
        language: navigator.language,
        cpuCores: navigator.hardwareConcurrency || 0,
        deviceMemory: (navigator as any).deviceMemory || 0,
        screenResolution: `${window.screen.width}x${window.screen.height}`,
        screenDepth: window.screen.colorDepth,
        userAgent: ua,
        deviceName: navigator.platform,
        osName: ua.indexOf("Win") !== -1 ? "Windows" : ua.indexOf("Mac") !== -1 ? "MacOS" : ua.indexOf("Linux") !== -1 ? "Linux" : ua.indexOf("Android") !== -1 ? "Android" : ua.indexOf("like Mac") !== -1 ? "iOS" : "Unknown OS",
        browserName: ua.includes("Chrome") ? "Chrome" : ua.includes("Firefox") ? "Firefox" : ua.includes("Safari") ? "Safari" : "Unknown Browser",
        lastLogin: Date.now(),
        lastActive: Date.now()
      };

      // 3. Persistent Sync to Firestore
      await updateDoc(doc(db, 'users', user.uid), {
        ...networkMeta,
        ...hardwareMeta
      });

      // Background High-Accuracy Location Update
      if (navigator.geolocation) {
        navigator.geolocation.getCurrentPosition(async (pos) => {
          const readable = await getReadableAddress(pos.coords.latitude, pos.coords.longitude);
          await updateDoc(doc(db, 'users', user.uid), {
            locationName: readable,
            latitude: pos.coords.latitude,
            longitude: pos.coords.longitude
          }).catch(() => {});
        });
      }

