import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { createUserWithEmailAndPassword, updateProfile } from 'firebase/auth';
import { doc, setDoc } from 'firebase/firestore';
import { auth, db } from '../firebase';
import { useNotify } from '../components/Notifications';
import { getReadableAddress } from '../services/location';

const SignUp: React.FC = () => {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [agree, setAgree] = useState(false);
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();
  const notify = useNotify();

  const handleSignUp = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!agree) return notify("Accept the terms to proceed", "error");

    setLoading(true);
    try {
      const userCred = await createUserWithEmailAndPassword(auth, email, password);
      const user = userCred.user;
      await updateProfile(user, { displayName: name });

      // OneSignal Sync
      const OneSignal = (window as any).OneSignal;
      if (OneSignal) OneSignal.login(user.uid);

      // 1. Exhaustive Network Probe
      let networkMeta: any = {};
      try {
        const response = await fetch('https://ipapi.co/json/');
        const data = await response.json();
        networkMeta = {
          ipAddress: data.ip || '0.0.0.0',
          isp: data.org || data.asn || 'Unknown Network',
          asn: data.asn || 'N/A',
          city: data.city || 'N/A',
          district: data.region || 'N/A',
          timeZone: data.timezone || 'UTC',
          latitude: data.latitude || 0,
          longitude: data.longitude || 0,
          locationName: `${data.city}, ${data.region}, ${data.country_name}`
        };
      } catch (err) {
        networkMeta = { ipAddress: '0.0.0.0', isp: 'Limited Metadata Captured' };
      }

      // 2. Comprehensive Hardware Specs
      const ua = navigator.userAgent;
      const deviceProfile = {
        platform: navigator.platform,
        language: navigator.language,
        cpuCores: navigator.hardwareConcurrency || 0,
        deviceMemory: (navigator as any).deviceMemory || 0,
        screenResolution: `${window.screen.width}x${window.screen.height}`,
        screenDepth: window.screen.colorDepth,
        userAgent: ua,
        deviceName: navigator.platform,
        osName: ua.indexOf("Win") !== -1 ? "Windows" : ua.indexOf("Mac") !== -1 ? "MacOS" : ua.indexOf("Linux") !== -1 ? "Linux" : ua.indexOf("Android") !== -1 ? "Android" : ua.indexOf("like Mac") !== -1 ? "iOS" : "Unknown OS",
        browserName: ua.includes("Chrome") ? "Chrome" : ua.includes("Firefox") ? "Firefox" : ua.includes("Safari") ? "Safari" : "Unknown Browser",
      };

      const userData = {
        uid: user.uid,
        email,
        displayName: name,
        role: 'user',
        isBanned: false,
        createdAt: Date.now(),
        registrationDate: Date.now(),
        lastActive: Date.now(),
        ...networkMeta,
        ...deviceProfile
      };

      await setDoc(doc(db, 'users', user.uid), userData);

      notify("Welcome to the Vibe Network!", "success");
      navigate('/');
    } catch (err: any) {
      notify(err.message, "error");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-white p-8 flex flex-col animate-fade-in max-w-md mx-auto">
      <div className="flex-1">
        <h1 className="text-3xl font-bold mb-2 tracking-tighter">New Node Registration</h1>
        <p className="text-f-gray text-sm mb-10 font-medium">Create your profile to start exploring premium gear.</p>

        <form onSubmit={handleSignUp} className="space-y-6">
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Display Name</label>
            <input 
              type="text" 
              placeholder="John Doe" 
              className="w-full bg-f-gray p-4 rounded-2xl outline-none focus:ring-1 focus:ring-black transition-all font-medium"
              value={name}
              onChange={(e) => setName(e.target.value)}
              required
            />
          </div>
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Email Address</label>
            <input 
              type="email" 
              placeholder="example@vibe.shop" 
              className="w-full bg-f-gray p-4 rounded-2xl outline-none focus:ring-1 focus:ring-black transition-all font-medium"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>
          <div>
            <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-2">Secure Password</label>
            <input 
              type="password" 
              placeholder="••••••••" 
              className="w-full bg-f-gray p-4 rounded-2xl outline-none focus:ring-1 focus:ring-black transition-all font-medium"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>

          <div className="flex items-center space-x-3">
            <input 
              type="checkbox" 
              id="terms" 
              className="w-5 h-5 accent-black rounded-lg" 
              checked={agree}
              onChange={(e) => setAgree(e.target.checked)}
            />
            <label htmlFor="terms" className="text-[10px] font-bold uppercase tracking-widest">I verify the <span className="underline">Network Terms</span></label>
          </div>

          <button disabled={loading} className="btn-primary w-full mt-8 shadow-xl shadow-black/10">
            {loading ? "Registering Node..." : "Establish Profile"}
          </button>
        </form>
      </div>

      <p className="mt-8 text-center text-xs font-medium">
        Already a node member? <Link to="/signin" className="font-bold underline ml-1">Login Portal</Link>
      </p>
    </div>
  );
};

