  const [notifContent, setNotifContent] = useState({ title: '', message: '' });
  const [notifImage, setNotifImage] = useState<File | null>(null);
  const [sending, setSending] = useState(false);
  const notify = useNotify();

  const ONESIGNAL_APP_ID = "29c39d8a-7be8-404a-8a33-5616086735fa";
  const ONESIGNAL_REST_KEY = "NDdiN2YxZjEtOTU4NS00ODU1LWEwZWUtZWE2NTE1ZTEwZTIy";
  const proxyUrl = "https://api.allorigins.win/raw?url=";

  useEffect(() => {
    // Real-time listener for user list updates
    const q = query(collection(db, 'users'), orderBy('createdAt', 'desc'));
    const unsubscribe = onSnapshot(q, (snap) => {
      setUsers(snap.docs.map(d => ({ ...d.data() } as UserProfile)));
    });
    return unsubscribe;
