                       type="file" 
                       accept="image/*"
                       className="w-full bg-f-gray p-4 rounded-2xl outline-none text-[10px] font-bold uppercase shadow-inner"
                       onChange={e => setNotifImage(e.target.files?.[0] || null)}
                    />
                 </div>
              </div>

              <div className="flex space-x-4 mt-10">
                 <button 
                   disabled={sending}
                   onClick={sendNotification} 
                   className="flex-1 btn-primary text-[10px] uppercase tracking-[2px] disabled:opacity-50 flex items-center justify-center"
                 >
                   {sending ? <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin mr-3"></div> : null}
                   {sending ? "Transmitting..." : "Initialize Dispatch"}
                 </button>
                 <button 
                   onClick={() => setNotifModal({ isOpen: false, uid: '', name: '' })} 
                   className="px-6 py-4 text-[10px] font-bold uppercase text-f-gray tracking-widest"
                 >
                   Abort
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default ManageUsers;

