    <div className="mb-8">
      <h4 className="text-[10px] font-bold text-f-gray font-bold uppercase tracking-[4px] border-b border-gray-100 pb-3 mb-5 flex items-center">
        <span className="w-1.5 h-1.5 bg-black rounded-full mr-3"></span>
        {title}
      </h4>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-1">
        {children}
      </div>
    </div>
  );

  const InfoBit = ({ label, value, color = "text-black" }: { label: string; value?: any, color?: string }) => (
    <div className="flex justify-between items-center py-2.5 border-b border-gray-50 last:border-0 group">
      <span className="text-[9px] font-bold text-gray-400 uppercase tracking-widest group-hover:text-black transition-colors">{label}</span>
      <span className={`text-[11px] font-bold ${color} break-all text-right max-w-[60%] pl-4`}>{value || 'NOT_CAPTURED'}</span>
    </div>
  );

  return (
    <div className="max-w-7xl mx-auto px-6 py-10 bg-white min-h-screen">
      <div className="flex justify-between items-center mb-10">
        <div className="flex items-center space-x-5">
