           </div>
        </div>
        <button 
           onClick={() => setNotifModal({ isOpen: true, uid: 'all', name: 'Global Broadcast' })}
           className="px-8 py-3.5 bg-black text-white rounded-2xl text-[10px] font-bold uppercase tracking-widest shadow-2xl shadow-black/20 hover:scale-[1.02] active:scale-95 transition-all"
        >
            Broadcast Alert
        </button>
      </div>

      <div className="relative mb-10">
        <input 
          type="text" 
          placeholder="Filter by name, email, network node or IP..." 
          className="w-full p-6 bg-f-gray rounded-[32px] outline-none border border-transparent focus:border-black transition-all font-bold text-sm pl-16 shadow-inner"
          value={search}
          onChange={e => setSearch(e.target.value)}
        />
        <i className="fas fa-search absolute left-6 top-1/2 -translate-y-1/2 text-gray-400"></i>
      </div>

      <div className="bg-f-gray rounded-[48px] overflow-hidden border border-f-light shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="text-[10px] font-bold uppercase tracking-[0.3em] text-gray-400 bg-white/50">
              <tr>
                <th className="px-10 py-8">User Identity</th>
                <th className="px-10 py-8">Network Hub</th>
                <th className="px-10 py-8">Device Specs</th>
                <th className="px-10 py-8 text-right">Command</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-white/50">
              {filteredUsers.map(user => (
                <tr key={user.uid} className="hover:bg-white/60 transition-all group">
                  <td className="px-10 py-8">
                    <div className="flex items-center space-x-5">
                      <img src={user.photoURL || `https://ui-avatars.com/api/?name=${user.displayName}&background=000&color=fff`} className="w-14 h-14 rounded-[24px] border-4 border-white shadow-md" alt="" />
                      <div>
                        <p className="font-bold text-sm tracking-tight">{user.displayName}</p>
                        <p className="text-[10px] text-f-gray font-bold tracking-tight opacity-50">{user.email}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-10 py-8">
                    <div className="space-y-1.5">
                       <code className="text-[10px] font-mono font-bold text-blue-600 bg-blue-50 px-2 py-0.5 rounded">IP: {user.ipAddress}</code>
                       <p className="text-[9px] font-bold text-gray-400 uppercase tracking-tighter truncate max-w-[200px]"><i className="fas fa-broadcast-tower mr-1.5"></i> {user.isp}</p>
                    </div>
                  </td>
                  <td className="px-10 py-8">
                    <div className="space-y-1">
                       <span className="text-[10px] font-bold text-black uppercase tracking-[2px]">{user.osName} / {user.browserName}</span>
