  const [syncingId, setSyncingId] = useState<string | null>(null);
  const [viewingOrder, setViewingOrder] = useState<Order | null>(null);
  const notify = useNotify();

  useEffect(() => {
    const q = query(collection(db, 'orders'), orderBy('createdAt', 'desc'));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));
      setOrders(data);
      setLoading(false);
    }, (err) => {
      console.error("Firestore Orders Sync Error:", err);
      setLoading(false);
    });
    return unsubscribe;
  }, []);

  const updateStatus = async (orderId: string, newStatus: OrderStatus) => {
    try {
      await updateDoc(doc(db, 'orders', orderId), { status: newStatus });
      notify("Status synchronized", "success");
    } catch (err) {
      notify("Status update rejected", "error");
    }
  };

  const handleSendToSteadfast = async (order: Order) => {
    setSyncingId(order.id);
    try {
        const result = await sendOrderToSteadfast(order);
        if (result && result.status === 200 && result.consignment) {
            await updateDoc(doc(db, 'orders', order.id), { 
                steadfastId: result.consignment.tracking_code,
                steadfastStatus: result.consignment.status,
                status: OrderStatus.SHIPPED
            });
            notify("Logistics handover successful", "success");
        } else {
            notify(result?.message || "Logistics rejection", "error");
        }
    } catch (e) {
        notify("Network gateway timeout", "error");
    } finally {
        setSyncingId(null);
    }
  };

  const getStatusColor = (status: OrderStatus) => {
    switch(status) {
      case OrderStatus.DELIVERED: return 'bg-green-100 text-green-600';
      case OrderStatus.SHIPPED: return 'bg-blue-100 text-blue-600';
      case OrderStatus.PROCESSING: return 'bg-orange-100 text-orange-600';
      case OrderStatus.PENDING: return 'bg-gray-100 text-gray-500';
      case OrderStatus.CANCELLED: return 'bg-red-100 text-red-600';
      default: return 'bg-gray-100 text-gray-600';
    }
  };

  const InfoBit = ({ label, value }: { label: string; value: any }) => (
    <div className="py-3 border-b border-gray-50 flex justify-between items-center group">
      <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{label}</span>
      <span className="text-xs font-bold text-black text-right max-w-[60%]">{value || 'N/A'}</span>
    </div>
  );

  return (
    <div className="max-w-7xl mx-auto px-6 py-10 bg-white min-h-screen relative">
      <div className="mb-12 flex items-center justify-between">
        <div className="flex items-center space-x-6">
          <button onClick={() => navigate(-1)} className="p-3.5 bg-f-gray rounded-2xl active:scale-90 transition-all shadow-sm">
            <i className="fas fa-chevron-left text-sm"></i>
          </button>
          <div>
            <h1 className="text-3xl font-bold tracking-tight">Order Manifest</h1>
            <p className="text-[10px] text-f-gray font-bold uppercase tracking-[0.3em] mt-1">A-Z System Logistics</p>
          </div>
        </div>
        <div className="flex bg-f-gray p-1.5 rounded-2xl">
           <div className="px-5 py-2.5 bg-white rounded-xl shadow-sm text-[10px] font-bold uppercase tracking-widest">Active ({orders.length})</div>
        </div>
      </div>

      <div className="space-y-10">
        {orders.map(order => (
          <div key={order.id} className="bg-f-gray rounded-[48px] border border-f-light overflow-hidden shadow-sm flex flex-col lg:flex-row group transition-all hover:shadow-2xl">
            <div className="p-10 lg:w-1/3 border-b lg:border-b-0 lg:border-r border-white/50 space-y-8 flex flex-col justify-between">
              <div>
                <div className="flex justify-between items-start mb-6">
                   <div>
                      <p className="text-[9px] font-bold text-gray-400 uppercase tracking-widest mb-1 opacity-40">System Invoice</p>
                      <p className="text-sm font-mono font-bold tracking-tighter">#{order.id.toUpperCase()}</p>
                   </div>
                   <span className={`px-4 py-2 rounded-2xl text-[9px] font-bold uppercase tracking-widest ${getStatusColor(order.status)}`}>
                      {order.status}
                   </span>
                </div>

                <div className="space-y-5">
                   <div className="flex items-center space-x-4">
                      <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center shadow-sm">
                         <i className="fas fa-id-card text-sm opacity-20"></i>
                      </div>
                      <div>
                         <p className="text-[9px] font-bold text-gray-400 uppercase tracking-tighter">Purchaser</p>
                         <p className="text-xs font-bold">{order.customerName}</p>
                      </div>
                   </div>
                   <div className="flex items-center space-x-4">
                      <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center shadow-sm">
                         <i className="fas fa-phone-alt text-sm opacity-20"></i>
                      </div>
                      <div>
                         <p className="text-[9px] font-bold text-gray-400 uppercase tracking-tighter">Verified Contact</p>
                         <p className="text-xs font-bold">{order.contactNumber}</p>
                      </div>
                   </div>
                </div>
              </div>

              <div className="pt-8 border-t border-white/50">
                 <button 
                  onClick={() => setViewingOrder(order)}
                  className="w-full py-4 bg-white text-black rounded-2xl text-[10px] font-bold uppercase tracking-widest shadow-sm hover:bg-black hover:text-white transition-all active:scale-95"
                 >
                   Deep Inspect A-Z
                 </button>
              </div>
            </div>

            <div className="p-10 flex-1 space-y-10 flex flex-col justify-between bg-white/40">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                 <div>
                    <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-6 opacity-40">Cart Signature</h4>
                    <div className="space-y-3">
                       {order.items.map((item, idx) => (
                          <div key={idx} className="flex items-center space-x-4 bg-white p-3.5 rounded-2xl border border-white shadow-sm">
                             <img src={item.image} className="w-10 h-10 rounded-xl object-contain bg-f-gray" alt="" />
                             <div className="flex-1 min-w-0">
                                <p className="text-[11px] font-bold truncate">{item.name}</p>
                                <p className="text-[9px] text-f-gray font-bold">৳{item.priceAtPurchase} x {item.quantity}</p>
                             </div>
                          </div>
                       ))}
                    </div>
                 </div>
                 <div className="flex flex-col justify-between">
                    <div>
                      <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-6 opacity-40">Logistics Node</h4>
                      <div className="p-5 bg-white rounded-3xl border border-white shadow-sm text-xs font-bold leading-relaxed italic text-gray-400">
                         {order.shippingAddress}
                      </div>
                    </div>
                    <div className="mt-8 p-6 bg-black text-white rounded-[32px] flex justify-between items-center shadow-xl">
                       <span className="text-[10px] font-bold uppercase tracking-[0.3em] opacity-40">Financial Total</span>
                       <span className="text-2xl font-bold tracking-tighter">৳{order.total}</span>
                    </div>
                 </div>
              </div>

              <div className="flex items-center justify-between pt-8 border-t border-white/50">
                 <div className="flex items-center space-x-4">
                    <div className="w-10 h-10 bg-black rounded-xl flex items-center justify-center text-white"><i className="fas fa-truck-loading text-xs"></i></div>
                    <div>
                      <p className="text-[9px] font-bold text-gray-400 uppercase tracking-widest opacity-40">Courier Sync</p>
                      <span className="text-[10px] font-bold">Steadfast Logistics</span>
                    </div>
                 </div>
                 {order.steadfastId ? (
                   <div className="px-6 py-3.5 bg-green-50 text-green-600 rounded-2xl border border-green-100 flex items-center space-x-3">
                      <i className="fas fa-check-circle"></i>
                      <span className="text-[10px] font-bold uppercase tracking-widest">Handed Over</span>
                   </div>
                 ) : (
                   <button 
                     disabled={syncingId === order.id}
                     onClick={() => handleSendToSteadfast(order)}
                     className="px-8 py-4 bg-black text-white rounded-2xl text-[10px] font-bold uppercase tracking-widest flex items-center space-x-3 shadow-xl active:scale-95 disabled:opacity-50"
                   >
                     {syncingId === order.id ? <i className="fas fa-circle-notch animate-spin"></i> : <i className="fas fa-bolt"></i>}
                     <span>Push to Courier</span>
                   </button>
                 )}
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* A-Z Order Inspection Modal */}
      {viewingOrder && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-xl z-[100] flex items-center justify-center p-6 lg:p-12 animate-fade-in">
           <div className="bg-white w-full max-w-4xl rounded-[64px] overflow-hidden shadow-2xl flex flex-col lg:flex-row h-full max-h-[90vh]">
              {/* Sidebar Info */}
              <div className="w-full lg:w-1/3 bg-black p-12 text-white flex flex-col justify-between">
                  <div>
                    <div className="w-20 h-20 bg-white/10 rounded-[32px] flex items-center justify-center mb-10"><i className="fas fa-box-open text-3xl"></i></div>
                    <h2 className="text-4xl font-bold tracking-tighter mb-4">Inspection</h2>
                    <p className="text-[10px] font-bold uppercase tracking-[0.5em] opacity-40">Logistics Blueprint</p>
