                    <button onClick={() => setViewingOrder(null)} className="w-full py-5 bg-white text-black rounded-3xl font-bold uppercase text-[10px] tracking-widest active:scale-95 transition-transform">Terminate View</button>
                  </div>
              </div>

              {/* Data Panel */}
              <div className="flex-1 p-12 overflow-y-auto no-scrollbar">
                  <div className="mb-10 flex justify-between items-end">
                    <h3 className="text-2xl font-bold tracking-tight">System Data Log</h3>
                    <code className="text-[10px] font-mono font-bold bg-f-gray px-3 py-1 rounded-full">REF: {viewingOrder.id}</code>
                  </div>

                  <section className="mb-12">
                    <h4 className="text-[10px] font-bold text-gray-300 uppercase tracking-[4px] border-b pb-3 mb-6">Customer Profile</h4>
                    <InfoBit label="Full Identity" value={viewingOrder.customerName} />
                    <InfoBit label="Phone Terminal" value={viewingOrder.contactNumber} />
                    <InfoBit label="Delivery Node" value={viewingOrder.shippingAddress} />
                  </section>

                  <section className="mb-12">
                    <h4 className="text-[10px] font-bold text-gray-300 uppercase tracking-[4px] border-b pb-3 mb-6">Financial Manifest</h4>
                    <InfoBit label="Payment Gateway" value={viewingOrder.paymentMethod} />
