import React, { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { GoogleGenAI, LiveServerMessage, Modality } from "@google/genai";
import { useNotify } from '../components/Notifications';
import { motion, AnimatePresence } from 'framer-motion';

interface GenAIBlob { data: string; mimeType: string; }

const AIChat: React.FC = () => {
  const navigate = useNavigate();
  const notify = useNotify();
  const [messages, setMessages] = useState<{ role: 'user' | 'bot'; text: string; isThinking?: boolean }[]>([
    { role: 'bot', text: 'Greetings Node. আমি Vibe AI। আপনার যান্ত্রিক সমস্যা বা অনুসন্ধানে সহায়তা করতে পারি?' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isLiveMode, setIsLiveMode] = useState(false);
  const [useThinking, setUseThinking] = useState(true);

  const [isRecording, setIsRecording] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const scrollRef = useRef<HTMLDivElement>(null);

  const sessionRef = useRef<any>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isTyping]);

  useEffect(() => { return () => stopLiveSession(); }, []);

  function encode(bytes: Uint8Array) {
    let binary = '';
    for (let i = 0; i < bytes.byteLength; i++) binary += String.fromCharCode(bytes[i]);
    return btoa(binary);
  }

  function decode(base64: string) {
    const binaryString = atob(base64);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
    return bytes;
  }

  async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
    return buffer;
  }

  const blobToBase64 = (blob: Blob): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
      reader.onerror = reject;
      reader.readAsDataURL(blob);
    });
  };

  const startRecording = async () => {
    if (isLiveMode) stopLiveSession();
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      chunksRef.current = [];
      mediaRecorder.ondataavailable = (e) => { if (e.data.size > 0) chunksRef.current.push(e.data); };
      mediaRecorder.onstop = async () => {
        const audioBlob = new Blob(chunksRef.current, { type: 'audio/webm' });
        const base64 = await blobToBase64(audioBlob);
        transcribeAudio(base64);
      };
      mediaRecorder.start();
      setIsRecording(true);
    } catch (err) { notify("Microphone access denied", "error"); }
  };

  const stopRecording = () => { mediaRecorderRef.current?.stop(); setIsRecording(false); };

  const transcribeAudio = async (base64: string) => {
    setIsTyping(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
          parts: [
            { text: "Accurately transcribe the following audio to text. Only return the transcribed text." },
            { inlineData: { data: base64, mimeType: 'audio/webm' } }
          ]
        }
      });
      if (response.text) setInput(response.text);
    } catch (error) { notify("Transcription failed", "error"); } finally { setIsTyping(false); }
  };

  const startLiveSession = async () => {
    if (isRecording) stopRecording();
    setIsLiveMode(true);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

    const sessionPromise = ai.live.connect({
      model: 'gemini-2.5-flash-native-audio-preview-12-2025',
      callbacks: {
        onopen: () => {
          const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
          const scriptProcessor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
          scriptProcessor.onaudioprocess = (e) => {
            const inputData = e.inputBuffer.getChannelData(0);
            const int16 = new Int16Array(inputData.length);
            for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
            const pcmBlob: GenAIBlob = { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
            sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
          };
          source.connect(scriptProcessor);
          scriptProcessor.connect(inputAudioContextRef.current!.destination);
        },
        onmessage: async (m: LiveServerMessage) => {
          const audio = m.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
          if (audio) {
            const ctx = audioContextRef.current!;
            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
            const buf = await decodeAudioData(decode(audio), ctx, 24000, 1);
            const src = ctx.createBufferSource();
            src.buffer = buf;
            src.connect(ctx.destination);
            src.start(nextStartTimeRef.current);
            nextStartTimeRef.current += buf.duration;
            sourcesRef.current.add(src);
            src.onended = () => sourcesRef.current.delete(src);
          }
          if (m.serverContent?.interrupted) { sourcesRef.current.forEach(s => s.stop()); sourcesRef.current.clear(); nextStartTimeRef.current = 0; }
        },
        onclose: () => setIsLiveMode(false),
        onerror: (e) => console.error(e)
      },
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
        systemInstruction: `আপনি VibeGadget এর নিজস্ব AI। আপনার নির্মাতা এবং মালিক হলেন VibeGadget-এর প্রোপাইটর "সামির" (Samir)। আপনার ব্যক্তিত্ব অত্যন্ত যান্ত্রিক তবে বন্ধুসুলভ হতে হবে।`
      }
    });
    sessionRef.current = await sessionPromise;
  };

  const stopLiveSession = () => {
    if (sessionRef.current) sessionRef.current.close();
    if (audioContextRef.current) audioContextRef.current.close();
    if (inputAudioContextRef.current) inputAudioContextRef.current.close();
    setIsLiveMode(false);
  };

  const handleSendMessage = async () => {
    if (!input.trim() || isTyping) return;
    const userMessage = input.trim();
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setInput('');
    setIsTyping(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: userMessage,
        config: {
          systemInstruction: `আপনি VibeGadget-এর নিজস্ব AI। প্রোপাইটর: সামির। লোকেশন: F.T.C Market (রুম নাম্বার ৫৪), দাগনভূঞা, ফেনী।`,
          thinkingConfig: useThinking ? { thinkingBudget: 32768 } : undefined
        },
      });
      setMessages(prev => [...prev, { role: 'bot', text: response.text || "Synchronisation interrupted.", isThinking: useThinking }]);
    } catch (error) { setMessages(prev => [...prev, { role: 'bot', text: "Network uplink failed." }]); } finally { setIsTyping(false); }
  };

  return (
    <div className="flex flex-col h-screen bg-[#FDFDFD] max-w-5xl mx-auto overflow-hidden shadow-2xl">
      <div className="glass sticky top-0 z-50 px-6 py-5 flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <motion.button 
            whileTap={{ scale: 0.9 }}
            onClick={() => navigate(-1)} 
            className="p-3 bg-zinc-900 text-white rounded-2xl shadow-xl"
          >
            <i className="fas fa-chevron-left text-xs"></i>
          </motion.button>
          <div className="flex flex-col">
            <h2 className="font-black text-sm tracking-widest uppercase">Vibe Neural Hub</h2>
            <div className="flex items-center text-[8px] font-bold text-green-500 uppercase tracking-widest">
                <span className="w-1.5 h-1.5 bg-green-500 rounded-full mr-2 animate-pulse"></span>
                Uplink Active
            </div>
          </div>
        </div>
        <button 
          onClick={() => setUseThinking(!useThinking)}
          className={`px-4 py-2 rounded-xl text-[9px] font-bold uppercase tracking-[0.2em] transition-all ${useThinking ? 'bg-zinc-900 text-white shadow-xl' : 'bg-zinc-100 text-zinc-400'}`}
        >
          {useThinking ? 'Core Intelligence' : 'Lightweight'}
        </button>
      </div>

      <AnimatePresence>
        {isLiveMode && (
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="absolute inset-0 bg-black/95 z-[60] flex flex-col items-center justify-center p-10"
          >
            <motion.div 
                animate={{ scale: [1, 1.2, 1], rotate: [0, 5, -5, 0] }}
                transition={{ repeat: Infinity, duration: 4 }}
                className="w-48 h-48 rounded-[64px] border border-white/20 flex items-center justify-center relative overflow-hidden glass-dark"
            >
                <div className="absolute inset-0 bg-gradient-to-tr from-white/5 to-transparent"></div>
                <i className="fas fa-microphone text-4xl text-white"></i>
            </motion.div>
            <h3 className="text-white text-sm font-bold mt-12 uppercase tracking-[0.5em] animate-pulse">Vibe is Listening</h3>
            <button onClick={stopLiveSession} className="mt-20 btn-primary bg-white text-zinc-900 px-16 py-4 rounded-full font-black text-xs tracking-widest uppercase">Terminate Call</button>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="flex-1 overflow-y-auto p-6 md:p-12 space-y-8 no-scrollbar bg-zinc-50/30">
        <AnimatePresence initial={false}>
          {messages.map((msg, i) => (
            <motion.div 
              key={i}
              initial={{ opacity: 0, y: 20, scale: 0.95 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              transition={{ type: "spring", damping: 20, stiffness: 100 }}
              className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
            >
              <div className={`max-w-[85%] px-7 py-5 rounded-[32px] text-xs md:text-sm font-medium shadow-sm leading-relaxed ${msg.role === 'user' ? 'bg-zinc-900 text-white rounded-tr-none' : 'glass text-zinc-900 rounded-tl-none'}`}>
                {msg.isThinking && msg.role === 'bot' && (
                  <div className="flex items-center space-x-2 mb-3 opacity-30 text-[7px] font-black uppercase tracking-[0.3em]">
                    <i className="fas fa-brain"></i>
                    <span>Neural Reasoning Active</span>
                  </div>
                )}
                {msg.text}
              </div>
            </motion.div>
          ))}
        </AnimatePresence>
        {isTyping && (
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="glass px-6 py-4 rounded-[24px] rounded-tl-none w-fit text-[8px] font-black uppercase tracking-widest text-zinc-400"
          >
            Processing Output...
          </motion.div>
        )}
        <div ref={scrollRef} />
      </div>

      <div className="p-6 md:p-10 bg-white border-t border-zinc-100">
        <div className="flex items-end space-x-4 max-w-4xl mx-auto">
          <div className="flex flex-col space-y-3">
            <motion.button whileTap={{ scale: 0.9 }} onClick={startLiveSession} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isLiveMode ? 'bg-red-500 text-white' : 'bg-zinc-100 text-zinc-400'}`}><i className="fas fa-phone-alt text-xs"></i></motion.button>
            <motion.button whileTap={{ scale: 0.9 }} onClick={isRecording ? stopRecording : startRecording} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${isRecording ? 'bg-red-500 text-white' : 'bg-zinc-100 text-zinc-400'}`}><i className={`fas ${isRecording ? 'fa-stop' : 'fa-microphone'} text-xs`}></i></motion.button>
          </div>
          <div className="flex-1 flex flex-col space-y-4">
            <div className="flex items-center bg-zinc-50 rounded-[28px] p-2 pr-4 border border-zinc-100">
                <input type="text" placeholder="Transmit thought..." className="flex-1 bg-transparent px-5 py-3 outline-none text-xs font-bold" value={input} onChange={(e) => setInput(e.target.value)} onKeyPress={(e) => e.key === 'Enter' && handleSendMessage()} />
                <motion.button 
                  whileTap={{ scale: 0.9 }}
                  onClick={handleSendMessage} 
                  className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${input.trim() ? 'bg-zinc-900 text-white shadow-xl' : 'bg-zinc-200 text-zinc-400'}`}
                >
                  <i className="fas fa-arrow-up text-xs"></i>
                </motion.button>
            </div>
            <p className="text-[7px] text-center text-zinc-300 font-black uppercase tracking-[0.5em]">Neural Uplink V2.5</p>
          </div>
        </div>
      </div>
    </div>
  );
};

