import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { auth, db } from '../firebase';
import { collection, addDoc, doc, getDoc } from 'firebase/firestore';
import { useNotify } from '../components/Notifications';
import { OrderStatus, UserProfile } from '../types';
import { sendOrderToTelegram } from '../services/telegram';
import { motion } from 'framer-motion';

const CheckoutPage: React.FC = () => {
  const [items, setItems] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);

  const [shipping, setShipping] = useState({
    name: '',
    address: localStorage.getItem('vibe_shipping_address') || 'Dhaka, Bangladesh',
    phone: '',
    payment: 'Cash on Delivery',
    paymentOption: 'Full Payment' as 'Full Payment' | 'Delivery Fee Only',
    trxId: ''
  });

  const navigate = useNavigate();
  const notify = useNotify();

  useEffect(() => {
    const cart = JSON.parse(localStorage.getItem('f_cart') || '[]');
    if (cart.length === 0) { navigate('/'); return; }
    setItems(cart);

    const user = auth.currentUser;
    if (user) {
      getDoc(doc(db, 'users', user.uid)).then(snap => {
        if (snap.exists()) {
          const data = snap.data() as UserProfile;
          setShipping(prev => ({ 
            ...prev, 
            name: data.displayName || '', 
            phone: data.phoneNumber || '',
            address: data.address || prev.address
          }));
        }
      });
    }
  }, []);

  const subTotal = items.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
  const deliveryFee = 150; 
  const grandTotal = subTotal + deliveryFee;

  const placeOrder = async () => {
    if (!shipping.name || !shipping.address || !shipping.phone) return notify("Please fill shipping details", "error");
    if (shipping.payment !== 'Cash on Delivery' && !shipping.trxId) return notify("Transaction ID is required", "error");

    setLoading(true);
    try {
      const orderData = {
        userId: auth.currentUser?.uid || 'guest',
        customerName: shipping.name,
        items: items.map(i => ({ productId: i.id, quantity: i.quantity, priceAtPurchase: i.price, name: i.name, image: i.image })),
        total: grandTotal,
        status: OrderStatus.PROCESSING,
        paymentMethod: shipping.payment,
        paymentOption: shipping.payment === 'Cash on Delivery' ? null : shipping.paymentOption,
        transactionId: shipping.trxId,
        shippingAddress: shipping.address,
        contactNumber: shipping.phone,
        createdAt: Date.now()
      };

      const docRef = await addDoc(collection(db, 'orders'), orderData);
      await sendOrderToTelegram({ ...orderData, id: docRef.id });

      localStorage.removeItem('f_cart');
      notify("Order Placed Successfully!", "success");
      navigate(`/success?orderId=${docRef.id}`);
    } catch (err) {
      notify("Something went wrong", "error");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-6 md:px-12 py-10 pb-32 animate-fade-in bg-white min-h-screen">
      <div className="flex items-center space-x-6 mb-12">
          <button onClick={() => navigate(-1)} className="p-3.5 bg-zinc-50 rounded-2xl shadow-sm hover:bg-zinc-900 hover:text-white transition-all">
             <i className="fas fa-chevron-left text-xs"></i>
          </button>
          <h1 className="text-2xl md:text-4xl font-black tracking-tight">System Checkout</h1>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
        {/* Input Fields */}
        <div className="lg:col-span-7 space-y-12">
          <section className="bg-zinc-50 p-8 md:p-12 rounded-[48px] border border-zinc-100 shadow-sm">
            <h2 className="text-[10px] font-black text-zinc-400 uppercase tracking-[0.4em] mb-10">Shipping Telemetry</h2>
            <div className="space-y-8">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div>
                    <label className="text-[9px] font-black text-zinc-400 uppercase mb-3 block px-2 tracking-widest">Receiver Identity</label>
                    <input 
                        type="text" 
                        placeholder="Full Name"
                        className="w-full bg-white px-6 py-5 rounded-3xl text-sm font-bold outline-none border border-transparent focus:border-zinc-900 shadow-inner transition-all"
                        value={shipping.name}
                        onChange={(e) => setShipping({...shipping, name: e.target.value})}
                    />
                  </div>
                  <div>
                    <label className="text-[9px] font-black text-zinc-400 uppercase mb-3 block px-2 tracking-widest">Active Terminal (Phone)</label>
                    <input 
                        type="tel" 
                        placeholder="01XXXXXXXXX"
                        className="w-full bg-white px-6 py-5 rounded-3xl text-sm font-bold outline-none border border-transparent focus:border-zinc-900 shadow-inner transition-all"
                        value={shipping.phone}
                        onChange={(e) => setShipping({...shipping, phone: e.target.value})}
                    />
                  </div>
               </div>
               <div>
                  <label className="text-[9px] font-black text-zinc-400 uppercase mb-3 block px-2 tracking-widest">Delivery Node (Address)</label>
                  <textarea 
                      placeholder="Street, Thana, District"
                      className="w-full bg-white px-6 py-5 rounded-[32px] text-sm font-bold outline-none border border-transparent focus:border-zinc-900 h-32 shadow-inner transition-all leading-relaxed"
