import React, { useState, useEffect } from 'react';
import { collection, onSnapshot, query, orderBy } from 'firebase/firestore';
import { db } from '../firebase';
import { Product } from '../types';
import { Link, useNavigate } from 'react-router-dom';
import { getReadableAddress } from '../services/location';
import { motion, AnimatePresence } from 'framer-motion';

const Home: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [banners, setBanners] = useState<any[]>([]);
  const [activeBanner, setActiveBanner] = useState(0);
  const [activeCategory, setActiveCategory] = useState('All');
  const [locationName, setLocationName] = useState('Fetching location...');
  const navigate = useNavigate();

  const categories = [
    { name: 'Mobile', icon: 'fas fa-mobile-alt' },
    { name: 'Accessories', icon: 'fas fa-headphones' },
    { name: 'Gadgets', icon: 'fas fa-plug' },
    { name: 'Chargers', icon: 'fas fa-bolt' }
  ];

  useEffect(() => {
    const qProds = query(collection(db, 'products'));
    const unsubscribeProds = onSnapshot(qProds, (snapshot) => {
      setProducts(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Product)));
    });

    const qBanners = query(collection(db, 'banners'), orderBy('createdAt', 'desc'));
    const unsubscribeBanners = onSnapshot(qBanners, (snapshot) => {
      setBanners(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    });

    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(async (position) => {
        const address = await getReadableAddress(position.coords.latitude, position.coords.longitude);
        setLocationName(address);
      }, () => {
        setLocationName('Dhaka, Bangladesh');
      });
    }

    return () => {
        unsubscribeProds();
        unsubscribeBanners();
    };
  }, []);

  useEffect(() => {
    if (banners.length > 1) {
      const interval = setInterval(() => {
        setActiveBanner(prev => (prev + 1) % banners.length);
      }, 6000);
      return () => clearInterval(interval);
    }
  }, [banners]);

  const filteredProducts = products.filter(p => activeCategory === 'All' || p.category === activeCategory);

  return (
    <div className="px-6 md:px-12 py-10 pb-32 bg-white max-w-[1400px] mx-auto min-h-screen">
      {/* Top Header */}
      <motion.div 
        initial={{ y: -10, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        className="flex justify-between items-center mb-12"
      >
        <div>
          <p className="text-[10px] text-zinc-400 font-bold uppercase tracking-widest mb-1">Deliver to</p>
          <button className="flex items-center font-bold text-xs md:text-sm hover:text-zinc-600 transition-all">
            <i className="fas fa-map-marker-alt text-black mr-2 text-[10px]"></i>
            {locationName}
          </button>
        </div>
        <motion.button 
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          onClick={() => navigate('/notifications')} 
          className="p-3 bg-zinc-50 rounded-2xl relative border border-zinc-100 shadow-sm"
        >
          <i className="fas fa-bell text-sm"></i>
          <span className="absolute top-2.5 right-2.5 w-2 h-2 bg-red-500 rounded-full border-2 border-white"></span>
        </motion.button>
      </motion.div>

      {/* Main Title & Search */}
      <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-8 mb-12">
        <div>
          <h1 className="text-4xl md:text-6xl lg:text-7xl font-black tracking-tighter text-zinc-900 leading-tight">Modern Gadgets.</h1>
          <p className="text-xs md:text-sm font-medium text-zinc-400 mt-2">Premium accessories for your tech lifestyle.</p>
        </div>

        <motion.div 
          onClick={() => navigate('/search')} 
          className="relative cursor-pointer w-full lg:max-w-md group"
        >
          <div className="w-full bg-zinc-50 py-4 pl-14 pr-10 rounded-2xl text-sm text-zinc-400 font-medium border border-zinc-100 group-hover:bg-zinc-100 transition-all">Search products...</div>
          <i className="fas fa-search absolute left-5 top-1/2 -translate-y-1/2 text-zinc-400"></i>
        </motion.div>
      </div>

      {/* Banner Carousel */}
      <motion.div 
        className="relative mb-16 overflow-hidden rounded-[32px] md:rounded-[48px] shadow-2xl shadow-zinc-100"
      >
        <div className="flex transition-transform duration-1000 ease-[cubic-bezier(0.4, 0, 0.2, 1)]" style={{ transform: `translateX(-${activeBanner * 100}%)` }}>
          {banners.length > 0 ? banners.map((banner, i) => (
            <div key={i} className="min-w-full bg-zinc-100 aspect-[16/9] md:aspect-[21/9] relative">
               <img src={banner.imageUrl} className="absolute inset-0 w-full h-full object-cover" alt="" />
               <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-black/20 to-transparent"></div>
               <div className="absolute bottom-8 left-8 md:bottom-12 md:left-12 text-white max-w-lg">
                  <h2 className="text-2xl md:text-4xl font-black tracking-tight mb-2">{banner.title}</h2>
                  <p className="text-[10px] md:text-xs uppercase font-bold tracking-widest opacity-80">{banner.description}</p>
               </div>
            </div>
          )) : (
            <div className="min-w-full bg-zinc-900 aspect-[21/9] flex items-center justify-center text-white">
               <p className="text-[10px] opacity-40 uppercase font-bold tracking-[0.4em] animate-pulse">Loading Offers...</p>
            </div>
          )}
        </div>
      </motion.div>

      {/* Categories */}
      <div className="flex justify-between items-center mb-8">
        <h3 className="font-bold text-sm text-zinc-900">Categories</h3>
        <button onClick={() => navigate('/all-products')} className="text-xs font-bold text-zinc-400 hover:text-zinc-900 transition-colors uppercase tracking-widest">See All</button>
      </div>

      <div className="flex justify-start mb-16 overflow-x-auto no-scrollbar gap-6 md:gap-8 pb-4">
        {categories.map(cat => (
          <motion.button 
            whileHover={{ y: -5 }}
            key={cat.name} 
            onClick={() => { setActiveCategory(cat.name); navigate('/all-products', { state: { category: cat.name } }); }} 
            className="flex flex-col items-center shrink-0 group"
          >
            <div className="w-16 h-16 md:w-20 md:h-20 bg-zinc-50 rounded-3xl flex items-center justify-center mb-3 group-hover:bg-zinc-900 group-hover:text-white transition-all shadow-sm border border-zinc-100">
