      {/* Products Grid */}
      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-6 md:gap-8">
        <AnimatePresence mode="popLayout">
          {filteredProducts.map((product, index) => (
            <motion.div
              layout
              key={product.id}
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.95 }}
              transition={{ duration: 0.4, delay: index * 0.05 }}
            >
              <Link to={`/product/${product.id}`} className="block group">
                <div className="bg-zinc-50 rounded-[32px] mb-4 overflow-hidden relative aspect-[1/1.2] flex items-center justify-center border border-zinc-100 transition-all duration-500 group-hover:shadow-xl group-hover:border-zinc-200">
                  <img src={product.image} className="w-full h-full object-contain p-6 group-hover:scale-105 transition-transform duration-500" alt={product.name} />
                  <div className="absolute top-4 right-4">
                     <div className="bg-white/90 backdrop-blur px-3 py-1.5 rounded-full text-[10px] font-bold shadow-sm">
                        ৳{product.price}
