import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { signInWithEmailAndPassword } from 'firebase/auth';
import { auth, db } from '../firebase';
import { doc, updateDoc } from 'firebase/firestore';
import { useNotify } from '../components/Notifications';

const SignIn: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();
  const notify = useNotify();

  const handleSignIn = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const userCred = await signInWithEmailAndPassword(auth, email, password);
      const user = userCred.user;

      // Sync user metadata on login
      await updateDoc(doc(db, 'users', user.uid), {
        lastLogin: Date.now(),
        lastActive: Date.now()
      });

      notify("Successfully logged in!", "success");
      navigate('/');
    } catch (err: any) {
      notify(err.message, "error");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-white p-8 flex flex-col max-w-md mx-auto">
      <button onClick={() => navigate(-1)} className="p-3 bg-zinc-50 rounded-2xl self-start mb-10 border border-zinc-100 hover:bg-zinc-100 transition-colors">
        <i className="fas fa-chevron-left text-sm"></i>
      </button>

      <div className="flex-1">
        <h1 className="text-3xl font-black mb-2 tracking-tighter">Sign In.</h1>
        <p className="text-zinc-500 text-sm mb-12 font-medium">Welcome back! Please enter your details.</p>

        <form onSubmit={handleSignIn} className="space-y-6">
          <div>
            <label className="block text-[10px] font-bold text-zinc-400 uppercase tracking-widest mb-3 px-2">Email Address</label>
            <input 
              type="email" 
              placeholder="Enter your email" 
              className="w-full bg-zinc-50 p-5 rounded-2xl outline-none border border-transparent focus:border-black transition-all font-medium text-sm"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>
          <div>
            <label className="block text-[10px] font-bold text-zinc-400 uppercase tracking-widest mb-3 px-2">Password</label>
            <input 
              type="password" 
              placeholder="Enter your password" 
              className="w-full bg-zinc-50 p-5 rounded-2xl outline-none border border-transparent focus:border-black transition-all font-medium text-sm"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>

          <button disabled={loading} className="btn-primary w-full mt-10 shadow-2xl shadow-black/10 py-5 text-sm uppercase tracking-widest">
            {loading ? "Signing In..." : "Sign In"}
          </button>
        </form>
      </div>

      <p className="mt-12 text-center text-xs font-medium text-zinc-500">
        Don't have an account? <Link to="/signup" className="text-black font-bold underline ml-1">Sign Up</Link>
      </p>
    </div>
  );
};

export default SignIn;

import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { createUserWithEmailAndPassword, updateProfile } from 'firebase/auth';
import { doc, setDoc } from 'firebase/firestore';
import { auth, db } from '../firebase';
import { useNotify } from '../components/Notifications';

const SignUp: React.FC = () => {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [agree, setAgree] = useState(false);
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();
  const notify = useNotify();

  const handleSignUp = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!agree) return notify("Please agree to the Terms & Conditions", "error");

    setLoading(true);
    try {
      const userCred = await createUserWithEmailAndPassword(auth, email, password);
      const user = userCred.user;
      await updateProfile(user, { displayName: name });

      const userData = {
        uid: user.uid,
        email,
        displayName: name,
        role: 'user',
        isBanned: false,
        createdAt: Date.now(),
        registrationDate: Date.now(),
        lastActive: Date.now()
      };

      await setDoc(doc(db, 'users', user.uid), userData);

      notify("Welcome to VibeGadget!", "success");
      navigate('/');
    } catch (err: any) {
      notify(err.message, "error");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-white p-8 flex flex-col max-w-md mx-auto">
      <button onClick={() => navigate(-1)} className="p-3 bg-zinc-50 rounded-2xl self-start mb-10 border border-zinc-100 hover:bg-zinc-100 transition-colors">
