      <div className="flex-1">
        <h1 className="text-3xl font-black mb-2 tracking-tighter">Sign Up.</h1>
        <p className="text-zinc-500 text-sm mb-12 font-medium">Create your account to start shopping.</p>

        <form onSubmit={handleSignUp} className="space-y-6">
