              type="text" 
              placeholder="Enter your name" 
              className="w-full bg-zinc-50 p-5 rounded-2xl outline-none border border-transparent focus:border-black transition-all font-medium text-sm"
              value={name}
              onChange={(e) => setName(e.target.value)}
              required
            />
          </div>
          <div>
            <label className="block text-[10px] font-bold text-zinc-400 uppercase tracking-widest mb-3 px-2">Email Address</label>
            <input 
              type="email" 
              placeholder="Enter your email" 
              className="w-full bg-zinc-50 p-5 rounded-2xl outline-none border border-transparent focus:border-black transition-all font-medium text-sm"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>
          <div>
            <label className="block text-[10px] font-bold text-zinc-400 uppercase tracking-widest mb-3 px-2">Password</label>
            <input 
              type="password" 
              placeholder="Create a password" 
              className="w-full bg-zinc-50 p-5 rounded-2xl outline-none border border-transparent focus:border-black transition-all font-medium text-sm"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>

          <div className="flex items-center space-x-3 px-2">
            <input 
              type="checkbox" 
              id="terms" 
              className="w-5 h-5 accent-black rounded-lg" 
              checked={agree}
              onChange={(e) => setAgree(e.target.checked)}
            />
            <label htmlFor="terms" className="text-[10px] font-bold uppercase tracking-widest text-zinc-500">I agree to the <span className="text-black underline">Terms & Conditions</span></label>
          </div>

          <button disabled={loading} className="btn-primary w-full mt-8 shadow-2xl shadow-black/10 py-5 text-sm uppercase tracking-widest">
            {loading ? "Creating Account..." : "Sign Up"}
