import React, { useState, useEffect } from 'react';
import { collection, onSnapshot, query, orderBy } from 'firebase/firestore';
import { db } from '../firebase';
import { Product } from '../types';
import { Link, useNavigate } from 'react-router-dom';
import { getReadableAddress } from '../services/location';
import { motion, AnimatePresence } from 'framer-motion';

const Home: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [banners, setBanners] = useState<any[]>([]);
  const [activeBanner, setActiveBanner] = useState(0);
  const [activeCategory, setActiveCategory] = useState('All');
  const [locationName, setLocationName] = useState('Fetching location...');
  const navigate = useNavigate();

  const categories = [
    { name: 'Mobile', icon: 'fas fa-mobile-alt' },
    { name: 'Accessories', icon: 'fas fa-headphones' },
    { name: 'Gadgets', icon: 'fas fa-plug' },
    { name: 'Chargers', icon: 'fas fa-bolt' }
  ];

  useEffect(() => {
    const qProds = query(collection(db, 'products'));
    const unsubscribeProds = onSnapshot(qProds, (snapshot) => {
      setProducts(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Product)));
    });

    const qBanners = query(collection(db, 'banners'), orderBy('createdAt', 'desc'));
    const unsubscribeBanners = onSnapshot(qBanners, (snapshot) => {
      setBanners(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    });

    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(async (position) => {
        const address = await getReadableAddress(position.coords.latitude, position.coords.longitude);
        setLocationName(address);
      }, () => {
        setLocationName('Dhaka, Bangladesh');
      });
    }

    return () => {
        unsubscribeProds();
        unsubscribeBanners();
    };
  }, []);

  useEffect(() => {
    if (banners.length > 1) {
      const interval = setInterval(() => {
        setActiveBanner(prev => (prev + 1) % banners.length);
      }, 6000);
      return () => clearInterval(interval);
    }
  }, [banners]);

  const filteredProducts = products.filter(p => activeCategory === 'All' || p.category === activeCategory);

  return (
    <div className="px-6 md:px-12 py-10 pb-32 bg-white max-w-[1440px] mx-auto min-h-screen">
      {/* Top Header */}
      <motion.div 
        initial={{ y: -10, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        className="flex justify-between items-center mb-10 md:mb-16"
      >
        <div>
          <p className="text-[10px] text-zinc-400 font-bold uppercase tracking-widest mb-1">Shipping to</p>
          <button className="flex items-center font-bold text-xs md:text-sm hover:text-zinc-600 transition-all">
            <i className="fas fa-map-marker-alt text-black mr-2 text-[10px]"></i>
            {locationName}
          </button>
        </div>
        <motion.button 
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          onClick={() => navigate('/notifications')} 
          className="p-3 bg-zinc-50 rounded-2xl relative border border-zinc-100 shadow-sm"
        >
          <i className="fas fa-bell text-sm"></i>
          <span className="absolute top-2.5 right-2.5 w-2 h-2 bg-red-500 rounded-full border-2 border-white"></span>
        </motion.button>
      </motion.div>

      {/* Hero Title & Search */}
      <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-8 mb-12 md:mb-20">
        <div className="max-w-xl">
          <h1 className="text-4xl md:text-6xl lg:text-7xl font-black tracking-tighter text-zinc-900 leading-tight">Modern Gadgets.</h1>
          <p className="text-sm md:text-base font-medium text-zinc-400 mt-3 md:mt-4">Exclusive mobile accessories curated for the modern tech lifestyle.</p>
        </div>

        <motion.div 
          onClick={() => navigate('/search')} 
          className="relative cursor-pointer w-full lg:max-w-md group"
        >
          <div className="w-full bg-zinc-50 py-5 pl-14 pr-10 rounded-3xl text-sm text-zinc-400 font-medium border border-zinc-100 group-hover:bg-zinc-100 transition-all shadow-sm">Search your favorite gear...</div>
          <i className="fas fa-search absolute left-5 top-1/2 -translate-y-1/2 text-zinc-400"></i>
        </motion.div>
      </div>

      {/* Billboard Carousel */}
      <motion.div 
        className="relative mb-16 overflow-hidden rounded-[32px] md:rounded-[48px] lg:rounded-[64px] shadow-2xl shadow-zinc-200/50"
      >
        <div className="flex transition-transform duration-1000 ease-[cubic-bezier(0.23, 1, 0.32, 1)]" style={{ transform: `translateX(-${activeBanner * 100}%)` }}>
          {banners.length > 0 ? banners.map((banner, i) => (
            <div key={i} className="min-w-full bg-zinc-100 aspect-[16/9] md:aspect-[21/9] lg:aspect-[3/1] relative">
               <img src={banner.imageUrl} className="absolute inset-0 w-full h-full object-cover" alt="" />
               <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent"></div>
               <div className="absolute bottom-8 left-8 md:bottom-16 md:left-16 text-white max-w-lg">
                  <h2 className="text-2xl md:text-5xl font-black tracking-tight mb-3 md:mb-4">{banner.title}</h2>
                  <p className="text-xs md:text-sm uppercase font-bold tracking-widest opacity-80 mb-6">{banner.description}</p>
                  <button className="px-8 py-3 bg-white text-black rounded-full font-bold text-[10px] uppercase tracking-widest hover:scale-105 active:scale-95 transition-all">Shop Collection</button>
               </div>
            </div>
          )) : (
            <div className="min-w-full bg-zinc-900 aspect-[21/9] flex items-center justify-center text-white">
               <p className="text-[10px] opacity-40 uppercase font-bold tracking-[0.4em] animate-pulse">Synchronizing Inventory...</p>
            </div>
          )}
        </div>
      </motion.div>

      {/* Shop by Categories */}
      <div className="flex justify-between items-center mb-10">
        <h3 className="font-black text-xs md:text-sm text-zinc-900 uppercase tracking-widest">Shop Categories</h3>
        <button onClick={() => navigate('/all-products')} className="text-xs font-bold text-zinc-400 hover:text-zinc-900 transition-colors uppercase tracking-widest border-b border-transparent hover:border-zinc-900">Explore All</button>
      </div>

      <div className="flex justify-start mb-20 overflow-x-auto no-scrollbar gap-6 md:gap-12 pb-4">
        {categories.map(cat => (
          <motion.button 
            whileHover={{ y: -8 }}
            key={cat.name} 
            onClick={() => { setActiveCategory(cat.name); navigate('/all-products', { state: { category: cat.name } }); }} 
            className="flex flex-col items-center shrink-0 group"
          >
            <div className="w-16 h-16 md:w-24 md:h-24 bg-zinc-50 rounded-[28px] md:rounded-[40px] flex items-center justify-center mb-4 group-hover:bg-zinc-900 group-hover:text-white transition-all shadow-sm border border-zinc-100 group-hover:shadow-xl">
              <i className={`${cat.icon} text-lg md:text-3xl`}></i>
            </div>
            <span className="text-[10px] md:text-xs font-bold text-zinc-500 group-hover:text-zinc-900 transition-colors uppercase tracking-widest">{cat.name}</span>
          </motion.button>
        ))}
      </div>

      {/* Featured Products */}
      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-6 gap-6 md:gap-10">
        <AnimatePresence mode="popLayout">
          {filteredProducts.map((product, index) => (
            <motion.div
              layout
              key={product.id}
              initial={{ opacity: 0, scale: 0.95, y: 10 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95 }}
              transition={{ duration: 0.5, delay: index * 0.05 }}
            >
              <Link to={`/product/${product.id}`} className="block group">
                <div className="bg-zinc-50 rounded-[32px] md:rounded-[48px] mb-5 overflow-hidden relative aspect-[1/1.2] flex items-center justify-center border border-zinc-100 transition-all duration-500 group-hover:shadow-2xl group-hover:border-zinc-200">
                  <img src={product.image} className="w-full h-full object-contain p-6 md:p-8 group-hover:scale-105 transition-transform duration-700 rounded-[32px]" alt={product.name} />
                  <div className="absolute top-5 right-5">
                     <div className="bg-white/90 backdrop-blur px-3.5 py-2 rounded-2xl text-[10px] font-black shadow-sm border border-black/5">
                        ৳{product.price}
                     </div>
                  </div>
                </div>
                <div className="px-3">
                  <h4 className="font-bold text-xs md:text-sm truncate mb-1 tracking-tight group-hover:text-zinc-500 transition-colors">{product.name}</h4>
                  <div className="flex items-center text-[10px] font-bold text-zinc-400 uppercase tracking-[0.2em]">
                     <i className="fas fa-star text-yellow-400 mr-2 text-[8px]"></i>
                     {product.rating} / 5.0
                  </div>
                </div>
              </Link>
            </motion.div>
          ))}
        </AnimatePresence>
      </div>
    </div>
  );
};

export default Home;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { doc, getDoc, collection, query, where, onSnapshot, limit, deleteDoc, setDoc } from 'firebase/firestore';
import { auth, db } from '../firebase';
import { Product, Review } from '../types';
import { useNotify } from '../components/Notifications';
import { motion, AnimatePresence } from 'framer-motion';

const ProductDetails: React.FC = () => {
  const { id } = useParams();
  const [product, setProduct] = useState<Product | null>(null);
  const [reviews, setReviews] = useState<Review[]>([]);
  const [activeImg, setActiveImg] = useState(0);
  const [fullScreenImg, setFullScreenImg] = useState<string | null>(null);
  const [isWishlisted, setIsWishlisted] = useState(false);

  const notify = useNotify();
  const navigate = useNavigate();

  useEffect(() => {
    window.scrollTo(0, 0);
    const fetchProduct = async () => {
      if (!id) return;
      const snap = await getDoc(doc(db, 'products', id));
      if (snap.exists()) {
        const productData = { id: snap.id, ...snap.data() } as Product;
        setProduct(productData);
      }
    };
    fetchProduct();

    if (id) {
      const q = query(collection(db, 'reviews'), where('productId', '==', id));
      onSnapshot(q, (snapshot) => {
        const reviewList = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Review));
        reviewList.sort((a, b) => b.createdAt - a.createdAt);
        setReviews(reviewList);
      });

      // Check wishlist status
      if (auth.currentUser) {
        const wishlistRef = doc(db, 'users', auth.currentUser.uid, 'wishlist', id);
        onSnapshot(wishlistRef, (snap) => {
          setIsWishlisted(snap.exists());
        });
      }
    }
  }, [id]);

  const toggleWishlist = async () => {
    if (!auth.currentUser) return notify("Please sign in to save items", "info");
    if (!product || !id) return;

    const wishlistRef = doc(db, 'users', auth.currentUser.uid, 'wishlist', id);
    if (isWishlisted) {
      await deleteDoc(wishlistRef);
      notify("Removed from wishlist", "info");
    } else {
      await setDoc(wishlistRef, {
        productId: id,
        name: product.name,
        image: product.image,
        price: product.price,
        rating: product.rating,
        addedAt: Date.now()
      });
      notify("Added to wishlist!", "success");
    }
  };

  const addToCart = () => {
    const cart = JSON.parse(localStorage.getItem('f_cart') || '[]');
    const existingIndex = cart.findIndex((item: any) => item.id === product?.id);
    if (existingIndex > -1) {
      cart[existingIndex].quantity += 1;
    } else {
      cart.push({ ...product, quantity: 1 });
    }
    localStorage.setItem('f_cart', JSON.stringify(cart));
    notify("Added to cart!", "success");
    navigate('/cart');
  };

  if (!product) return <div className="h-screen flex items-center justify-center"><div className="w-10 h-10 border-4 border-black border-t-transparent rounded-full animate-spin"></div></div>;

  const images = product.images || [product.image];

  return (
    <div className="animate-fade-in bg-white min-h-screen pb-32 max-w-7xl mx-auto flex flex-col lg:flex-row lg:items-start lg:p-12 lg:gap-20">

      {/* Image Gallery */}
      <div className="w-full lg:w-1/2 lg:sticky lg:top-12">
        <div className="relative aspect-square md:aspect-video lg:aspect-square bg-zinc-50 rounded-b-[48px] lg:rounded-[64px] overflow-hidden shadow-inner flex items-center justify-center border border-zinc-100 group">
          <button onClick={() => navigate(-1)} className="absolute top-6 left-6 z-10 p-3.5 bg-white/60 backdrop-blur-xl rounded-2xl text-black shadow-sm active:scale-90 transition-transform lg:hidden">
            <i className="fas fa-chevron-left text-sm"></i>
          </button>

          <button 
            onClick={toggleWishlist}
            className={`absolute top-6 right-6 z-10 p-3.5 rounded-2xl shadow-xl transition-all active:scale-90 ${isWishlisted ? 'bg-black text-white' : 'bg-white/60 backdrop-blur-xl text-black hover:bg-white'}`}
          >
            <i className={`${isWishlisted ? 'fas' : 'far'} fa-heart text-sm`}></i>
          </button>

          <motion.img 
            initial={{ scale: 0.9, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            key={activeImg}
            src={images[activeImg]} 
            className="w-full h-full object-contain p-8 md:p-16 lg:p-20 cursor-zoom-in group-hover:scale-105 transition-transform duration-700 rounded-[48px]"
            onClick={() => setFullScreenImg(images[activeImg])}
            alt={product.name}
          />

          {images.length > 1 && (
            <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex space-x-2.5 bg-black/5 backdrop-blur-2xl px-5 py-2.5 rounded-full border border-white/20 shadow-sm">
              {images.map((_, i) => (
                <div key={i} className={`h-1.5 rounded-full transition-all duration-300 ${i === activeImg ? 'w-8 bg-black' : 'w-2 bg-black/20'}`}></div>
              ))}
            </div>
          )}
        </div>

        {images.length > 1 && (
          <div className="flex justify-center flex-wrap gap-4 mt-8 px-6">
            {images.map((img, i) => (
              <button 
                key={i} 
                onClick={() => setActiveImg(i)}
                className={`w-16 h-16 md:w-20 md:h-20 rounded-3xl border-2 p-2 bg-zinc-50 transition-all ${i === activeImg ? 'border-black scale-110 shadow-xl' : 'border-transparent opacity-60 hover:opacity-100'}`}
              >
                <img src={img} className="w-full h-full object-contain rounded-xl" alt="" />
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Product Content */}
      <div className="px-6 py-10 lg:py-0 flex-1 max-w-2xl">
        <div className="mb-12">
           <p className="text-[10px] md:text-xs text-zinc-400 font-black uppercase tracking-[0.4em] mb-4">{product.category}</p>
           <h1 className="text-3xl md:text-5xl font-black tracking-tighter mb-6 leading-[1.1]">{product.name}</h1>
           <div className="flex items-center space-x-8">
              <p className="text-3xl md:text-4xl font-black">৳{product.price}</p>
              <div className="flex items-center space-x-3 bg-zinc-50 px-5 py-2.5 rounded-2xl border border-zinc-100 shadow-sm">
                 <i className="fas fa-star text-yellow-400 text-xs"></i>
                 <span className="text-sm font-black">{product.rating}</span>
                 <span className="text-[10px] font-bold text-zinc-300 uppercase tracking-widest">({product.numReviews} Reviews)</span>
              </div>
           </div>
        </div>

        <div className="mb-12">
            <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-zinc-900 mb-5">About Product</h3>
            <p className="text-sm md:text-lg text-zinc-500 leading-relaxed font-medium">
