import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { collection, addDoc, getDocs, deleteDoc, doc, updateDoc } from 'firebase/firestore';
import { db } from '../../firebase';
import { uploadToImgbb } from '../../services/imgbb';
import { useNotify, useConfirm } from '../../components/Notifications';
import { Product } from '../../types';
import { motion, AnimatePresence } from 'framer-motion';

const ManageProducts: React.FC = () => {
  const navigate = useNavigate();
  const [products, setProducts] = useState<Product[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const notify = useNotify();
  const confirm = useConfirm();

  const [formData, setFormData] = useState({
    name: '',
    price: 0,
    description: '',
    category: 'Mobile',
    stock: 10,
    imageFiles: [] as File[]
  });

  const fetchProducts = async () => {
    const snap = await getDocs(collection(db, 'products'));
    setProducts(snap.docs.map(d => ({ id: d.id, ...d.data() } as Product)));
  };

  useEffect(() => { fetchProducts(); }, []);

  const handleEdit = (product: Product) => {
    setEditingId(product.id);
    setFormData({
      name: product.name,
      price: product.price,
      description: product.description,
      category: product.category,
      stock: product.stock,
      imageFiles: []
    });
    setIsAdding(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      let imageUrls: string[] = [];
      if (formData.imageFiles.length > 0) {
        for (const file of formData.imageFiles) {
          const url = await uploadToImgbb(file);
          imageUrls.push(url);
        }
      }

      const productData: any = {
        name: formData.name,
        price: Number(formData.price),
        description: formData.description,
        category: formData.category,
        stock: Number(formData.stock),
      };

      if (imageUrls.length > 0) {
        productData.image = imageUrls[0];
        productData.images = imageUrls;
      }

      if (editingId) {
        await updateDoc(doc(db, 'products', editingId), productData);
        notify("Product synchronized", "success");
      } else {
        productData.rating = 5;
        productData.numReviews = 0;
        await addDoc(collection(db, 'products'), productData);
        notify("New product deployed", "success");
      }

      setIsAdding(false);
      setEditingId(null);
      fetchProducts();
    } catch (err) {
      notify("Logistics rejection", "error");
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = (id: string) => {
    confirm({
      title: "Confirm Deletion",
      message: "Permanently remove this asset from the active catalog?",
      onConfirm: async () => {
        await deleteDoc(doc(db, 'products', id));
        notify("Asset cleared", "info");
        fetchProducts();
      }
    });
  };

  return (
    <div className="max-w-[1440px] mx-auto px-6 md:px-12 py-10 pb-32 min-h-screen bg-[#FDFDFD]">
      {/* Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-6 mb-12">
        <div className="flex items-center space-x-6">
           <button onClick={() => navigate('/admin')} className="p-4 bg-zinc-900 text-white rounded-2xl shadow-xl active:scale-90 transition-all">
             <i className="fas fa-chevron-left text-xs"></i>
           </button>
           <div>
              <h1 className="text-3xl md:text-4xl font-black tracking-tighter">Inventory</h1>
              <p className="text-[10px] text-zinc-400 font-bold uppercase tracking-[0.3em] mt-1">Catalog Control Panel</p>
           </div>
        </div>
        <button 
          onClick={() => { setIsAdding(!isAdding); setEditingId(null); }}
          className={`px-8 py-4 rounded-[24px] font-black uppercase text-[10px] tracking-widest shadow-2xl transition-all active:scale-95 ${isAdding ? 'bg-red-500 text-white' : 'bg-black text-white shadow-zinc-200'}`}
        >
          {isAdding ? "Abort Operation" : "New Item +"}
        </button>
      </div>

      <AnimatePresence>
        {isAdding && (
          <motion.form 
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            onSubmit={handleSubmit} 
            className="bg-white p-8 md:p-12 rounded-[48px] shadow-sm mb-16 space-y-10 max-w-4xl mx-auto border border-zinc-100"
          >
            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
              <div>
                <label className="block text-[10px] font-black text-zinc-400 uppercase tracking-widest mb-4 px-2">Item Identity</label>
                <input 
                  type="text" className="w-full p-5 bg-zinc-50 rounded-[24px] outline-none border border-transparent focus:border-zinc-900 transition-all font-bold shadow-inner" required
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                />
              </div>
              <div>
                <label className="block text-[10px] font-black text-zinc-400 uppercase tracking-widest mb-4 px-2">Classification</label>
                <select 
                  className="w-full p-5 bg-zinc-50 rounded-[24px] outline-none border border-transparent focus:border-zinc-900 transition-all font-black uppercase text-[10px] tracking-widest shadow-inner cursor-pointer"
                  value={formData.category}
                  onChange={e => setFormData({...formData, category: e.target.value})}
                >
                  <option>Mobile</option>
                  <option>Accessories</option>
                  <option>Gadgets</option>
                  <option>Chargers</option>
                </select>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-10">
              <div>
                <label className="block text-[10px] font-black text-zinc-400 uppercase tracking-widest mb-4 px-2">Market Price (৳)</label>
                <input 
                  type="number" className="w-full p-5 bg-zinc-50 rounded-[24px] outline-none border border-transparent focus:border-zinc-900 transition-all font-black shadow-inner" required
                  value={formData.price}
                  onChange={e => setFormData({...formData, price: Number(e.target.value)})}
                />
              </div>
              <div>
                <label className="block text-[10px] font-black text-zinc-400 uppercase tracking-widest mb-4 px-2">Stock Level</label>
                <input 
                  type="number" className="w-full p-5 bg-zinc-50 rounded-[24px] outline-none border border-transparent focus:border-zinc-900 transition-all font-black shadow-inner" required
                  value={formData.stock}
                  onChange={e => setFormData({...formData, stock: Number(e.target.value)})}
                />
              </div>
            </div>

            <div>
              <label className="block text-[10px] font-black text-zinc-400 uppercase tracking-widest mb-4 px-2">Visual Assets (Upload)</label>
              <div className="relative group">
                <input 
                  type="file" className="w-full p-5 bg-zinc-50 rounded-[24px] outline-none text-[10px] font-black uppercase shadow-inner border border-dashed border-zinc-200 cursor-pointer" accept="image/*" multiple
                  onChange={e => {
                    if (e.target.files) {
                      setFormData({...formData, imageFiles: Array.from(e.target.files)});
                    }
                  }}
