import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { db } from '../../firebase';
import { collection, onSnapshot, query, orderBy, doc, updateDoc } from 'firebase/firestore';
import { Order, OrderStatus } from '../../types';
import { useNotify } from '../../components/Notifications';
import { sendOrderToSteadfast } from '../../services/steadfast';
import { motion, AnimatePresence } from 'framer-motion';

const ManageOrders: React.FC = () => {
  const navigate = useNavigate();
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncingId, setSyncingId] = useState<string | null>(null);
  const [viewingOrder, setViewingOrder] = useState<Order | null>(null);
  const notify = useNotify();

  useEffect(() => {
    const q = query(collection(db, 'orders'), orderBy('createdAt', 'desc'));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      setOrders(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order)));
      setLoading(false);
    });
    return unsubscribe;
  }, []);

  const handleSendToSteadfast = async (order: Order) => {
    setSyncingId(order.id);
    try {
        const result = await sendOrderToSteadfast(order);
        if (result && result.status === 200 && result.consignment) {
            await updateDoc(doc(db, 'orders', order.id), { 
                steadfastId: result.consignment.tracking_code,
                steadfastStatus: result.consignment.status,
                status: OrderStatus.SHIPPED
            });
            notify("Logistics updated", "success");
        } else {
            notify(result?.message || "Courier error", "error");
        }
    } catch (e) {
        notify("Gateway timeout", "error");
    } finally {
        setSyncingId(null);
    }
  };

  const getStatusColor = (status: OrderStatus) => {
    switch(status) {
      case OrderStatus.DELIVERED: return 'bg-green-100 text-green-600';
      case OrderStatus.SHIPPED: return 'bg-blue-100 text-blue-600';
      case OrderStatus.PROCESSING: return 'bg-orange-100 text-orange-600';
      case OrderStatus.CANCELLED: return 'bg-red-100 text-red-600';
      default: return 'bg-zinc-100 text-zinc-500';
    }
  };

  return (
    <div className="max-w-[1440px] mx-auto px-6 md:px-12 py-10 pb-32 min-h-screen bg-[#FDFDFD]">
      <div className="mb-12 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-6">
        <div className="flex items-center space-x-6">
          <button onClick={() => navigate('/admin')} className="p-4 bg-zinc-900 text-white rounded-2xl shadow-xl active:scale-90 transition-all">
            <i className="fas fa-chevron-left text-xs"></i>
          </button>
          <div>
            <h1 className="text-3xl md:text-4xl font-black tracking-tighter">Orders</h1>
            <p className="text-[10px] text-zinc-400 font-bold uppercase tracking-[0.3em] mt-1">Shipping & Logistics</p>
          </div>
        </div>
        <div className="bg-zinc-100 px-6 py-2.5 rounded-2xl border border-zinc-200 text-[10px] font-black uppercase tracking-widest">
           Manifest Volume: {orders.length}
        </div>
      </div>

      <div className="space-y-8">
        {loading ? (
           <div className="py-20 text-center animate-pulse font-black text-xs uppercase tracking-[0.5em] text-zinc-300">Synchronizing Logistics...</div>
        ) : orders.map(order => (
          <motion.div 
            layout
            key={order.id} 
            className="bg-white rounded-[48px] border border-zinc-100 overflow-hidden shadow-sm flex flex-col lg:flex-row group transition-all hover:shadow-2xl hover:border-zinc-200"
          >
            {/* Status & Customer Info */}
            <div className="p-8 md:p-12 lg:w-[400px] border-b lg:border-b-0 lg:border-r border-zinc-100 space-y-10 flex flex-col justify-between">
              <div>
                <div className="flex justify-between items-start mb-10">
                   <div>
                      <p className="text-[9px] font-black text-zinc-300 uppercase tracking-widest mb-1">Order ID</p>
                      <p className="text-sm font-mono font-black tracking-tighter">#{order.id.slice(0,12).toUpperCase()}</p>
                   </div>
                   <span className={`px-4 py-2 rounded-2xl text-[9px] font-black uppercase tracking-widest ${getStatusColor(order.status)}`}>
                      {order.status}
                   </span>
                </div>

                <div className="space-y-6">
                   <div className="flex items-center space-x-4">
                      <div className="w-12 h-12 bg-zinc-50 rounded-2xl flex items-center justify-center border border-zinc-100">
                         <i className="fas fa-user text-xs opacity-20"></i>
                      </div>
                      <div>
                         <p className="text-[9px] font-black text-zinc-300 uppercase tracking-tighter">Customer</p>
                         <p className="text-xs font-bold tracking-tight">{order.customerName}</p>
                      </div>
                   </div>
                   <div className="flex items-center space-x-4">
                      <div className="w-12 h-12 bg-zinc-50 rounded-2xl flex items-center justify-center border border-zinc-100">
                         <i className="fas fa-phone-alt text-xs opacity-20"></i>
                      </div>
                      <div>
                         <p className="text-[9px] font-black text-zinc-300 uppercase tracking-tighter">Phone</p>
                         <p className="text-xs font-bold tracking-tight">{order.contactNumber}</p>
                      </div>
                   </div>
                </div>
              </div>

              <button 
                onClick={() => setViewingOrder(order)}
                className="w-full py-5 bg-zinc-50 hover:bg-zinc-900 hover:text-white text-zinc-900 rounded-[24px] text-[10px] font-black uppercase tracking-widest transition-all active:scale-[0.98] border border-zinc-100"
              >
                Inspect Manifest
              </button>
            </div>

            {/* Cart & Actions */}
            <div className="p-8 md:p-12 flex-1 space-y-10 flex flex-col justify-between">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-10 lg:gap-16">
                  <div>
                    <h4 className="text-[10px] font-black text-zinc-300 uppercase tracking-widest mb-6">Product Manifest</h4>
                    <div className="space-y-4">
                       {order.items.map((item, idx) => (
                          <div key={idx} className="flex items-center space-x-4 p-3 bg-zinc-50 rounded-2xl border border-zinc-100">
                             <img src={item.image} className="w-12 h-12 rounded-[14px] object-contain bg-white" alt="" />
                             <div className="flex-1 min-w-0">
                                <p className="text-[11px] font-bold truncate">{item.name}</p>
                                <p className="text-[9px] text-zinc-400 font-bold uppercase">৳{item.priceAtPurchase} x {item.quantity}</p>
                             </div>
                          </div>
                       ))}
                    </div>
                  </div>
                  <div>
                    <h4 className="text-[10px] font-black text-zinc-300 uppercase tracking-widest mb-6">Shipping Node</h4>
                    <div className="p-6 bg-zinc-50 rounded-3xl border border-zinc-100 text-xs font-medium leading-relaxed italic text-zinc-400">
                       {order.shippingAddress}
                    </div>
                    <div className="mt-8 flex justify-between items-end">
                       <div>
                          <p className="text-[9px] font-black text-zinc-300 uppercase tracking-widest mb-1">Grand Total</p>
                          <p className="text-3xl font-black tracking-tighter">৳{order.total}</p>
                       </div>
                       <div className="text-right">
                          <p className="text-[9px] font-black text-zinc-300 uppercase tracking-widest mb-1">Method</p>
                          <p className="text-[10px] font-bold uppercase">{order.paymentMethod}</p>
                       </div>
                    </div>
                  </div>
               </div>

               <div className="flex items-center justify-between pt-10 border-t border-zinc-100">
                  <div className="flex items-center space-x-3">
                     <div className={`w-3 h-3 rounded-full ${order.steadfastId ? 'bg-green-500' : 'bg-zinc-200'}`}></div>
                     <span className="text-[10px] font-black uppercase tracking-widest text-zinc-400">Courier Status</span>
                  </div>
                  {order.steadfastId ? (
                    <div className="flex items-center space-x-3 px-6 py-3.5 bg-green-50 text-green-600 rounded-2xl border border-green-100">
                       <i className="fas fa-check-circle text-xs"></i>
                       <span className="text-[10px] font-black uppercase tracking-widest">Handed to Steadfast</span>
                    </div>
                  ) : (
                    <button 
                      disabled={syncingId === order.id}
                      onClick={() => handleSendToSteadfast(order)}
                      className="px-8 py-5 bg-black text-white rounded-[24px] text-[10px] font-black uppercase tracking-widest flex items-center space-x-3 shadow-2xl transition-all active:scale-[0.98] disabled:opacity-50"
                    >
                      {syncingId === order.id ? <i className="fas fa-circle-notch animate-spin"></i> : <i className="fas fa-rocket"></i>}
                      <span>Initialize Delivery</span>
                    </button>
                  )}
               </div>
            </div>
          </motion.div>
        ))}
      </div>

      {/* Detailed Inspection Modal */}
      <AnimatePresence>
        {viewingOrder && (
          <div className="fixed inset-0 bg-black/80 backdrop-blur-2xl z-[1000] flex items-center justify-center p-6 md:p-12" onClick={() => setViewingOrder(null)}>
            <motion.div 
               initial={{ scale: 0.9, opacity: 0 }}
               animate={{ scale: 1, opacity: 1 }}
               exit={{ scale: 0.9, opacity: 0 }}
               className="bg-white w-full max-w-5xl rounded-[64px] overflow-hidden shadow-2xl flex flex-col lg:flex-row h-full max-h-[90vh] cursor-default"
               onClick={e => e.stopPropagation()}
            >
               <div className="lg:w-1/3 bg-zinc-900 p-12 text-white flex flex-col justify-between">
                  <div>
                    <h2 className="text-5xl font-black tracking-tighter mb-4">Invoice.</h2>
                    <p className="text-[10px] font-black uppercase tracking-[0.4em] opacity-40">Detail Inspection Node</p>
                  </div>
                  <div className="space-y-6">
                     <div className="p-6 bg-white/5 rounded-3xl border border-white/5">
                        <p className="text-[9px] font-black uppercase opacity-30 tracking-widest mb-1">Handover Stage</p>
                        <p className="text-xs font-bold text-blue-400">{viewingOrder.status}</p>
                     </div>
                     <button onClick={() => setViewingOrder(null)} className="w-full py-5 bg-white text-zinc-900 rounded-[28px] font-black uppercase text-[10px] tracking-widest shadow-xl active:scale-95 transition-all">Close Log</button>
                  </div>
               </div>
               <div className="flex-1 p-12 overflow-y-auto no-scrollbar space-y-12">
                  <section>
                    <h4 className="text-[10px] font-black text-zinc-300 uppercase tracking-[0.4em] border-b border-zinc-100 pb-3 mb-8">Financial Overview</h4>
                    <div className="space-y-4">
                       <DetailItem label="Cart Items Value" value={`৳${viewingOrder.total - 150}`} />
                       <DetailItem label="Shipping Charge" value="৳150" />
                       <DetailItem label="Payment Gateway" value={viewingOrder.paymentMethod} />
                       <DetailItem label="Gateway ID" value={viewingOrder.transactionId || 'NOT_FOUND'} />
                    </div>
                  </section>
                  <section>
                    <h4 className="text-[10px] font-black text-zinc-300 uppercase tracking-[0.4em] border-b border-zinc-100 pb-3 mb-8">Courier Intelligence</h4>
