                       <DetailItem label="Partner Node" value="Steadfast (BD)" />
                       <DetailItem label="Partner Ref ID" value={viewingOrder.steadfastId || 'PENDING'} />
                       <DetailItem label="Sync Timestamp" value={new Date(viewingOrder.createdAt).toLocaleString()} />
