import React, { useState, createContext, useContext } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

type ToastType = 'success' | 'error' | 'info';

interface Toast {
  id: number;
  message: string;
  type: ToastType;
}

interface ConfirmOptions {
  title: string;
  message: string;
  onConfirm: () => void;
  onCancel?: () => void;
  confirmText?: string;
  cancelText?: string;
}

interface ToastContextType {
  notify: (message: string, type?: ToastType) => void;
  confirm: (options: ConfirmOptions) => void;
}

const ToastContext = createContext<ToastContextType | undefined>(undefined);

export const ToastProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [confirmModal, setConfirmModal] = useState<ConfirmOptions | null>(null);

  const notify = (message: string, type: ToastType = 'info') => {
    const id = Date.now();
    setToasts((prev) => [...prev, { id, message, type }]);
    setTimeout(() => {
      setToasts((prev) => prev.filter((t) => t.id !== id));
    }, 4000);
  };

  const confirm = (options: ConfirmOptions) => {
    setConfirmModal(options);
  };

  return (
    <ToastContext.Provider value={{ notify, confirm }}>
      {children}

      {/* Fluid Toasts */}
      <div className="fixed top-6 right-6 z-[9999] flex flex-col gap-3 pointer-events-none w-full max-w-[400px]">
        <AnimatePresence>
          {toasts.map((toast) => (
            <motion.div
              key={toast.id}
              initial={{ opacity: 0, x: 50, scale: 0.9 }}
              animate={{ opacity: 1, x: 0, scale: 1 }}
              exit={{ opacity: 0, scale: 0.8, x: 20 }}
              className={`pointer-events-auto p-4 rounded-[1.5rem] shadow-[0_20px_40px_rgba(0,0,0,0.1)] flex items-center justify-between border ${
                toast.type === 'success' ? 'bg-white border-green-100 text-green-800' : 
                toast.type === 'error' ? 'bg-white border-red-100 text-red-800' : 
                'bg-white border-zinc-100 text-zinc-800'
              }`}
            >
              <div className="flex items-center space-x-3">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center ${
                  toast.type === 'success' ? 'bg-green-100' : 
                  toast.type === 'error' ? 'bg-red-100' : 
                  'bg-zinc-100'
                }`}>
                  <i className={`fas ${toast.type === 'success' ? 'fa-check' : toast.type === 'error' ? 'fa-exclamation' : 'fa-info'} text-xs`}></i>
                </div>
                <p className="font-bold text-sm tracking-tight">{toast.message}</p>
              </div>
              <button onClick={() => setToasts(prev => prev.filter(t => t.id !== toast.id))} className="ml-4 opacity-30 hover:opacity-100">
                <i className="fas fa-times text-xs"></i>
              </button>
            </motion.div>
          ))}
        </AnimatePresence>
      </div>

      {/* Confirmation Modal */}
      <AnimatePresence>
        {confirmModal && (
          <div className="fixed inset-0 z-[10000] flex items-center justify-center p-6">
            <motion.div 
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="absolute inset-0 bg-black/40 backdrop-blur-md"
              onClick={() => setConfirmModal(null)}
            />
            <motion.div 
              initial={{ opacity: 0, scale: 0.9, y: 20 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.9, y: 20 }}
              className="bg-white rounded-[2.5rem] p-8 w-full max-w-sm shadow-2xl relative z-10 text-center border border-zinc-100"
            >
              <div className="w-20 h-20 bg-zinc-50 rounded-[2rem] flex items-center justify-center mx-auto mb-6 text-2xl">
                 🤔
              </div>
              <h3 className="text-2xl font-black mb-3 tracking-tighter">{confirmModal.title}</h3>
              <p className="text-sm text-zinc-500 font-medium leading-relaxed mb-10 px-2">{confirmModal.message}</p>
              <div className="flex flex-col gap-3">
                <button 
                  onClick={() => { confirmModal.onConfirm(); setConfirmModal(null); }}
                  className="w-full py-4.5 bg-black text-white rounded-[1.5rem] font-bold text-sm uppercase tracking-widest active:scale-95 transition-all shadow-xl shadow-black/10"
                >
                  {confirmModal.confirmText || 'Confirm'}
                </button>
                <button 
                  onClick={() => { if(confirmModal.onCancel) confirmModal.onCancel(); setConfirmModal(null); }}
                  className="w-full py-4 text-zinc-400 font-bold text-xs uppercase tracking-widest active:scale-95 transition-all"
                >
                  {confirmModal.cancelText || 'Cancel'}
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </ToastContext.Provider>
  );
};

export const useNotify = () => {
  const context = useContext(ToastContext);
  if (!context) throw new Error("useNotify must be used within ToastProvider");
  return context.notify;
};

export const useConfirm = () => {
  const context = useContext(ToastContext);
  if (!context) throw new Error("useConfirm must be used within ToastProvider");
  return context.confirm;
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { auth, db } from '../firebase';
import { collection, addDoc, doc, getDoc } from 'firebase/firestore';
import { useNotify } from '../components/Notifications';
import { OrderStatus, UserProfile } from '../types';
import { sendOrderToTelegram } from '../services/telegram';
import { motion } from 'framer-motion';

const CheckoutPage: React.FC = () => {
  const [items, setItems] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);

  const [shipping, setShipping] = useState({
    name: '',
    address: localStorage.getItem('vibe_shipping_address') || 'Dhaka, Bangladesh',
    phone: '',
    payment: 'Cash on Delivery',
    paymentOption: 'Full Payment' as 'Full Payment' | 'Delivery Fee Only',
    trxId: ''
  });

  const navigate = useNavigate();
  const notify = useNotify();

  useEffect(() => {
    const cart = JSON.parse(localStorage.getItem('f_cart') || '[]');
    if (cart.length === 0) { navigate('/'); return; }
    setItems(cart);

    const user = auth.currentUser;
    if (user) {
      getDoc(doc(db, 'users', user.uid)).then(snap => {
        if (snap.exists()) {
          const data = snap.data() as UserProfile;
          setShipping(prev => ({ 
            ...prev, 
            name: data.displayName || '', 
            phone: data.phoneNumber || '',
            address: data.address || prev.address
          }));
        }
      });
    }
  }, []);

  const subTotal = items.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
  const deliveryFee = 150; 
  const grandTotal = subTotal + deliveryFee;

  const placeOrder = async () => {
    if (!shipping.name || !shipping.address || !shipping.phone) return notify("Please fill in all shipping details", "error");
    if (shipping.payment !== 'Cash on Delivery' && !shipping.trxId) return notify("Transaction ID is required for digital payments", "error");

    setLoading(true);
    try {
      const orderData = {
        userId: auth.currentUser?.uid || 'guest',
        customerName: shipping.name,
        items: items.map(i => ({ productId: i.id, quantity: i.quantity, priceAtPurchase: i.price, name: i.name, image: i.image })),
        total: grandTotal,
        status: OrderStatus.PROCESSING,
        paymentMethod: shipping.payment,
        paymentOption: shipping.payment === 'Cash on Delivery' ? null : shipping.paymentOption,
        transactionId: shipping.trxId,
        shippingAddress: shipping.address,
        contactNumber: shipping.phone,
        createdAt: Date.now()
      };

      const docRef = await addDoc(collection(db, 'orders'), orderData);
      await sendOrderToTelegram({ ...orderData, id: docRef.id });

      localStorage.removeItem('f_cart');
      notify("Order Placed Successfully!", "success");
      navigate(`/success?orderId=${docRef.id}`);
    } catch (err) {
      notify("Failed to process order. Please try again.", "error");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-6 md:px-12 py-10 pb-32 bg-white min-h-screen">
      <div className="flex items-center space-x-6 mb-12">
          <button onClick={() => navigate(-1)} className="p-3.5 bg-zinc-50 rounded-2xl shadow-sm hover:bg-zinc-900 hover:text-white transition-all">
             <i className="fas fa-chevron-left text-xs"></i>
          </button>
          <h1 className="text-3xl md:text-5xl font-black tracking-tighter">Checkout.</h1>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
        <div className="lg:col-span-7 space-y-12">
          <section className="bg-zinc-50 p-8 md:p-12 rounded-[2.5rem] border border-zinc-100 shadow-sm">
            <h2 className="text-xs font-black text-zinc-900 uppercase tracking-widest mb-10">Shipping Information</h2>
            <div className="space-y-8">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div>
                    <label className="text-[10px] font-bold text-zinc-400 uppercase mb-3 block px-1">Full Name</label>
                    <input 
                        type="text" 
                        placeholder="e.g. John Doe"
                        className="w-full bg-white px-6 py-5 rounded-[1.5rem] text-sm font-bold outline-none border border-transparent focus:border-black shadow-sm transition-all"
                        value={shipping.name}
                        onChange={(e) => setShipping({...shipping, name: e.target.value})}
                    />
                  </div>
                  <div>
                    <label className="text-[10px] font-bold text-zinc-400 uppercase mb-3 block px-1">Phone Number</label>
                    <input 
                        type="tel" 
                        placeholder="01XXXXXXXXX"
                        className="w-full bg-white px-6 py-5 rounded-[1.5rem] text-sm font-bold outline-none border border-transparent focus:border-black shadow-sm transition-all"
                        value={shipping.phone}
                        onChange={(e) => setShipping({...shipping, phone: e.target.value})}
                    />
                  </div>
               </div>
               <div>
                  <label className="text-[10px] font-bold text-zinc-400 uppercase mb-3 block px-1">Delivery Address</label>
                  <textarea 
                      placeholder="Enter full address details..."
                      className="w-full bg-white px-6 py-5 rounded-[2rem] text-sm font-bold outline-none border border-transparent focus:border-black h-32 shadow-sm transition-all leading-relaxed"
                      value={shipping.address}
                      onChange={(e) => setShipping({...shipping, address: e.target.value})}
                  />
               </div>

               {/* Delivery Partners Info */}
               <div className="flex items-center space-x-3 p-4 bg-white rounded-2xl border border-zinc-200">
                  <div className="w-10 h-10 rounded-xl bg-zinc-50 flex items-center justify-center text-lg">🚚</div>
                  <div className="flex-1">
                     <p className="text-[10px] font-black uppercase text-zinc-400 tracking-widest">Courier Partners</p>
                     <p className="text-xs font-bold text-zinc-900">Delivery via Steadfast or Pathao</p>
                  </div>
               </div>
            </div>
          </section>

          <section className="bg-zinc-50 p-8 md:p-12 rounded-[2.5rem] border border-zinc-100 shadow-sm">
            <h2 className="text-xs font-black text-zinc-900 uppercase tracking-widest mb-10">Payment Method</h2>

            <div className="flex bg-zinc-200/40 p-1.5 rounded-[1.5rem] mb-10 max-w-sm">
              {['Cash on Delivery', 'bKash'].map(m => (
                <button 
                  key={m}
                  onClick={() => setShipping({...shipping, payment: m})}
                  className={`flex-1 py-4 rounded-[1.2rem] text-xs font-bold transition-all ${shipping.payment === m ? 'bg-black text-white shadow-xl' : 'text-zinc-500 hover:text-zinc-700'}`}
                >
                  {m === 'Cash on Delivery' ? 'COD' : 'bKash'}
                </button>
              ))}
            </div>

            {shipping.payment === 'bKash' && (
              <motion.div 
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                className="space-y-8 bg-white p-8 rounded-[2rem] shadow-sm mb-6 border border-zinc-100"
              >
                 <div className="flex justify-between items-center bg-zinc-50 p-6 rounded-[1.5rem] border border-zinc-100">
                    <span className="text-xs font-bold text-zinc-400 uppercase">Merchant No.</span>
                    <span className="font-black text-lg tracking-widest">01747708843</span>
                 </div>

                 <div>
                    <label className="text-[10px] font-bold text-zinc-400 uppercase mb-3 block px-1">Transaction ID (TrxID)</label>
                    <input 
                        type="text" 
                        placeholder="Enter 10-digit ID"
                        className="w-full bg-zinc-50 px-6 py-5 rounded-[1.5rem] text-sm font-bold outline-none border border-transparent focus:border-black shadow-inner uppercase"
                        value={shipping.trxId}
                        onChange={(e) => setShipping({...shipping, trxId: e.target.value.toUpperCase()})}
                    />
                 </div>
              </motion.div>
            )}
          </section>
        </div>

        {/* Order Summary Side */}
        <div className="lg:col-span-5">
           <div className="bg-zinc-900 text-white p-10 md:p-12 rounded-[3.5rem] sticky top-12 shadow-2xl">
              <h3 className="text-xs font-black uppercase tracking-[0.2em] text-white/40 mb-10">Order Summary</h3>

              <div className="space-y-6 mb-12 max-h-[300px] overflow-y-auto no-scrollbar pr-2">
                 {items.map((item, idx) => (
                    <div key={idx} className="flex items-center space-x-5">
                       <div className="w-14 h-14 bg-white/10 rounded-2xl overflow-hidden p-2 flex items-center justify-center shrink-0">
                          <img src={item.image} className="w-full h-full object-contain rounded-lg" alt="" />
                       </div>
                       <div className="flex-1 min-w-0">
                          <p className="text-sm font-bold truncate">{item.name}</p>
                          <p className="text-xs text-white/40 font-medium">Qty: {item.quantity}</p>
                       </div>
                       <p className="text-sm font-black">৳{item.price * item.quantity}</p>
                    </div>
                 ))}
              </div>

              <div className="space-y-5 pt-8 border-t border-white/10">
                <div className="flex justify-between text-xs font-medium text-white/50">
                  <span>Subtotal</span>
                  <span>৳{subTotal}</span>
                </div>
                <div className="flex justify-between text-xs font-medium text-white/50">
                  <span>Delivery Charge</span>
                  <span>৳{deliveryFee}</span>
                </div>
                <div className="flex justify-between font-black text-4xl tracking-tighter pt-4">
                  <span>Total</span>
                  <span>৳{grandTotal}</span>
                </div>
              </div>

              <button 
                disabled={loading}
                onClick={placeOrder}
                className="w-full mt-12 py-6 bg-white text-zinc-900 rounded-[2rem] font-black text-sm uppercase tracking-widest hover:scale-[1.02] active:scale-95 transition-all shadow-xl disabled:opacity-50"
              >
                {loading ? "Processing..." : "Complete Order"}
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

export default CheckoutPage;

