import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { auth, db } from '../firebase';
import { collection, addDoc, doc, getDoc } from 'firebase/firestore';
import { useNotify } from '../components/Notifications';
import { OrderStatus, UserProfile } from '../types';
import { sendOrderToTelegram } from '../services/telegram';
import { motion } from 'framer-motion';

const CheckoutPage: React.FC = () => {
  const [items, setItems] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [shipping, setShipping] = useState({
    name: '',
    address: localStorage.getItem('vibe_shipping_address') || '',
    phone: '',
    payment: 'Cash on Delivery',
    paymentOption: 'Full Payment',
    trxId: ''
  });

  const navigate = useNavigate();
  const notify = useNotify();

  useEffect(() => {
    const cart = JSON.parse(localStorage.getItem('f_cart') || '[]');
    if (cart.length === 0) { navigate('/'); return; }
    setItems(cart);
    if (auth.currentUser) {
      getDoc(doc(db, 'users', auth.currentUser.uid)).then(snap => {
        if (snap.exists()) {
          const data = snap.data() as UserProfile;
          setShipping(prev => ({ ...prev, name: data.displayName || '', phone: data.phoneNumber || '' }));
        }
      });
    }
  }, []);

  const copyNumber = () => {
    navigator.clipboard.writeText("01747708843");
    notify("Number copied to clipboard", "success");
  };

  const placeOrder = async () => {
    if (!shipping.name || !shipping.address || !shipping.phone) return notify("Full details required", "error");
    if (shipping.payment === 'bKash' && !shipping.trxId) return notify("Transaction ID required", "error");

    setLoading(true);
    try {
      const orderData = {
        userId: auth.currentUser?.uid || 'guest',
        customerName: shipping.name,
        items: items.map(i => ({ productId: i.id, quantity: i.quantity, priceAtPurchase: i.price, name: i.name, image: i.image })),
        total: items.reduce((a,c)=>a+(c.price*c.quantity), 0) + 150,
        status: OrderStatus.PROCESSING,
        paymentMethod: shipping.payment,
        paymentOption: shipping.paymentOption,
        transactionId: shipping.trxId,
        shippingAddress: shipping.address,
        contactNumber: shipping.phone,
        createdAt: Date.now()
      };

      const docRef = await addDoc(collection(db, 'orders'), orderData);
      await sendOrderToTelegram({ ...orderData, id: docRef.id });
      localStorage.removeItem('f_cart');
      notify("Order Placed Successfully!", "success");
      navigate(`/success?orderId=${docRef.id}`);
    } catch (err) { notify("Order failed", "error"); } finally { setLoading(false); }
  };

  return (
    <div className="max-w-7xl mx-auto px-6 py-10 pb-32 bg-white min-h-screen">
      <div className="flex items-center space-x-6 mb-12">
          <button onClick={() => navigate(-1)} className="p-3.5 bg-zinc-50 rounded-2xl"><i className="fas fa-chevron-left text-xs"></i></button>
          <h1 className="text-3xl font-black tracking-tighter">Checkout.</h1>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
        <div className="lg:col-span-7 space-y-12">
          <section className="bg-zinc-50 p-8 md:p-12 rounded-[3rem] border border-zinc-100 shadow-sm">
            <h2 className="text-xs font-black uppercase tracking-widest text-zinc-900 mb-10">Shipping Information</h2>
            <div className="space-y-8">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <Input label="Recipient Name" value={shipping.name} onChange={v => setShipping({...shipping, name: v})} />
                  <Input label="Contact Number" value={shipping.phone} onChange={v => setShipping({...shipping, phone: v})} />
               </div>
               <div>
                  <label className="text-[10px] font-bold text-zinc-400 uppercase mb-3 block px-1">Full Address</label>
                  <textarea className="w-full bg-white px-6 py-5 rounded-[2rem] text-sm font-bold h-32 outline-none shadow-sm focus:ring-1 focus:ring-black" value={shipping.address} onChange={e => setShipping({...shipping, address: e.target.value})} />
               </div>
            </div>
          </section>

          <section className="bg-zinc-50 p-8 md:p-12 rounded-[3rem] border border-zinc-100 shadow-sm">
            <h2 className="text-xs font-black uppercase tracking-widest text-zinc-900 mb-10">Payment Gateway</h2>
            <div className="flex bg-zinc-200/40 p-1.5 rounded-[2rem] mb-10 max-w-xs">
              {['Cash on Delivery', 'bKash'].map(m => (
                <button key={m} onClick={() => setShipping({...shipping, payment: m})} className={`flex-1 py-4 rounded-[1.8rem] text-xs font-bold transition-all ${shipping.payment === m ? 'bg-black text-white shadow-xl' : 'text-zinc-500'}`}>
                  {m === 'bKash' ? 'bKash' : 'COD'}
                </button>
              ))}
            </div>

            {shipping.payment === 'bKash' && (
              <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="space-y-8 bg-white p-8 rounded-[2.5rem] shadow-sm border border-zinc-100">
                 <div className="flex justify-between items-center bg-zinc-50 p-6 rounded-2xl">
                    <div><p className="text-[10px] font-bold text-zinc-400 uppercase mb-1">Personal Number</p><p className="font-black text-xl tracking-widest">01747708843</p></div>
                    <button onClick={copyNumber} className="p-4 bg-black text-white rounded-2xl active:scale-90 transition-all shadow-xl"><i className="fas fa-copy"></i></button>
                 </div>
                 <Input label="Transaction ID (TrxID)" value={shipping.trxId} onChange={v => setShipping({...shipping, trxId: v.toUpperCase()})} placeholder="e.g. A2B3C4D5" />
              </motion.div>
            )}
          </section>
        </div>

        <div className="lg:col-span-5">
           <div className="bg-zinc-900 text-white p-10 md:p-12 rounded-[4rem] shadow-2xl sticky top-12">
              <h3 className="text-xs font-black uppercase tracking-widest text-white/30 mb-10">Checkout Summary</h3>
              <div className="space-y-5 pt-8 border-t border-white/10">
                <div className="flex justify-between font-black text-4xl tracking-tighter pt-4"><span>Total</span><span>৳{items.reduce((a,c)=>a+(c.price*c.quantity),0)+150}</span></div>
              </div>
              <button disabled={loading} onClick={placeOrder} className="w-full mt-12 py-6 bg-white text-black rounded-[2rem] font-black text-xs uppercase tracking-widest shadow-xl hover:scale-[1.02] active:scale-95 transition-all">
                {loading ? "Processing..." : "Place Order Now"}
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

const Input = ({ label, value, onChange, placeholder }: any) => (
  <div className="w-full">
    <label className="text-[10px] font-bold text-zinc-400 uppercase mb-3 block px-1">{label}</label>
    <input type="text" placeholder={placeholder} className="w-full bg-white px-6 py-5 rounded-[1.8rem] text-sm font-bold outline-none shadow-sm focus:ring-1 focus:ring-black transition-all" value={value} onChange={e => onChange(e.target.value)} />
  </div>
);

export default CheckoutPage;

import React, { useState, useEffect } from 'react';
