const StatusIcon = ({ status }: { status: OrderStatus }) => {
  switch (status) {
    case OrderStatus.HOLD:
      return <svg className="w-12 h-12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>;
    case OrderStatus.PROCESSING:
      return <svg className="w-12 h-12 animate-spin-slow" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M12 22C17.5228 22 22 17.5228 22 12C22 6.47715 17.5228 2 12 2C6.47715 2 2 6.47715 2 12C2 17.5228 6.47715 22 12 22Z"/><path d="M12 6V12L16 14"/></svg>;
    case OrderStatus.SHIPPED:
      return <svg className="w-12 h-12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><rect x="1" y="3" width="15" height="13"/><polygon points="16 8 20 8 23 11 23 16 16 16 16 8"/><circle cx="5.5" cy="18.5" r="2.5"/><circle cx="18.5" cy="18.5" r="2.5"/></svg>;
    case OrderStatus.DELIVERED:
      return <svg className="w-12 h-12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>;
    default:
      return <svg className="w-12 h-12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><circle cx="12" cy="12" r="10"/><line x1="12" y1="12" x2="12" y2="12.01"/></svg>;
  }
};

const TrackOrder: React.FC = () => {
  const navigate = useNavigate();
  const { id } = useParams();
  const [order, setOrder] = useState<Order | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!id) return;
    const unsubscribe = onSnapshot(doc(db, 'orders', id), (snap) => {
      if (snap.exists()) setOrder({ id: snap.id, ...snap.data() } as Order);
      setLoading(false);
    });
    return unsubscribe;
  }, [id]);

  if (loading) return <div className="h-screen flex items-center justify-center"><div className="w-8 h-8 border-4 border-black border-t-transparent rounded-full animate-spin"></div></div>;
  if (!order) return <div className="h-screen flex flex-col items-center justify-center p-10"><p className="font-bold mb-6">Order not found.</p><button onClick={() => navigate('/')} className="btn-primary w-full">Return Home</button></div>;

  return (
    <div className="p-6 md:p-12 pb-32 min-h-screen bg-white max-w-md mx-auto animate-fade-in">
       <div className="flex items-center space-x-6 mb-12">
          <button onClick={() => navigate(-1)} className="p-3.5 bg-zinc-50 rounded-2xl shadow-sm"><i className="fas fa-chevron-left text-xs"></i></button>
          <h1 className="text-2xl font-black tracking-tight">Track Order.</h1>
       </div>

       <div className="bg-zinc-50 rounded-[3rem] p-10 flex flex-col items-center text-center border border-zinc-100 shadow-sm mb-10">
          <div className="mb-8 text-zinc-900"><StatusIcon status={order.status} /></div>
          <h2 className="text-2xl font-black mb-2 tracking-tight">{order.status}</h2>
          <p className="text-[10px] font-bold text-zinc-400 uppercase tracking-widest">Tracking ID: {order.trackingId || 'Preparing...'}</p>
       </div>

       <div className="space-y-6">
          <h3 className="text-[10px] font-black uppercase tracking-widest text-zinc-400 px-2">Order History</h3>
          <div className="bg-zinc-50 rounded-[2.5rem] p-8 border border-zinc-100 space-y-8">
             <Step label="Package Received" sub="The order has been confirmed." active />
             <Step label="Quality Control" sub="Items are being inspected." active={order.status !== OrderStatus.PENDING} />
             <Step label="Out for Delivery" sub="Your gear is with our partner." active={order.status === OrderStatus.SHIPPED || order.status === OrderStatus.DELIVERED} />
             <Step label="Delivered" sub="Enjoy your new gadgets!" active={order.status === OrderStatus.DELIVERED} />
          </div>
       </div>
    </div>
  );
};

const Step = ({ label, sub, active }: any) => (
  <div className="flex space-x-6">
    <div className="flex flex-col items-center">
       <div className={`w-3 h-3 rounded-full ${active ? 'bg-black shadow-lg shadow-black/20' : 'bg-zinc-200'}`}></div>
       <div className="w-0.5 h-full bg-zinc-100"></div>
    </div>
    <div className="-translate-y-1">
       <h4 className={`text-xs font-black uppercase tracking-tight ${active ? 'text-zinc-900' : 'text-zinc-300'}`}>{label}</h4>
       <p className="text-[10px] font-medium text-zinc-400 mt-1">{sub}</p>
    </div>
  </div>
);

export default TrackOrder;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { db } from '../../firebase';
import { collection, onSnapshot, query, orderBy, doc, updateDoc } from 'firebase/firestore';
import { Order, OrderStatus } from '../../types';
import { useNotify } from '../../components/Notifications';
import { motion } from 'framer-motion';

const ManageOrders: React.FC = () => {
  const navigate = useNavigate();
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [updatingId, setUpdatingId] = useState<string | null>(null);
  const notify = useNotify();

  useEffect(() => {
    const q = query(collection(db, 'orders'), orderBy('createdAt', 'desc'));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      setOrders(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order)));
      setLoading(false);
    });
    return unsubscribe;
  }, []);

  const updateOrder = async (orderId: string, data: any) => {
    setUpdatingId(orderId);
    try {
      await updateDoc(doc(db, 'orders', orderId), data);
      notify("Order updated", "success");
    } catch (e) {
      notify("Update failed", "error");
    } finally { setUpdatingId(null); }
  };

  return (
    <div className="max-w-[1440px] mx-auto px-6 py-10 pb-32 min-h-screen bg-[#FDFDFD]">
      <div className="mb-12 flex items-center space-x-6">
        <button onClick={() => navigate('/admin')} className="p-4 bg-zinc-900 text-white rounded-2xl shadow-xl"><i className="fas fa-chevron-left text-xs"></i></button>
        <div><h1 className="text-3xl font-black tracking-tighter">Manage Orders.</h1></div>
      </div>

      <div className="space-y-6">
        {orders.map(order => (
          <div key={order.id} className="bg-white rounded-[3rem] border border-zinc-100 p-8 md:p-12 shadow-sm flex flex-col lg:flex-row gap-12 transition-all hover:shadow-xl">
             <div className="lg:w-1/3">
                <div className="flex justify-between items-start mb-6">
                   <div><p className="text-[10px] font-bold text-zinc-300 uppercase tracking-widest">Reference</p><p className="font-mono font-black text-sm">#{order.id.slice(0,10).toUpperCase()}</p></div>
                   <span className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest ${order.status === OrderStatus.DELIVERED ? 'bg-green-50 text-green-600' : 'bg-zinc-100 text-zinc-500'}`}>{order.status}</span>
                </div>
                <div className="space-y-2 mb-8">
                   <p className="text-sm font-bold">{order.customerName}</p>
                   <p className="text-xs font-medium text-zinc-400">{order.contactNumber}</p>
                   <p className="text-[11px] text-zinc-400 leading-relaxed italic">{order.shippingAddress}</p>
                </div>
                <select 
                  className="w-full p-4 bg-zinc-50 rounded-2xl text-[10px] font-black uppercase tracking-widest border-none outline-none cursor-pointer"
                  value={order.status}
                  onChange={(e) => updateOrder(order.id, { status: e.target.value as OrderStatus })}
                >
                  {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
                </select>
             </div>

             <div className="flex-1 space-y-8">
                <div className="flex flex-col md:flex-row gap-8">
                   <div className="flex-1">
                      <p className="text-[10px] font-bold text-zinc-300 uppercase tracking-widest mb-4">Tracking ID</p>
                      <input 
                        type="text" 
                        placeholder="Assign Custom ID..."
                        className="w-full bg-zinc-50 p-5 rounded-2xl text-xs font-bold outline-none border border-transparent focus:border-black transition-all"
                        defaultValue={order.trackingId}
                        onBlur={(e) => updateOrder(order.id, { trackingId: e.target.value })}
                      />
                   </div>
                   <div className="text-right">
                      <p className="text-[10px] font-bold text-zinc-300 uppercase tracking-widest mb-2">Grand Total</p>
                      <p className="text-3xl font-black">৳{order.total}</p>
                   </div>
                </div>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 pt-8 border-t border-zinc-100">
                   {order.items.map((item, i) => (
                      <div key={i} className="flex flex-col items-center p-4 bg-zinc-50 rounded-2xl">
                         <img src={item.image} className="w-12 h-12 object-contain mb-3" alt="" />
                         <p className="text-[9px] font-bold text-center truncate w-full">{item.name}</p>
                      </div>
                   ))}
                </div>
             </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ManageOrders;

