import React, { useState, useRef, useEffect } from 'react';
import { UserProfile } from '../types';
import { useNavigate, Link } from 'react-router-dom';
import { auth, db } from '../firebase';
import { signOut, updateProfile } from 'firebase/auth';
import { doc, updateDoc } from 'firebase/firestore';
import { useNotify } from '../components/Notifications';
import { uploadToImgbb } from '../services/imgbb';

const Profile: React.FC<{ userData: UserProfile | null }> = ({ userData: initialUserData }) => {
  const navigate = useNavigate();
  const notify = useNotify();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [updating, setUpdating] = useState(false);
  const [localUserData, setLocalUserData] = useState<UserProfile | null>(initialUserData);

  useEffect(() => { setLocalUserData(initialUserData); }, [initialUserData]);

  const handleLogout = async () => {
    await signOut(auth);
    localStorage.removeItem('f_cart');
    navigate('/auth-selector');
  };

  const menuItems = [
    { label: 'My Orders', icon: 'fas fa-shopping-bag', path: '/orders' },
    { label: 'My Wishlist', icon: 'fas fa-heart', path: '/wishlist' },
    { label: 'Account Settings', icon: 'fas fa-cog', path: '/settings' },
    { label: 'Help Center', icon: 'fas fa-headset', path: '/help-center' }
  ];

  const isAdmin = localUserData?.role === 'admin' || localUserData?.email === 'admin@vibe.shop';

  return (
    <div className="p-6 pb-48 animate-fade-in bg-white max-w-5xl mx-auto min-h-screen md:flex md:items-center md:justify-center">
       {localUserData ? (
          <div className="w-full max-w-md">
            <div className="flex flex-col items-center mb-16">
              <div className="relative mb-8">
                <div className="w-32 h-32 rounded-[48px] bg-zinc-50 border-4 border-white shadow-2xl overflow-hidden ring-1 ring-black/5">
                   <img src={localUserData?.photoURL || `https://ui-avatars.com/api/?name=${localUserData.displayName}`} className="w-full h-full object-cover" alt="" />
                </div>
                <button onClick={() => fileInputRef.current?.click()} disabled={updating} className="absolute -bottom-2 -right-2 w-12 h-12 bg-black rounded-3xl flex items-center justify-center border-4 border-white shadow-xl active:scale-90 transition-all"><i className="fas fa-camera text-white text-sm"></i></button>
                <input type="file" hidden ref={fileInputRef} accept="image/*" onChange={async (e) => {
                    const file = e.target.files?.[0]; if (!file || !auth.currentUser) return;
                    setUpdating(true);
                    try {
                        const url = await uploadToImgbb(file);
                        await updateProfile(auth.currentUser, { photoURL: url });
                        await updateDoc(doc(db, 'users', auth.currentUser.uid), { photoURL: url });
                        setLocalUserData(prev => prev ? { ...prev, photoURL: url } : null);
                        notify("Profile Picture Updated", "success");
                    } catch(e) { notify("Upload failed", "error"); } finally { setUpdating(false); }
                }} />
              </div>

              <div className="text-center">
                 <h2 className="text-3xl font-bold tracking-tighter mb-1">{localUserData?.displayName}</h2>
                 <p className="text-[10px] font-bold text-zinc-400 uppercase tracking-[0.3em] opacity-40">{localUserData?.email}</p>
              </div>
           </div>

           <div className="space-y-4">
              {isAdmin && (
                <Link to="/admin" className="flex justify-between items-center p-6 bg-black text-white rounded-[40px] shadow-2xl shadow-black/20 hover:scale-[1.02] active:scale-95 transition-all">
                   <div className="flex items-center space-x-5"><div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center"><i className="fas fa-user-shield"></i></div><span className="font-bold text-sm uppercase tracking-widest">Admin Dashboard</span></div>
                   <i className="fas fa-chevron-right text-xs opacity-40"></i>
                </Link>
              )}
              {menuItems.map((item, idx) => (
                <Link key={idx} to={item.path} className="flex justify-between items-center p-6 bg-zinc-50 border border-zinc-100 rounded-[40px] hover:bg-white transition-all active:scale-[0.98] shadow-sm">
                   <div className="flex items-center space-x-5"><div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center shadow-sm"><i className={`${item.icon} text-sm`}></i></div><span className="font-bold text-sm tracking-tight">{item.label}</span></div>
                   <i className="fas fa-chevron-right text-xs text-gray-200"></i>
                </Link>
              ))}
              <button onClick={handleLogout} className="w-full flex justify-between items-center p-6 text-red-500 bg-red-50/10 border border-red-100 rounded-[40px] active:scale-[0.98] transition-all"><div className="flex items-center space-x-5"><div className="w-12 h-12 bg-red-100 rounded-2xl flex items-center justify-center"><i className="fas fa-sign-out-alt"></i></div><span className="font-bold text-sm uppercase tracking-widest">Log Out</span></div></button>
           </div>
          </div>
       ) : (
          <div className="flex flex-col items-center justify-center text-center max-w-sm"><div className="w-24 h-24 bg-zinc-50 rounded-[40px] flex items-center justify-center mb-10"><i className="fas fa-fingerprint text-4xl text-gray-300"></i></div><h2 className="text-3xl font-bold mb-3 tracking-tighter">Login Required</h2><p className="text-xs text-zinc-400 mb-12 px-10 leading-relaxed">Sign in to VibeGadget to view your orders and profile.</p><button onClick={() => navigate('/auth-selector')} className="btn-primary w-full shadow-2xl">Sign In Now</button></div>
       )}
    </div>
  );
};

export default Profile;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { auth, db } from '../firebase';
import { collection, addDoc, doc, getDoc } from 'firebase/firestore';
import { useNotify } from '../components/Notifications';
import { OrderStatus, UserProfile } from '../types';
import { sendOrderToTelegram } from '../services/telegram';
import { motion } from 'framer-motion';

const CheckoutPage: React.FC = () => {
  const [items, setItems] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [shipping, setShipping] = useState({
    name: '',
    address: localStorage.getItem('vibe_shipping_address') || '',
    phone: '',
    payment: 'Cash on Delivery',
    trxId: ''
  });

  const navigate = useNavigate();
  const notify = useNotify();

  useEffect(() => {
    const cart = JSON.parse(localStorage.getItem('f_cart') || '[]');
    if (cart.length === 0) { navigate('/'); return; }
    setItems(cart);
    if (auth.currentUser) {
      getDoc(doc(db, 'users', auth.currentUser.uid)).then(snap => {
        if (snap.exists()) {
          const data = snap.data() as UserProfile;
          setShipping(prev => ({ ...prev, name: data.displayName || '', phone: data.phoneNumber || '' }));
        }
      });
    }
  }, []);

  const BKASH_NUMBER = "01747708843";

  const copyNumber = () => {
    navigator.clipboard.writeText(BKASH_NUMBER);
    notify("bKash number copied!", "success");
  };

  const placeOrder = async () => {
    if (!shipping.name || !shipping.address || !shipping.phone) return notify("Please fill all details", "error");
    if (shipping.payment === 'bKash' && !shipping.trxId) return notify("Transaction ID required", "error");

    setLoading(true);
    try {
      const orderData = {
        userId: auth.currentUser?.uid || 'guest',
        customerName: shipping.name,
        items: items.map(i => ({ productId: i.id, quantity: i.quantity, priceAtPurchase: i.price, name: i.name, image: i.image })),
        total: items.reduce((a,c)=>a+(c.price*c.quantity), 0) + 150,
        status: OrderStatus.PROCESSING,
        paymentMethod: shipping.payment,
        transactionId: shipping.trxId,
        shippingAddress: shipping.address,
        contactNumber: shipping.phone,
        createdAt: Date.now()
      };

      const docRef = await addDoc(collection(db, 'orders'), orderData);
      await sendOrderToTelegram({ ...orderData, id: docRef.id });
      localStorage.removeItem('f_cart');
      notify("Order Placed Successfully!", "success");
      navigate(`/success?orderId=${docRef.id}`);
    } catch (err) { notify("Order failed", "error"); } finally { setLoading(false); }
  };

  return (
    <div className="max-w-7xl mx-auto px-6 py-10 pb-40 bg-white min-h-screen">
      <div className="flex items-center space-x-6 mb-12">
          <button onClick={() => navigate(-1)} className="p-3.5 bg-zinc-50 rounded-2xl border border-zinc-100 shadow-sm hover:bg-black hover:text-white transition-all">
             <i className="fas fa-chevron-left text-xs"></i>
          </button>
          <h1 className="text-3xl font-black tracking-tighter">Checkout.</h1>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
        <div className="lg:col-span-7 space-y-12">
          <section className="bg-zinc-50 p-8 md:p-12 rounded-[3rem] border border-zinc-100 shadow-sm">
            <h2 className="text-[10px] font-black uppercase tracking-widest text-zinc-900 mb-10">Shipping Information</h2>
            <div className="space-y-8">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <Input label="Recipient Name" placeholder="e.g. John Doe" value={shipping.name} onChange={v => setShipping({...shipping, name: v})} />
                  <Input label="Contact Number" placeholder="01XXXXXXXXX" value={shipping.phone} onChange={v => setShipping({...shipping, phone: v})} />
               </div>
               <div>
                  <label className="text-[10px] font-black text-zinc-400 uppercase mb-3 block px-1 tracking-widest">Full Delivery Address</label>
                  <textarea 
                    placeholder="Enter house, road, area, and city details..."
                    className="w-full bg-white px-6 py-5 rounded-[2rem] text-sm font-bold h-32 outline-none shadow-sm focus:ring-1 focus:ring-black border border-transparent transition-all" 
                    value={shipping.address} 
                    onChange={e => setShipping({...shipping, address: e.target.value})} 
                  />
               </div>
            </div>
          </section>

          <section className="bg-zinc-50 p-8 md:p-12 rounded-[3rem] border border-zinc-100 shadow-sm">
            <h2 className="text-[10px] font-black uppercase tracking-widest text-zinc-900 mb-10">Payment Method</h2>
            <div className="flex bg-zinc-200/40 p-1.5 rounded-[2rem] mb-10 max-w-xs border border-white/20">
              {['Cash on Delivery', 'bKash'].map(m => (
                <button key={m} onClick={() => setShipping({...shipping, payment: m})} className={`flex-1 py-4 rounded-[1.8rem] text-[10px] font-black uppercase tracking-widest transition-all ${shipping.payment === m ? 'bg-black text-white shadow-xl' : 'text-zinc-500'}`}>
                  {m === 'bKash' ? 'bKash' : 'COD'}
                </button>
              ))}
            </div>

            {shipping.payment === 'bKash' && (
              <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="space-y-8 bg-white p-8 rounded-[2.5rem] shadow-sm border border-zinc-100">
                 <div className="flex justify-between items-center bg-zinc-50 p-6 rounded-[2rem] border border-zinc-100">
                    <div>
                      <p className="text-[10px] font-black text-zinc-400 uppercase mb-1 tracking-widest">Payment Number (Personal)</p>
                      <p className="font-black text-xl tracking-widest">{BKASH_NUMBER}</p>
                    </div>
                    <button onClick={copyNumber} className="w-12 h-12 bg-black text-white rounded-[1.5rem] active:scale-90 transition-all shadow-xl flex items-center justify-center">
                      <i className="fas fa-copy text-xs"></i>
                    </button>
