                 <p className="text-zinc-400 text-sm font-medium mb-6">{localUserData?.email}</p>
                 <div className="flex items-center justify-center md:justify-start space-x-3">
                    <span className="px-4 py-1.5 bg-zinc-900 text-white rounded-full text-[10px] font-bold uppercase tracking-widest">{localUserData?.role}</span>
                    <span className="px-4 py-1.5 bg-zinc-50 text-zinc-400 rounded-full text-[10px] font-bold uppercase tracking-widest border border-zinc-100">Verified Account</span>
