                        <span className="block text-[10px] text-white/40 font-bold uppercase">Store Management Access</span>
                      </div>
                   </div>
                   <i className="fas fa-chevron-right text-xs opacity-30 group-hover:translate-x-2 transition-transform"></i>
                </Link>
              )}
              {menuItems.map((item, idx) => (
                <Link key={idx} to={item.path} className="flex justify-between items-center p-8 bg-white border border-zinc-100 rounded-[2.5rem] hover:bg-zinc-50 transition-all group">
                   <div className="flex items-center space-x-6">
                      <div className="w-14 h-14 bg-zinc-50 rounded-2xl flex items-center justify-center group-hover:bg-white transition-all shadow-inner">
