             <Step label="Order Placed" sub="We have received your order." active />
             <Step label="Quality Check" sub="Ensuring your items are perfect." active={order.status !== OrderStatus.PENDING && order.status !== OrderStatus.CANCELLED} />
             <Step label="Packed" sub="Items are ready for shipping." active={[OrderStatus.PACKAGING, OrderStatus.SHIPPED, OrderStatus.ON_THE_WAY, OrderStatus.DELIVERED].includes(order.status)} />
             <Step label="In Transit" sub="Handed over to the courier." active={[OrderStatus.SHIPPED, OrderStatus.ON_THE_WAY, OrderStatus.DELIVERED].includes(order.status)} />
             <Step label="Delivered" sub="Order successfully completed." active={order.status === OrderStatus.DELIVERED} />
