      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-6 gap-6 md:gap-10">
        {products.filter(p => activeCategory === 'All' || p.category === activeCategory).map((product) => (
          <Link to={`/product/${product.id}`} key={product.id} className="block group">
            <div className="bg-zinc-50 rounded-[2.5rem] mb-5 overflow-hidden relative aspect-[1/1.2] flex items-center justify-center border border-zinc-100 group-hover:shadow-xl transition-all duration-500 shadow-sm">
