import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { auth, db } from '../firebase';
import { collection, addDoc, doc, getDoc } from 'firebase/firestore';
import { useNotify } from '../components/Notifications';
import { OrderStatus, UserProfile } from '../types';
import { sendOrderToTelegram } from '../services/telegram';
import { motion } from 'framer-motion';

const CheckoutPage: React.FC = () => {
  const [items, setItems] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [shipping, setShipping] = useState({
    name: '',
    address: localStorage.getItem('vibe_shipping_address') || '',
    phone: '',
    payment: 'Cash on Delivery',
    trxId: ''
  });

  const navigate = useNavigate();
  const notify = useNotify();

  useEffect(() => {
    const cart = JSON.parse(localStorage.getItem('f_cart') || '[]');
    if (cart.length === 0) { navigate('/'); return; }
    setItems(cart);
    if (auth.currentUser) {
      getDoc(doc(db, 'users', auth.currentUser.uid)).then(snap => {
        if (snap.exists()) {
          const data = snap.data() as UserProfile;
          setShipping(prev => ({ ...prev, name: data.displayName || '', phone: data.phoneNumber || '' }));
        }
      });
    }
  }, []);

  const BKASH_NUMBER = "01747708843";

  const copyNumber = () => {
    navigator.clipboard.writeText(BKASH_NUMBER);
    notify("bKash number copied!", "success");
  };

  const placeOrder = async () => {
    if (!shipping.name || !shipping.address || !shipping.phone) return notify("Please complete all shipping details.", "error");
    if (shipping.payment === 'bKash' && !shipping.trxId) return notify("Transaction ID is required for bKash.", "error");

    setLoading(true);
    try {
      const orderData = {
        userId: auth.currentUser?.uid || 'guest',
        customerName: shipping.name,
        items: items.map(i => ({ productId: i.id, quantity: i.quantity, priceAtPurchase: i.price, name: i.name, image: i.image })),
        total: items.reduce((a,c)=>a+(c.price*c.quantity), 0) + 150,
        status: OrderStatus.PROCESSING,
        paymentMethod: shipping.payment,
        transactionId: shipping.trxId,
        shippingAddress: shipping.address,
        contactNumber: shipping.phone,
        createdAt: Date.now()
      };

      const docRef = await addDoc(collection(db, 'orders'), orderData);
      await sendOrderToTelegram({ ...orderData, id: docRef.id });
      localStorage.removeItem('f_cart');
      notify("Order Placed Successfully!", "success");
      navigate(`/success?orderId=${docRef.id}`);
    } catch (err) { notify("Order failed to process.", "error"); } finally { setLoading(false); }
  };

  return (
    <div className="max-w-7xl mx-auto px-6 py-10 pb-40 bg-white min-h-screen">
      <div className="flex items-center space-x-6 mb-12">
          <button onClick={() => navigate(-1)} className="p-3.5 bg-zinc-50 rounded-2xl border border-zinc-100 shadow-sm hover:bg-black hover:text-white transition-all">
             <i className="fas fa-chevron-left text-xs"></i>
          </button>
          <h1 className="text-3xl font-black tracking-tighter uppercase">Checkout.</h1>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
        <div className="lg:col-span-7 space-y-12">
          <section className="bg-zinc-50 p-8 md:p-12 rounded-[3rem] border border-zinc-100 shadow-sm">
            <h2 className="text-[10px] font-bold uppercase tracking-widest text-zinc-900 mb-10">Shipping Details</h2>
            <div className="space-y-8">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <Input label="Full Name" placeholder="e.g. John Doe" value={shipping.name} onChange={v => setShipping({...shipping, name: v})} />
                  <Input label="Phone Number" placeholder="01XXXXXXXXX" value={shipping.phone} onChange={v => setShipping({...shipping, phone: v})} />
               </div>
               <div>
                  <label className="text-[10px] font-bold text-zinc-400 uppercase mb-3 block px-1 tracking-widest">Delivery Address</label>
                  <textarea 
                    placeholder="House, Road, Area, and City..."
                    className="w-full bg-white px-6 py-5 rounded-[2rem] text-sm font-bold h-32 outline-none shadow-sm focus:ring-1 focus:ring-black border border-transparent transition-all" 
                    value={shipping.address} 
                    onChange={e => setShipping({...shipping, address: e.target.value})} 
                  />
               </div>
            </div>
          </section>

          <section className="bg-zinc-50 p-8 md:p-12 rounded-[3rem] border border-zinc-100 shadow-sm">
            <h2 className="text-[10px] font-bold uppercase tracking-widest text-zinc-900 mb-10">Payment Method</h2>
            <div className="flex bg-zinc-200/40 p-1.5 rounded-[2rem] mb-10 max-w-xs border border-white/20">
              {['Cash on Delivery', 'bKash'].map(m => (
                <button key={m} onClick={() => setShipping({...shipping, payment: m})} className={`flex-1 py-4 rounded-[1.8rem] text-[10px] font-bold uppercase tracking-widest transition-all ${shipping.payment === m ? 'bg-black text-white shadow-xl' : 'text-zinc-500'}`}>
                  {m === 'bKash' ? 'bKash' : 'Cash'}
                </button>
              ))}
            </div>

            {shipping.payment === 'bKash' && (
              <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="space-y-8 bg-white p-8 rounded-[2.5rem] shadow-sm border border-zinc-100">
                 <div className="flex justify-between items-center bg-zinc-50 p-6 rounded-[2rem] border border-zinc-100">
                    <div>
                      <p className="text-[10px] font-bold text-zinc-400 uppercase mb-1 tracking-widest">Send Money to (Personal)</p>
                      <p className="font-black text-xl tracking-widest">{BKASH_NUMBER}</p>
                    </div>
                    <button onClick={copyNumber} className="w-12 h-12 bg-black text-white rounded-[1.5rem] active:scale-90 transition-all shadow-xl flex items-center justify-center">
                      <i className="fas fa-copy text-xs"></i>
                    </button>
                 </div>
                 <div className="p-5 bg-yellow-50 rounded-2xl border border-yellow-100">
                    <p className="text-[10px] text-yellow-700 font-bold leading-relaxed">Please "Send Money" to the number above and enter your TrxID below.</p>
                 </div>
                 <Input label="Transaction ID (TrxID)" value={shipping.trxId} onChange={v => setShipping({...shipping, trxId: v.toUpperCase()})} placeholder="Enter Transaction ID" />
              </motion.div>
            )}
          </section>
        </div>

        <div className="lg:col-span-5">
           <div className="bg-zinc-900 text-white p-10 md:p-12 rounded-[4rem] shadow-2xl sticky top-12 border border-white/5">
              <h3 className="text-[10px] font-bold uppercase tracking-widest text-white/30 mb-10">Order Summary</h3>
              <div className="space-y-5">
                <div className="flex justify-between text-xs font-bold text-white/50 tracking-widest uppercase">
                  <span>Subtotal</span>
                  <span>৳{items.reduce((a,c)=>a+(c.price*c.quantity),0)}</span>
                </div>
                <div className="flex justify-between text-xs font-bold text-white/50 tracking-widest uppercase">
                  <span>Delivery</span>
                  <span>৳150</span>
                </div>
                <div className="h-px bg-white/10 my-4"></div>
                <div className="flex justify-between font-black text-4xl tracking-tighter pt-4">
                  <span>Total</span>
                  <span>৳{items.reduce((a,c)=>a+(c.price*c.quantity),0)+150}</span>
                </div>
              </div>
              <button disabled={loading} onClick={placeOrder} className="w-full mt-12 py-6 bg-white text-black rounded-[2rem] font-bold text-[11px] uppercase tracking-[0.2em] shadow-xl hover:scale-[1.02] active:scale-95 transition-all">
                {loading ? "Placing Order..." : "Place Order"}
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

const Input = ({ label, value, onChange, placeholder }: any) => (
  <div className="w-full">
    <label className="text-[10px] font-bold text-zinc-400 uppercase mb-3 block px-1 tracking-widest">{label}</label>
    <input type="text" placeholder={placeholder} className="w-full bg-white px-6 py-5 rounded-[1.8rem] text-sm font-bold outline-none shadow-sm focus:ring-1 focus:ring-black border border-transparent transition-all" value={value} onChange={e => onChange(e.target.value)} />
  </div>
);

export default CheckoutPage;

import React, { useState, useEffect, useRef } from 'react';
import { collection, onSnapshot, query, orderBy } from 'firebase/firestore';
import { db } from '../firebase';
import { Product } from '../types';
import { Link, useNavigate } from 'react-router-dom';
import { getReadableAddress } from '../services/location';
import { motion, AnimatePresence, useScroll, useTransform, useSpring } from 'framer-motion';

const Home: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [banners, setBanners] = useState<any[]>([]);
  const [activeBanner, setActiveBanner] = useState(0);
  const [activeCategory, setActiveCategory] = useState('All');
  const [locationName, setLocationName] = useState('Fetching location...');
  const navigate = useNavigate();

  // Parallax Ref and Logic
  const bannerContainerRef = useRef<HTMLDivElement>(null);
  const { scrollYProgress } = useScroll({
    target: bannerContainerRef,
    offset: ["start end", "end start"]
  });

  // Map scroll progress to a vertical offset for the banner image
  const parallaxY = useTransform(scrollYProgress, [0, 1], ["-10%", "10%"]);
  const smoothY = useSpring(parallaxY, { stiffness: 100, damping: 30, restDelta: 0.001 });

  useEffect(() => {
    const qProds = query(collection(db, 'products'));
    const unsubscribeProds = onSnapshot(qProds, (snapshot) => {
      setProducts(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Product)));
    });

    const qBanners = query(collection(db, 'banners'), orderBy('createdAt', 'desc'));
    const unsubscribeBanners = onSnapshot(qBanners, (snapshot) => {
      setBanners(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    });

    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(async (position) => {
        const address = await getReadableAddress(position.coords.latitude, position.coords.longitude);
        setLocationName(address);
      }, () => setLocationName('Dhaka, Bangladesh'));
    }
    return () => { unsubscribeProds(); unsubscribeBanners(); };
  }, []);

  useEffect(() => {
    if (banners.length > 1) {
      const interval = setInterval(() => setActiveBanner(prev => (prev + 1) % banners.length), 6000);
      return () => clearInterval(interval);
    }
  }, [banners]);

  const categories = [
    { name: 'Mobile', icon: 'fas fa-mobile-alt' },
    { name: 'Accessories', icon: 'fas fa-headphones' },
    { name: 'Gadgets', icon: 'fas fa-plug' },
    { name: 'Chargers', icon: 'fas fa-bolt' }
  ];

  return (
    <div className="px-6 md:px-12 py-10 pb-48 bg-white max-w-[1440px] mx-auto min-h-screen">
      <motion.div initial={{ y: -10, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className="flex justify-between items-center mb-10 md:mb-16">
        <div className="flex flex-col">
          <p className="text-[10px] text-zinc-400 font-bold uppercase tracking-[0.2em] mb-1">Shipping to</p>
          <button className="flex items-center font-black text-xs md:text-sm tracking-tight">
            <i className="fas fa-map-marker-alt text-black mr-2 text-[10px]"></i>
            {locationName}
          </button>
        </div>
        <button onClick={() => navigate('/notifications')} className="p-3.5 bg-zinc-50 rounded-2xl relative border border-zinc-100 shadow-sm active:scale-90 transition-transform">
          <i className="fas fa-bell text-sm"></i>
          <span className="absolute top-3 right-3 w-2 h-2 bg-red-500 rounded-full border-2 border-white"></span>
        </button>
      </motion.div>

      <div className="mb-12 md:mb-20">
        <h1 className="text-4xl md:text-7xl font-black tracking-tighter text-zinc-900 leading-tight">Latest Gear.</h1>
        <motion.div onClick={() => navigate('/search')} className="relative cursor-pointer w-full max-w-md mt-8 group">
          <div className="w-full bg-zinc-50 py-5 pl-14 pr-10 rounded-[2rem] text-[11px] font-bold uppercase tracking-widest text-zinc-400 border border-zinc-100 group-hover:bg-zinc-100 transition-all shadow-sm">Search products...</div>
          <i className="fas fa-search absolute left-6 top-1/2 -translate-y-1/2 text-zinc-300"></i>
        </motion.div>
      </div>

      {banners.length > 0 && (
        <motion.div 
          ref={bannerContainerRef}
          className="relative mb-20 overflow-hidden rounded-[3.5rem] shadow-2xl shadow-zinc-100"
        >
          <div className="flex transition-transform duration-1000 ease-[cubic-bezier(0.23, 1, 0.32, 1)]" style={{ transform: `translateX(-${activeBanner * 100}%)` }}>
            {banners.map((banner, i) => (
              <div key={i} className="min-w-full bg-zinc-100 aspect-[16/9] md:aspect-[21/9] lg:aspect-[3/1] relative overflow-hidden">
                 <motion.img 
                  src={banner.imageUrl} 
                  style={{ y: smoothY, scale: 1.2 }}
                  className="absolute inset-0 w-full h-full object-cover origin-center" 
                  alt="" 
                 />
                 <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent"></div>
                 <div className="absolute bottom-8 left-8 md:bottom-16 md:left-16 text-white max-w-lg">
                    <h2 className="text-2xl md:text-5xl font-black tracking-tighter mb-2 uppercase">{banner.title}</h2>
                    <p className="text-[10px] md:text-xs font-bold uppercase tracking-[0.3em] opacity-80 mb-8">{banner.description}</p>
                    <button onClick={() => banner.link && navigate(banner.link)} className="px-10 py-3.5 bg-white text-black rounded-full font-bold text-[10px] uppercase tracking-widest shadow-xl hover:scale-105 transition-transform">View Collection</button>
                 </div>
              </div>
            ))}
          </div>
          {banners.length > 1 && (
            <div className="absolute bottom-6 right-8 flex space-x-2">
               {banners.map((_, i) => (
                 <div key={i} className={`h-1.5 rounded-full transition-all duration-500 ${i === activeBanner ? 'w-8 bg-white' : 'w-2 bg-white/30'}`}></div>
               ))}
            </div>
          )}
        </motion.div>
      )}

      <div className="flex justify-start mb-20 overflow-x-auto no-scrollbar gap-8 md:gap-12 pb-4 px-2">
        {categories.map(cat => (
          <motion.button whileHover={{ y: -5 }} key={cat.name} onClick={() => navigate('/all-products', { state: { category: cat.name } })} className="flex flex-col items-center shrink-0 group">
            <div className="w-16 h-16 md:w-24 md:h-24 bg-zinc-50 rounded-[2.2rem] flex items-center justify-center mb-4 group-hover:bg-zinc-900 group-hover:text-white transition-all shadow-sm border border-zinc-100">
              <i className={`${cat.icon} text-lg md:text-2xl`}></i>
