            <span className="text-[9px] font-bold text-zinc-400 uppercase tracking-[0.2em] group-hover:text-zinc-900 transition-colors">{cat.name}</span>
          </motion.button>
        ))}
      </div>

      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-6 gap-6 md:gap-10">
        {products.filter(p => activeCategory === 'All' || p.category === activeCategory).map((product) => (
          <Link to={`/product/${product.id}`} key={product.id} className="block group">
            <div className="bg-zinc-50 rounded-[2.5rem] mb-5 overflow-hidden relative aspect-[1/1.2] flex items-center justify-center border border-zinc-100 group-hover:shadow-xl transition-all duration-500 shadow-sm">
              <img src={product.image} className="w-full h-full object-contain p-6 md:p-8 group-hover:scale-105 transition-transform duration-700 rounded-[15px]" alt={product.name} />
              <div className="absolute top-4 right-4"><div className="bg-white/90 backdrop-blur px-3 py-2 rounded-2xl text-[10px] font-black shadow-sm border border-black/5">৳{product.price}</div></div>
