import React, { useState, useEffect, useRef } from 'react';
import { collection, onSnapshot, query, orderBy } from 'firebase/firestore';
import { db } from '../firebase';
import { Product } from '../types';
import { Link, useNavigate } from 'react-router-dom';
import { getReadableAddress } from '../services/location';
import { motion, AnimatePresence, useScroll, useTransform, useSpring } from 'framer-motion';

const Home: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [banners, setBanners] = useState<any[]>([]);
  const [activeBanner, setActiveBanner] = useState(0);
  const [activeCategory, setActiveCategory] = useState('All');
  const [locationName, setLocationName] = useState('Fetching location...');
  const [featuredIndex, setFeaturedIndex] = useState(0);
  const navigate = useNavigate();

  // Parallax Ref and Logic
  const bannerContainerRef = useRef<HTMLDivElement>(null);
  const { scrollYProgress } = useScroll({
    target: bannerContainerRef,
    offset: ["start end", "end start"]
  });

  const parallaxY = useTransform(scrollYProgress, [0, 1], ["-10%", "10%"]);
  const smoothY = useSpring(parallaxY, { stiffness: 100, damping: 30, restDelta: 0.001 });

  useEffect(() => {
    const qProds = query(collection(db, 'products'));
    const unsubscribeProds = onSnapshot(qProds, (snapshot) => {
      setProducts(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Product)));
    });

    const qBanners = query(collection(db, 'banners'), orderBy('createdAt', 'desc'));
    const unsubscribeBanners = onSnapshot(qBanners, (snapshot) => {
      setBanners(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    });

    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(async (position) => {
        const address = await getReadableAddress(position.coords.latitude, position.coords.longitude);
        setLocationName(address);
      }, () => setLocationName('Dhaka, Bangladesh'));
    }
    return () => { unsubscribeProds(); unsubscribeBanners(); };
  }, []);

  useEffect(() => {
    if (banners.length > 1) {
      const interval = setInterval(() => setActiveBanner(prev => (prev + 1) % banners.length), 6000);
      return () => clearInterval(interval);
    }
  }, [banners]);

  const categories = [
    { name: 'Mobile', icon: 'fas fa-mobile-alt' },
    { name: 'Accessories', icon: 'fas fa-headphones' },
    { name: 'Gadgets', icon: 'fas fa-plug' },
    { name: 'Chargers', icon: 'fas fa-bolt' }
  ];

  const featuredProducts = products.filter(p => p.featured);

  const nextFeatured = () => {
    if (featuredProducts.length === 0) return;
    setFeaturedIndex((prev) => (prev + 1) % featuredProducts.length);
  };

  const prevFeatured = () => {
    if (featuredProducts.length === 0) return;
    setFeaturedIndex((prev) => (prev - 1 + featuredProducts.length) % featuredProducts.length);
  };

  return (
    <div className="px-6 md:px-12 py-10 pb-48 bg-white max-w-[1440px] mx-auto min-h-screen">
      <motion.div initial={{ y: -10, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className="flex justify-between items-center mb-10 md:mb-16">
        <div className="flex flex-col">
          <p className="text-[10px] text-zinc-400 font-bold uppercase tracking-[0.2em] mb-1">Shipping to</p>
          <button className="flex items-center font-black text-xs md:text-sm tracking-tight">
            <i className="fas fa-map-marker-alt text-black mr-2 text-[10px]"></i>
            {locationName}
          </button>
        </div>
        <button onClick={() => navigate('/notifications')} className="p-3.5 bg-zinc-50 rounded-2xl relative border border-zinc-100 shadow-sm active:scale-90 transition-transform">
          <i className="fas fa-bell text-sm"></i>
          <span className="absolute top-3 right-3 w-2 h-2 bg-red-500 rounded-full border-2 border-white"></span>
        </button>
      </motion.div>

      <div className="mb-12 md:mb-20">
        <h1 className="text-4xl md:text-7xl font-black tracking-tighter text-zinc-900 leading-tight">Latest Gear.</h1>
        <motion.div onClick={() => navigate('/search')} className="relative cursor-pointer w-full max-w-md mt-8 group">
          <div className="w-full bg-zinc-50 py-5 pl-14 pr-10 rounded-[2rem] text-[11px] font-bold uppercase tracking-widest text-zinc-400 border border-zinc-100 group-hover:bg-zinc-100 transition-all shadow-sm">Search products...</div>
          <i className="fas fa-search absolute left-6 top-1/2 -translate-y-1/2 text-zinc-300"></i>
        </motion.div>
      </div>

      {banners.length > 0 && (
        <motion.div 
          ref={bannerContainerRef}
          className="relative mb-20 overflow-hidden rounded-[3.5rem] shadow-2xl shadow-zinc-100"
        >
          <div className="flex transition-transform duration-1000 ease-[cubic-bezier(0.23, 1, 0.32, 1)]" style={{ transform: `translateX(-${activeBanner * 100}%)` }}>
            {banners.map((banner, i) => (
              <div key={i} className="min-w-full bg-zinc-100 aspect-[16/9] md:aspect-[21/9] lg:aspect-[3/1] relative overflow-hidden">
                 <motion.img 
                  src={banner.imageUrl} 
                  style={{ y: smoothY, scale: 1.2 }}
                  className="absolute inset-0 w-full h-full object-cover origin-center" 
                  alt="" 
                 />
                 <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent"></div>
                 <div className="absolute bottom-8 left-8 md:bottom-16 md:left-16 text-white max-w-lg">
                    <h2 className="text-2xl md:text-5xl font-black tracking-tighter mb-2 uppercase">{banner.title}</h2>
                    <p className="text-[10px] md:text-xs font-bold uppercase tracking-[0.3em] opacity-80 mb-8">{banner.description}</p>
                    <button onClick={() => banner.link && navigate(banner.link)} className="px-10 py-3.5 bg-white text-black rounded-full font-bold text-[10px] uppercase tracking-widest shadow-xl hover:scale-105 transition-transform">View Collection</button>
                 </div>
              </div>
            ))}
          </div>
          {banners.length > 1 && (
            <div className="absolute bottom-6 right-8 flex space-x-2">
               {banners.map((_, i) => (
                 <div key={i} className={`h-1.5 rounded-full transition-all duration-500 ${i === activeBanner ? 'w-8 bg-white' : 'w-2 bg-white/30'}`}></div>
               ))}
            </div>
          )}
        </motion.div>
      )}

      <div className="flex justify-start mb-20 overflow-x-auto no-scrollbar gap-8 md:gap-12 pb-4 px-2">
        {categories.map(cat => (
          <motion.button whileHover={{ y: -5 }} key={cat.name} onClick={() => setActiveCategory(cat.name === activeCategory ? 'All' : cat.name)} className={`flex flex-col items-center shrink-0 group ${activeCategory === cat.name ? 'scale-110' : ''}`}>
            <div className={`w-16 h-16 md:w-24 md:h-24 rounded-[2.2rem] flex items-center justify-center mb-4 transition-all shadow-sm border ${activeCategory === cat.name ? 'bg-zinc-900 text-white border-zinc-900 shadow-xl' : 'bg-zinc-50 border-zinc-100 group-hover:bg-zinc-900 group-hover:text-white'}`}>
              <i className={`${cat.icon} text-lg md:text-2xl`}></i>
            </div>
            <span className={`text-[9px] font-bold uppercase tracking-[0.2em] transition-colors ${activeCategory === cat.name ? 'text-zinc-900' : 'text-zinc-400 group-hover:text-zinc-900'}`}>{cat.name}</span>
