      {featuredProducts.length > 0 && (
        <div className="mb-24">
          <div className="flex justify-between items-end mb-10 px-2">
            <div>
              <h3 className="text-[10px] font-bold uppercase tracking-[0.3em] text-zinc-400 mb-2">Editor's Picks</h3>
              <h2 className="text-3xl md:text-5xl font-black tracking-tighter">Featured Products.</h2>
