              <motion.button 
                whileTap={{ scale: 0.9 }} 
                onClick={nextFeatured}
                className="w-12 h-12 rounded-2xl bg-white border border-zinc-100 flex items-center justify-center shadow-sm hover:bg-black hover:text-white transition-all"
              >
                <i className="fas fa-chevron-right text-xs"></i>
              </motion.button>
            </div>
          </div>

          <div className="relative overflow-hidden px-2 py-4">
            <div className="flex transition-transform duration-700 ease-[cubic-bezier(0.23, 1, 0.32, 1)]" style={{ transform: `translateX(-${featuredIndex * 100}%)` }}>
              {featuredProducts.map((p) => (
                <div key={p.id} className="min-w-full flex flex-col md:flex-row items-center md:items-start md:space-x-12 bg-zinc-50/50 p-8 md:p-12 rounded-[3.5rem] border border-zinc-100">
                  <div className="w-full md:w-1/2 aspect-square md:aspect-[4/3] relative flex items-center justify-center bg-white rounded-[2.5rem] shadow-sm mb-8 md:mb-0 border border-zinc-100/50 overflow-hidden">
                    <img src={p.image} className="w-full h-full object-contain p-8 md:p-12 rounded-[15px]" alt={p.name} />
                  </div>
                  <div className="flex-1 flex flex-col justify-center text-center md:text-left">
                    <span className="text-[10px] font-black uppercase tracking-[0.3em] text-zinc-400 mb-4">{p.category}</span>
                    <h3 className="text-3xl md:text-5xl font-black tracking-tighter mb-6 leading-none">{p.name}</h3>
                    <p className="text-sm md:text-base text-zinc-500 font-medium mb-10 leading-relaxed line-clamp-3 md:line-clamp-none">
                      {p.description || "Premium accessory built with top-tier materials for the ultimate tech enthusiast."}
                    </p>
                    <div className="flex flex-col md:flex-row items-center md:space-x-8 space-y-6 md:space-y-0">
                      <div className="text-3xl font-black">৳{p.price}</div>
                      <Link to={`/product/${p.id}`} className="px-12 py-4 bg-black text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl hover:scale-105 transition-transform">View Details</Link>
