          </div>
        </div>
      )}

      <div>
        <div className="flex justify-between items-end mb-10 px-2">
          <div>
            <h3 className="text-[10px] font-bold uppercase tracking-[0.3em] text-zinc-400 mb-2">All Items</h3>
            <h2 className="text-3xl md:text-5xl font-black tracking-tighter">Explore Collection.</h2>
          </div>
        </div>

        {/* Improved Masonry Grid with Variable Heights */}
        <div className="columns-2 md:columns-3 lg:columns-4 xl:columns-6 gap-6 md:gap-10 space-y-6 md:space-y-10">
          {products.filter(p => activeCategory === 'All' || p.category === activeCategory).map((product) => (
            <motion.div 
              layout
              key={product.id} 
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              className="break-inside-avoid"
            >
              <Link to={`/product/${product.id}`} className="block group">
                <div className="bg-zinc-50 rounded-[2.5rem] mb-5 overflow-hidden relative border border-zinc-100 group-hover:shadow-xl transition-all duration-500 shadow-sm">
                  {/* Remove fixed aspect ratio for true masonry feel */}
                  <img src={product.image} className="w-full h-auto object-contain p-6 md:p-8 group-hover:scale-105 transition-transform duration-700 rounded-[15px]" alt={product.name} />
                  <div className="absolute top-4 right-4">
                    <div className="bg-white/90 backdrop-blur px-3 py-2 rounded-2xl text-[10px] font-black shadow-sm border border-black/5">
                      ৳{product.price}
