import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { auth, db } from '../firebase';
import { collection, addDoc, doc, getDoc } from 'firebase/firestore';
import { useNotify } from '../components/Notifications';
import { OrderStatus, UserProfile } from '../types';
import { sendOrderToTelegram } from '../services/telegram';
import { motion, AnimatePresence } from 'framer-motion';

const CheckoutPage: React.FC = () => {
  const [items, setItems] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [validationError, setValidationError] = useState<string | null>(null);
  const [shipping, setShipping] = useState({
    name: '',
    address: localStorage.getItem('vibe_shipping_address') || '',
    phone: '',
    payment: 'Cash on Delivery',
    trxId: ''
  });

  const navigate = useNavigate();
  const notify = useNotify();

  useEffect(() => {
    const cart = JSON.parse(localStorage.getItem('f_cart') || '[]');
    if (cart.length === 0) { navigate('/'); return; }
    setItems(cart);
    if (auth.currentUser) {
      getDoc(doc(db, 'users', auth.currentUser.uid)).then(snap => {
        if (snap.exists()) {
          const data = snap.data() as UserProfile;
          setShipping(prev => ({ ...prev, name: data.displayName || '', phone: data.phoneNumber || '' }));
        }
      });
    }
  }, []);

  const BKASH_NUMBER = "01747708843";

  const copyNumber = () => {
    navigator.clipboard.writeText(BKASH_NUMBER);
    notify("bKash number copied!", "success");
  };

  const placeOrder = async () => {
    setValidationError(null);

    if (!shipping.name || !shipping.address || !shipping.phone) {
      return notify("Complete all shipping details.", "error");
    }

    // Strict bKash Validation
    if (shipping.payment === 'bKash') {
      if (!shipping.trxId || shipping.trxId.trim().length < 8) {
        setValidationError("trxId");
        return notify("Valid bKash TrxID required to proceed.", "error");
      }
    }

    setLoading(true);
    try {
      const orderData = {
        userId: auth.currentUser?.uid || 'guest',
        customerName: shipping.name,
        items: items.map(i => ({ productId: i.id, quantity: i.quantity, priceAtPurchase: i.price, name: i.name, image: i.image })),
        total: items.reduce((a,c)=>a+(c.price*c.quantity), 0) + 150,
        status: OrderStatus.PROCESSING,
        paymentMethod: shipping.payment,
        transactionId: shipping.trxId.trim(),
        shippingAddress: shipping.address,
        contactNumber: shipping.phone,
        createdAt: Date.now()
      };

      const docRef = await addDoc(collection(db, 'orders'), orderData);
      await sendOrderToTelegram({ ...orderData, id: docRef.id });
      localStorage.removeItem('f_cart');
      notify("Order Placed Successfully!", "success");
      navigate(`/success?orderId=${docRef.id}`);
    } catch (err) { notify("Order failed to process.", "error"); } finally { setLoading(false); }
  };

  return (
    <div className="max-w-[1440px] mx-auto px-6 py-10 pb-48 bg-white min-h-screen font-inter">
      <div className="flex items-center space-x-8 mb-16">
          <button onClick={() => navigate(-1)} className="p-4 bg-zinc-50 rounded-2xl border border-zinc-100 shadow-sm hover:bg-black hover:text-white transition-all active:scale-90">
             <i className="fas fa-chevron-left text-xs"></i>
          </button>
          <div className="flex flex-col">
            <h1 className="text-3xl md:text-5xl font-black tracking-tighter uppercase leading-none">Checkout.</h1>
            <p className="text-[10px] font-bold text-zinc-400 uppercase tracking-[0.4em] mt-1">Order Neural Bridge</p>
          </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-16">
        <div className="lg:col-span-7 space-y-16">
          <section className="bg-zinc-50 p-10 md:p-14 rounded-[3.5rem] border border-zinc-100 shadow-sm">
            <h2 className="text-[11px] font-black uppercase tracking-[0.4em] text-zinc-900 mb-12">Logistics Profile</h2>
            <div className="space-y-10">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                  <Input label="Full Name" placeholder="e.g. John Doe" value={shipping.name} onChange={v => setShipping({...shipping, name: v})} />
                  <Input label="Contact Node" placeholder="01XXXXXXXXX" value={shipping.phone} onChange={v => setShipping({...shipping, phone: v})} />
               </div>
               <div>
                  <label className="text-[10px] font-black text-zinc-300 uppercase mb-4 block px-1 tracking-widest">Global Destination</label>
                  <textarea 
                    placeholder="Provide detailed street, area, and city coordinates..."
                    className="w-full bg-white px-8 py-6 rounded-[2.2rem] text-sm font-bold h-40 outline-none shadow-inner border border-zinc-100 focus:border-black transition-all leading-relaxed" 
                    value={shipping.address} 
                    onChange={e => setShipping({...shipping, address: e.target.value})} 
                  />
               </div>
            </div>
          </section>

          <section className="bg-zinc-50 p-10 md:p-14 rounded-[3.5rem] border border-zinc-100 shadow-sm">
            <h2 className="text-[11px] font-black uppercase tracking-[0.4em] text-zinc-900 mb-12">Financial Settlement</h2>
            <div className="flex bg-zinc-200/50 p-1.5 rounded-[2.5rem] mb-12 max-w-sm border border-zinc-100">
              {['Cash on Delivery', 'bKash'].map(m => (
                <button key={m} onClick={() => setShipping({...shipping, payment: m})} className={`flex-1 py-5 rounded-[2.2rem] text-[10px] font-black uppercase tracking-widest transition-all ${shipping.payment === m ? 'bg-black text-white shadow-2xl scale-[1.02]' : 'text-zinc-400 hover:text-zinc-600'}`}>
                  {m === 'bKash' ? 'bKash Pay' : 'COD'}
                </button>
              ))}
            </div>

            <AnimatePresence mode="wait">
              {shipping.payment === 'bKash' && (
                <motion.div 
                  initial={{ opacity: 0, y: 20 }} 
                  animate={{ opacity: 1, y: 0 }} 
                  exit={{ opacity: 0, y: -20 }} 
                  className="space-y-10 bg-white p-10 rounded-[3rem] shadow-xl border border-zinc-100"
                >
                   <div className="flex justify-between items-center bg-zinc-50 p-8 rounded-[2.5rem] border border-zinc-100 group">
                      <div>
                        <p className="text-[10px] font-black text-zinc-300 uppercase mb-2 tracking-widest">Send Money (Personal)</p>
                        <p className="font-black text-2xl tracking-widest text-zinc-900">{BKASH_NUMBER}</p>
                      </div>
                      <button onClick={copyNumber} className="w-14 h-14 bg-black text-white rounded-[1.8rem] active:scale-90 transition-all shadow-2xl flex items-center justify-center group-hover:scale-110">
                        <i className="fas fa-copy text-sm"></i>
                      </button>
                   </div>
                   <div className="p-6 bg-yellow-50/50 rounded-3xl border border-yellow-100/50">
                      <p className="text-[11px] text-yellow-700 font-bold leading-relaxed flex items-start">
                        <i className="fas fa-info-circle mt-0.5 mr-3"></i>
                        Please "Send Money" the full amount + delivery charge to our bKash number and provide the Transaction ID below.
                      </p>
                   </div>
                   <div className={validationError === "trxId" ? "animate-shake" : ""}>
                     <Input 
                        label="Transaction ID (Required)" 
                        value={shipping.trxId} 
                        onChange={v => setShipping({...shipping, trxId: v.toUpperCase()})} 
                        placeholder="ENTER 8+ CHARACTER TRXID"
                        error={validationError === "trxId"}
                      />
                   </div>
                </motion.div>
              )}
            </AnimatePresence>
          </section>
        </div>

        <div className="lg:col-span-5">
           <div className="bg-zinc-900 text-white p-12 md:p-14 rounded-[4.5rem] shadow-[0_50px_100px_rgba(0,0,0,0.4)] sticky top-12 border border-white/10">
              <h3 className="text-[11px] font-black uppercase tracking-[0.5em] text-white/30 mb-12">Manifest Sync</h3>
              <div className="space-y-6">
                <div className="flex justify-between text-[11px] font-bold text-white/40 tracking-[0.2em] uppercase">
