                <div className="flex justify-between text-[11px] font-bold text-white/40 tracking-[0.2em] uppercase">
                  <span>Steadfast Delivery</span>
                  <span>৳150</span>
                </div>
                <div className="h-px bg-white/10 my-8"></div>
                <div className="flex justify-between font-black text-5xl tracking-tighter py-6">
