              <motion.button 
                whileHover={{ scale: 1.02, backgroundColor: '#fff', color: '#000' }}
                whileTap={{ scale: 0.98 }}
                disabled={loading} 
                onClick={placeOrder} 
                className="w-full mt-14 py-7 bg-white text-black rounded-[2.5rem] font-black text-[12px] uppercase tracking-[0.3em] shadow-2xl transition-all disabled:opacity-50"
              >
                {loading ? "Syncing Nodes..." : "Confirm & Commit"}
              </motion.button>
           </div>
        </div>
      </div>
    </div>
  );
};

const Input = ({ label, value, onChange, placeholder, error }: any) => (
  <div className="w-full">
    <label className={`text-[10px] font-black uppercase mb-4 block px-1 tracking-widest ${error ? 'text-red-500' : 'text-zinc-300'}`}>{label}</label>
    <input 
      type="text" 
      placeholder={placeholder} 
      className={`w-full bg-white px-8 py-6 rounded-[2rem] text-sm font-black outline-none shadow-inner border transition-all ${error ? 'border-red-500 focus:border-red-600 ring-2 ring-red-100' : 'border-zinc-100 focus:border-black'}`} 
      value={value} 
      onChange={e => onChange(e.target.value)} 
    />
  </div>
);

export default CheckoutPage;

