import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { auth, db } from '../firebase';
import { collection, addDoc, doc, getDoc } from 'firebase/firestore';
import { useNotify } from '../components/Notifications';
import { OrderStatus, UserProfile } from '../types';
import { sendOrderToTelegram } from '../services/telegram';
import { motion, AnimatePresence } from 'framer-motion';

const CheckoutPage: React.FC = () => {
  const [items, setItems] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [userIp, setUserIp] = useState<string>('');
  const [validationError, setValidationError] = useState<string | null>(null);
  const [shipping, setShipping] = useState({
    name: '',
    address: localStorage.getItem('vibe_shipping_address') || '',
    phone: '',
    payment: 'Cash on Delivery',
    paymentOption: 'Full Payment',
    trxId: ''
  });

  const navigate = useNavigate();
  const notify = useNotify();

  useEffect(() => {
    // Fetch User IP for better admin tracking
    fetch('https://api.ipify.org?format=json')
      .then(res => res.json())
      .then(data => setUserIp(data.ip))
      .catch(() => setUserIp('Unavailable'));

    const cart = JSON.parse(localStorage.getItem('f_cart') || '[]');
    if (cart.length === 0) { navigate('/'); return; }
    setItems(cart);

    if (auth.currentUser) {
      getDoc(doc(db, 'users', auth.currentUser.uid)).then(snap => {
        if (snap.exists()) {
          const data = snap.data() as UserProfile;
          setShipping(prev => ({ ...prev, name: data.displayName || '', phone: data.phoneNumber || '' }));
        }
      });
    }
  }, []);

  const BKASH_NUMBER = "01747708843";

  const copyNumber = () => {
    navigator.clipboard.writeText(BKASH_NUMBER);
    notify("bKash Number copied!", "success");
  };

  const placeOrder = async () => {
    setValidationError(null);

    if (!shipping.name || !shipping.address || !shipping.phone) {
      return notify("Please complete all shipping information.", "error");
    }

    if (shipping.payment === 'bKash') {
      if (!shipping.trxId || shipping.trxId.trim().length < 8) {
        setValidationError("trxId");
        return notify("Valid bKash Transaction ID is required.", "error");
      }
    }

    setLoading(true);
    try {
      const orderData = {
        userId: auth.currentUser?.uid || 'guest',
        customerName: shipping.name,
        items: items.map(i => ({ productId: i.id, quantity: i.quantity, priceAtPurchase: i.price, name: i.name, image: i.image })),
        total: items.reduce((a,c)=>a+(c.price*c.quantity), 0) + 150,
        status: OrderStatus.PROCESSING,
        paymentMethod: shipping.payment,
        paymentOption: shipping.payment === 'bKash' ? shipping.paymentOption : 'N/A',
        transactionId: shipping.trxId.trim(),
        shippingAddress: shipping.address,
        contactNumber: shipping.phone,
        ipAddress: userIp,
        createdAt: Date.now()
      };

      const docRef = await addDoc(collection(db, 'orders'), orderData);
      await sendOrderToTelegram({ ...orderData, id: docRef.id });
      localStorage.removeItem('f_cart');
      notify("Order Confirmed Successfully!", "success");
      navigate(`/success?orderId=${docRef.id}`);
    } catch (err) { notify("Order failed to process.", "error"); } finally { setLoading(false); }
  };

  const subTotal = items.reduce((a,c)=>a+(c.price*c.quantity), 0);
  const deliveryFee = 150;
  const totalAmount = subTotal + deliveryFee;

  return (
    <div className="max-w-[1440px] mx-auto px-6 py-10 pb-48 bg-white min-h-screen font-inter">
      <div className="flex items-center space-x-8 mb-16">
          <button onClick={() => navigate(-1)} className="p-4 bg-zinc-50 rounded-2xl border border-zinc-100 hover:bg-black hover:text-white transition-all active:scale-90">
             <i className="fas fa-chevron-left text-xs"></i>
          </button>
          <div className="flex flex-col">
            <h1 className="text-3xl md:text-5xl font-black tracking-tighter uppercase leading-none">Checkout.</h1>
            <p className="text-[10px] font-bold text-zinc-400 uppercase tracking-[0.4em] mt-1">Order Details</p>
          </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
        <div className="lg:col-span-7 space-y-10">
          {/* Shipping Information Section */}
          <section className="bg-white p-8 md:p-10 rounded-[2.5rem] border border-zinc-100">
            <h2 className="text-[11px] font-black uppercase tracking-[0.4em] text-zinc-900 mb-8">Shipping Address</h2>
            <div className="space-y-6">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <Input label="Full Name" placeholder="Your name" value={shipping.name} onChange={v => setShipping({...shipping, name: v})} />
                  <Input label="Phone Number" placeholder="01XXXXXXXXX" value={shipping.phone} onChange={v => setShipping({...shipping, phone: v})} />
               </div>
               <div>
                  <label className="text-[10px] font-black text-zinc-300 uppercase mb-3 block px-1 tracking-widest">Street Address</label>
                  <textarea 
                    placeholder="Enter full address details..."
                    className="w-full bg-zinc-50 px-6 py-5 rounded-[1.5rem] text-sm font-bold h-32 outline-none border border-transparent focus:border-black transition-all leading-relaxed" 
                    value={shipping.address} 
                    onChange={e => setShipping({...shipping, address: e.target.value})} 
                  />
               </div>
            </div>
          </section>

          {/* Payment Method Section */}
          <section className="bg-white p-8 md:p-10 rounded-[2.5rem] border border-zinc-100">
            <h2 className="text-[11px] font-black uppercase tracking-[0.4em] text-zinc-900 mb-8">Payment Method</h2>
            <div className="flex bg-zinc-100 p-1 rounded-[1.5rem] mb-8 max-w-sm">
              {['Cash on Delivery', 'bKash'].map(m => (
                <button key={m} onClick={() => setShipping({...shipping, payment: m})} className={`flex-1 py-4 rounded-[1.2rem] text-[10px] font-black uppercase tracking-widest transition-all ${shipping.payment === m ? 'bg-black text-white shadow-md' : 'text-zinc-400 hover:text-zinc-600'}`}>
                  {m === 'bKash' ? 'bKash Pay' : 'COD'}
                </button>
              ))}
            </div>

            <AnimatePresence mode="wait">
              {shipping.payment === 'bKash' && (
                <motion.div 
                  initial={{ opacity: 0, y: 10 }} 
                  animate={{ opacity: 1, y: 0 }} 
                  exit={{ opacity: 0, y: -10 }} 
                  className="space-y-8 bg-zinc-50 p-8 rounded-[2rem] border border-zinc-100"
                >
                   {/* bKash Payment Options */}
                   <div className="space-y-4">
                      <p className="text-[10px] font-black text-zinc-400 uppercase tracking-widest px-1">Choose bKash Option</p>
                      <div className="flex gap-4">
                         {['Full Payment', 'Delivery Fee Only'].map(opt => (
                           <button 
                             key={opt}
                             onClick={() => setShipping({...shipping, paymentOption: opt})}
                             className={`flex-1 py-4 rounded-xl text-[10px] font-black uppercase border transition-all ${shipping.paymentOption === opt ? 'bg-zinc-900 text-white border-black' : 'bg-white text-zinc-400 border-zinc-200 hover:border-zinc-400'}`}
                           >
                             {opt === 'Full Payment' ? `Full (৳${totalAmount})` : `Fee (৳${deliveryFee})`}
                           </button>
                         ))}
                      </div>
                   </div>

                   {/* bKash Number Display */}
                   <div className="flex justify-between items-center bg-white p-5 rounded-[1.5rem] border border-zinc-100">
                      <div>
                        <p className="text-[10px] font-black text-zinc-300 uppercase mb-1 tracking-widest">bKash Personal Number</p>
                        <p className="font-black text-xl tracking-widest text-zinc-900">{BKASH_NUMBER}</p>
                      </div>
                      <button onClick={copyNumber} className="w-12 h-12 bg-zinc-100 text-zinc-900 rounded-2xl active:scale-90 transition-all flex items-center justify-center hover:bg-black hover:text-white">
                        <i className="fas fa-copy text-sm"></i>
                      </button>
                   </div>

                   <div className="p-5 bg-blue-50/50 rounded-2xl border border-blue-100/30">
                      <p className="text-[11px] text-blue-800 font-bold leading-relaxed flex items-start">
                        <i className="fas fa-info-circle mt-0.5 mr-3"></i>
                        Please "Send Money" our bKash number and provide the Transaction ID below to verify your payment.
                      </p>
                   </div>

                   <div className={validationError === "trxId" ? "animate-shake" : ""}>
                     <Input 
                        label="Transaction ID (Required)" 
                        value={shipping.trxId} 
                        onChange={v => setShipping({...shipping, trxId: v.toUpperCase()})} 
                        placeholder="e.g. 8K67A9XYZ"
                        error={validationError === "trxId"}
                      />
                   </div>
                </motion.div>
              )}
            </AnimatePresence>
          </section>
        </div>

        {/* Order Summary Section */}
        <div className="lg:col-span-5">
           <div className="bg-zinc-900 text-white p-10 md:p-12 rounded-[3rem] sticky top-12 border border-white/5">
              <h3 className="text-[11px] font-black uppercase tracking-[0.5em] text-white/30 mb-10">Order Summary</h3>
              <div className="space-y-5">
                <div className="flex justify-between text-[11px] font-bold text-white/40 tracking-[0.2em] uppercase">
                  <span>Subtotal</span>
                  <span>৳{subTotal}</span>
                </div>
                <div className="flex justify-between text-[11px] font-bold text-white/40 tracking-[0.2em] uppercase">
                  <span>Delivery Charge</span>
                  <span>৳{deliveryFee}</span>
                </div>
                <div className="h-px bg-white/10 my-6"></div>
                <div className="flex justify-between font-black text-4xl tracking-tighter py-4">
                  <span>Total</span>
                  <span>৳{totalAmount}</span>
                </div>
              </div>
              <motion.button 
                whileHover={{ scale: 1.01, backgroundColor: '#fff', color: '#000' }}
                whileTap={{ scale: 0.99 }}
                disabled={loading} 
                onClick={placeOrder} 
                className="w-full mt-12 py-6 bg-white text-black rounded-[2rem] font-black text-[12px] uppercase tracking-[0.3em] transition-all disabled:opacity-50"
              >
                {loading ? "Processing..." : "Confirm & Order"}
              </motion.button>
              <p className="text-[8px] text-center mt-6 text-white/20 font-bold uppercase tracking-widest">Public IP: {userIp}</p>
           </div>
        </div>
      </div>
    </div>
  );
};

const Input = ({ label, value, onChange, placeholder, error }: any) => (
  <div className="w-full">
    <label className={`text-[10px] font-black uppercase mb-3 block px-1 tracking-widest ${error ? 'text-red-500' : 'text-zinc-300'}`}>{label}</label>
    <input 
      type="text" 
      placeholder={placeholder} 
      className={`w-full bg-zinc-50 px-6 py-5 rounded-[1.2rem] text-sm font-black outline-none border transition-all ${error ? 'border-red-500 ring-2 ring-red-50' : 'border-transparent focus:border-black'}`} 
      value={value} 
      onChange={e => onChange(e.target.value)} 
    />
  </div>
);

export default CheckoutPage;

