import React, { useState, useRef, useEffect } from 'react';
import { UserProfile } from '../types';
import { useNavigate, Link } from 'react-router-dom';
import { auth, db } from '../firebase';
import { signOut, updateProfile } from 'firebase/auth';
import { doc, updateDoc } from 'firebase/firestore';
import { useNotify } from '../components/Notifications';
import { uploadToImgbb } from '../services/imgbb';
import { motion } from 'framer-motion';

const Profile: React.FC<{ userData: UserProfile | null }> = ({ userData: initialUserData }) => {
  const navigate = useNavigate();
  const notify = useNotify();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [updating, setUpdating] = useState(false);
  const [localUserData, setLocalUserData] = useState<UserProfile | null>(initialUserData);

  useEffect(() => { 
    setLocalUserData(initialUserData); 
  }, [initialUserData]);

  const handleLogout = async () => {
    await signOut(auth);
    localStorage.removeItem('f_cart');
    navigate('/auth-selector');
  };

  const menuItems = [
    { label: 'Orders', icon: 'fas fa-shopping-bag', path: '/orders', desc: 'Manage your history' },
    { label: 'Favorites', icon: 'fas fa-heart', path: '/wishlist', desc: 'Saved gadgets' },
    { label: 'Settings', icon: 'fas fa-cog', path: '/settings', desc: 'Profile options' },
    { label: 'Support', icon: 'fas fa-headset', path: '/help-center', desc: 'Help desk' }
  ];

  const isAdmin = localUserData?.role === 'admin' || 
                  localUserData?.email?.toLowerCase().trim() === 'admin@vibe.shop';

  return (
    <div className="p-6 md:p-12 pb-48 bg-white max-w-4xl mx-auto min-h-screen font-inter">
       {localUserData ? (
          <div>
            <div className="flex flex-col md:flex-row items-center md:items-start md:space-x-8 mb-12">
              <div className="relative mb-6 md:mb-0">
                <motion.div 
                  initial={{ opacity: 0, scale: 0.95 }}
                  animate={{ opacity: 1, scale: 1 }}
                  className="w-28 h-28 md:w-36 md:h-36 rounded-[2.5rem] bg-zinc-50 border border-zinc-100 overflow-hidden"
                >
                   <img src={localUserData?.photoURL || `https://ui-avatars.com/api/?name=${localUserData.displayName}&background=000&color=fff`} className="w-full h-full object-cover" alt="" />
                </motion.div>
                <motion.button 
                  whileTap={{ scale: 0.9 }}
                  onClick={() => fileInputRef.current?.click()} 
                  disabled={updating} 
                  className="absolute bottom-0 right-0 w-10 h-10 bg-black text-white rounded-xl flex items-center justify-center border-4 border-white shadow-lg"
                >
                  <i className="fas fa-camera text-[10px]"></i>
                </motion.button>
                <input type="file" hidden ref={fileInputRef} accept="image/*" onChange={async (e) => {
                    const file = e.target.files?.[0]; if (!file || !auth.currentUser) return;
                    setUpdating(true);
                    try {
                        const url = await uploadToImgbb(file);
                        await updateProfile(auth.currentUser, { photoURL: url });
                        await updateDoc(doc(db, 'users', auth.currentUser.uid), { photoURL: url });
                        setLocalUserData(prev => prev ? { ...prev, photoURL: url } : null);
                        notify("Profile updated!", "success");
                    } catch(e) { notify("Update failed.", "error"); } finally { setUpdating(false); }
                }} />
              </div>

              <div className="text-center md:text-left pt-2">
                 <h2 className="text-2xl md:text-3xl font-black tracking-tight mb-1">{localUserData?.displayName}</h2>
                 <p className="text-zinc-400 text-xs font-medium mb-6">{localUserData?.email}</p>
                 <div className="flex items-center justify-center md:justify-start space-x-2">
                    <span className="px-4 py-1.5 bg-zinc-900 text-white rounded-full text-[9px] font-bold uppercase tracking-widest">{isAdmin ? 'Admin' : 'Customer'}</span>
                    <span className="px-4 py-1.5 bg-zinc-50 text-zinc-400 rounded-full text-[9px] font-bold uppercase tracking-widest border border-zinc-100">Verified</span>
                 </div>
              </div>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {isAdmin && (
                <Link to="/admin" className="col-span-1 md:col-span-2 flex justify-between items-center p-8 bg-zinc-900 text-white rounded-[2rem] hover:scale-[1.01] transition-all group">
                   <div className="flex items-center space-x-6">
                      <div className="w-12 h-12 bg-white/10 rounded-xl flex items-center justify-center"><i className="fas fa-user-shield text-lg"></i></div>
                      <div>
                        <span className="block font-bold text-sm tracking-tight">Admin Control Panel</span>
                        <span className="block text-[9px] text-white/40 font-bold uppercase mt-1">Manage Store & Orders</span>
                      </div>
                   </div>
                   <i className="fas fa-arrow-right text-[10px] opacity-30 group-hover:translate-x-2 transition-transform"></i>
                </Link>
              )}

              {menuItems.map((item, idx) => (
                <Link key={idx} to={item.path} className="flex justify-between items-center p-6 bg-white border border-zinc-100 rounded-[1.8rem] hover:bg-zinc-50 transition-all group">
                   <div className="flex items-center space-x-5">
                      <div className="w-12 h-12 bg-zinc-50 rounded-xl flex items-center justify-center border border-zinc-100/50">
                        <i className={`${item.icon} text-zinc-400 group-hover:text-black`}></i>
                      </div>
                      <div>
                        <span className="block font-bold text-sm tracking-tight">{item.label}</span>
                        <span className="block text-[9px] text-zinc-300 font-bold uppercase tracking-widest mt-0.5">{item.desc}</span>
                      </div>
                   </div>
                   <i className="fas fa-chevron-right text-[10px] text-zinc-200 group-hover:translate-x-1 transition-transform"></i>
                </Link>
              ))}

              <button onClick={handleLogout} className="col-span-1 md:col-span-2 flex justify-between items-center p-6 bg-red-50/20 border border-red-100 rounded-[1.8rem] hover:bg-red-50 transition-all group">
                <div className="flex items-center space-x-5">
                  <div className="w-12 h-12 bg-red-100 rounded-xl flex items-center justify-center"><i className="fas fa-sign-out-alt text-red-500"></i></div>
                  <span className="font-bold text-sm uppercase tracking-widest text-red-600">Logout</span>
                </div>
                <i className="fas fa-power-off text-xs text-red-200"></i>
              </button>
           </div>
          </div>
       ) : (
          <div className="flex flex-col items-center justify-center text-center py-24">
             <div className="w-20 h-20 bg-zinc-50 rounded-3xl flex items-center justify-center mb-8 border border-zinc-100">
               <i className="fas fa-user text-2xl text-zinc-200"></i>
             </div>
             <h2 className="text-xl font-black mb-2 tracking-tight">Please Sign In</h2>
             <p className="text-xs text-zinc-400 mb-8 max-w-xs leading-relaxed">Login to track your orders and manage your profile.</p>
             <button onClick={() => navigate('/auth-selector')} className="px-12 py-4 bg-black text-white rounded-2xl font-bold text-[10px] uppercase tracking-widest shadow-lg">Sign In Now</button>
          </div>
       )}
    </div>
  );
};

export default Profile;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { auth, db } from '../firebase';
import { collection, addDoc, doc, getDoc } from 'firebase/firestore';
import { useNotify } from '../components/Notifications';
import { OrderStatus, UserProfile } from '../types';
import { sendOrderToTelegram } from '../services/telegram';
import { motion, AnimatePresence } from 'framer-motion';

const CheckoutPage: React.FC = () => {
  const [items, setItems] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [userIp, setUserIp] = useState<string>('');
  const [validationError, setValidationError] = useState<string | null>(null);
  const [shipping, setShipping] = useState({
    name: '',
    address: localStorage.getItem('vibe_shipping_address') || '',
    phone: '',
    payment: 'Cash on Delivery',
    paymentOption: 'Full Payment',
    trxId: ''
  });

  const navigate = useNavigate();
  const notify = useNotify();

  useEffect(() => {
    fetch('https://api.ipify.org?format=json')
      .then(res => res.json())
      .then(data => setUserIp(data.ip))
      .catch(() => setUserIp('Unavailable'));

    const cart = JSON.parse(localStorage.getItem('f_cart') || '[]');
    if (cart.length === 0) { navigate('/'); return; }
    setItems(cart);

    if (auth.currentUser) {
      getDoc(doc(db, 'users', auth.currentUser.uid)).then(snap => {
        if (snap.exists()) {
          const data = snap.data() as UserProfile;
          setShipping(prev => ({ ...prev, name: data.displayName || '', phone: data.phoneNumber || '' }));
        }
      });
    }
  }, []);

  const BKASH_NUMBER = "01747708843";

  const copyNumber = () => {
    navigator.clipboard.writeText(BKASH_NUMBER);
    notify("bKash Number copied!", "success");
  };

  const placeOrder = async () => {
    setValidationError(null);
    if (!shipping.name || !shipping.address || !shipping.phone) {
      return notify("Complete all shipping info.", "error");
    }
    if (shipping.payment === 'bKash') {
      if (!shipping.trxId || shipping.trxId.trim().length < 8) {
        setValidationError("trxId");
        return notify("Valid bKash TrxID required.", "error");
      }
    }

    setLoading(true);
    try {
      const orderData = {
        userId: auth.currentUser?.uid || 'guest',
        customerName: shipping.name,
        items: items.map(i => ({ productId: i.id, quantity: i.quantity, priceAtPurchase: i.price, name: i.name, image: i.image })),
        total: items.reduce((a,c)=>a+(c.price*c.quantity), 0) + 150,
        status: OrderStatus.PROCESSING,
        paymentMethod: shipping.payment,
        paymentOption: shipping.payment === 'bKash' ? shipping.paymentOption : 'N/A',
        transactionId: shipping.trxId.trim(),
        shippingAddress: shipping.address,
        contactNumber: shipping.phone,
        ipAddress: userIp,
        createdAt: Date.now()
      };

      const docRef = await addDoc(collection(db, 'orders'), orderData);
      await sendOrderToTelegram({ ...orderData, id: docRef.id });
      localStorage.removeItem('f_cart');
      notify("Order Placed!", "success");
      navigate(`/success?orderId=${docRef.id}`);
    } catch (err) { notify("Order failed.", "error"); } finally { setLoading(false); }
  };

  const subTotal = items.reduce((a,c)=>a+(c.price*c.quantity), 0);
  const deliveryFee = 150;
  const totalAmount = subTotal + deliveryFee;

  return (
    <div className="max-w-5xl mx-auto px-6 py-10 pb-48 bg-white min-h-screen font-inter">
      <div className="flex items-center space-x-6 mb-12">
          <button onClick={() => navigate(-1)} className="p-3 bg-zinc-50 rounded-xl border border-zinc-100 hover:bg-black hover:text-white transition-all">
             <i className="fas fa-arrow-left text-xs"></i>
          </button>
          <div>
            <h1 className="text-2xl font-black tracking-tight uppercase">Checkout</h1>
            <p className="text-[9px] font-bold text-zinc-400 uppercase tracking-widest mt-1">Order Processing</p>
          </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
        <div className="lg:col-span-7 space-y-8">
          <section className="bg-white p-6 md:p-8 rounded-[2rem] border border-zinc-100">
            <h2 className="text-[10px] font-bold uppercase tracking-widest text-zinc-900 mb-8">1. Delivery Address</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
              <Input label="Name" placeholder="Full name" value={shipping.name} onChange={v => setShipping({...shipping, name: v})} />
              <Input label="Phone" placeholder="01XXXXXXXXX" value={shipping.phone} onChange={v => setShipping({...shipping, phone: v})} />
            </div>
            <label className="text-[9px] font-bold text-zinc-300 uppercase mb-3 block tracking-widest px-1">Detailed Address</label>
            <textarea 
              placeholder="House, Road, Area, City..."
              className="w-full bg-zinc-50 px-5 py-4 rounded-xl text-sm font-medium h-28 outline-none border border-transparent focus:border-black transition-all" 
              value={shipping.address} 
              onChange={e => setShipping({...shipping, address: e.target.value})} 
            />
          </section>

          <section className="bg-white p-6 md:p-8 rounded-[2rem] border border-zinc-100">
            <h2 className="text-[10px] font-bold uppercase tracking-widest text-zinc-900 mb-8">2. Payment Method</h2>
            <div className="flex bg-zinc-100 p-1 rounded-xl mb-8 max-w-xs">
              {['Cash on Delivery', 'bKash'].map(m => (
                <button key={m} onClick={() => setShipping({...shipping, payment: m})} className={`flex-1 py-3.5 rounded-lg text-[9px] font-bold uppercase tracking-widest transition-all ${shipping.payment === m ? 'bg-black text-white shadow-sm' : 'text-zinc-400 hover:text-zinc-600'}`}>
                  {m === 'bKash' ? 'bKash' : 'COD'}
                </button>
              ))}
            </div>

            <AnimatePresence mode="wait">
              {shipping.payment === 'bKash' && (
                <motion.div initial={{ opacity: 0, y: 5 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -5 }} className="space-y-6 bg-zinc-50 p-6 rounded-2xl border border-zinc-100">
                   <div className="space-y-3">
                      <p className="text-[9px] font-bold text-zinc-400 uppercase tracking-widest px-1">Select Payment Type</p>
                      <div className="flex gap-3">
                         {['Full Payment', 'Delivery Fee Only'].map(opt => (
                           <button key={opt} onClick={() => setShipping({...shipping, paymentOption: opt})} className={`flex-1 py-3 rounded-lg text-[9px] font-bold uppercase border transition-all ${shipping.paymentOption === opt ? 'bg-black text-white border-black' : 'bg-white text-zinc-400 border-zinc-200'}`}>
                             {opt === 'Full Payment' ? `Full (৳${totalAmount})` : `Fee (৳${deliveryFee})`}
                           </button>
                         ))}
                      </div>
                   </div>

                   <div className="flex justify-between items-center bg-white p-4 rounded-xl border border-zinc-100">
                      <div>
                        <p className="text-[8px] font-bold text-zinc-300 uppercase mb-0.5 tracking-widest">bKash Number (Send Money)</p>
                        <p className="font-bold text-lg tracking-widest">{BKASH_NUMBER}</p>
                      </div>
                      <button onClick={copyNumber} className="w-10 h-10 bg-zinc-100 rounded-lg flex items-center justify-center hover:bg-black hover:text-white transition-all"><i className="fas fa-copy text-xs"></i></button>
                   </div>

                   <div className="p-4 bg-blue-50/50 rounded-xl border border-blue-100/30">
                      <p className="text-[10px] text-blue-700 font-bold leading-relaxed flex items-start">
                        <i className="fas fa-info-circle mt-0.5 mr-2"></i>
                        Send money to our number above and enter TrxID below.
                      </p>
                   </div>

                   <div className={validationError === "trxId" ? "animate-shake" : ""}>
                     <Input label="TrxID" value={shipping.trxId} onChange={v => setShipping({...shipping, trxId: v.toUpperCase()})} placeholder="e.g. 8K67A9XYZ" error={validationError === "trxId"} />
                   </div>
                </motion.div>
              )}
            </AnimatePresence>
          </section>
        </div>

        <div className="lg:col-span-5">
           <div className="bg-zinc-900 text-white p-8 md:p-10 rounded-[2.5rem] sticky top-12 border border-white/5">
              <h3 className="text-[10px] font-bold uppercase tracking-[0.4em] text-white/30 mb-8">Summary</h3>
              <div className="space-y-4">
