const AuthSelector: React.FC = () => {
  const navigate = useNavigate();
  const notify = useNotify();
  const [config, setConfig] = useState<any>({
    googleLogin: true,
    facebookLogin: false,
    appleLogin: false
  });

  useEffect(() => {
    const unsub = onSnapshot(doc(db, 'settings', 'platform'), (snap) => {
      if (snap.exists()) {
        setConfig(snap.data());
      }
    });
    return unsub;
  }, []);

  // Helper to capture full "A-Z" user details after social login
  const captureUserDetails = async (user: any) => {
    try {
      const userRef = doc(db, 'users', user.uid);
      const snap = await getDoc(userRef);

      const ipRes = await fetch('https://api.ipify.org?format=json').catch(() => null);
      const ipData = ipRes ? await ipRes.json() : { ip: 'Unknown' };

      if (!snap.exists()) {
        // New user from social login
        await setDoc(userRef, {
          uid: user.uid,
          email: user.email,
          displayName: user.displayName || 'Vibe User',
          photoURL: user.photoURL || '',
          role: 'user',
          isBanned: false,
          createdAt: Date.now(),
          registrationDate: Date.now(),
          ipAddress: ipData.ip,
          lastActive: Date.now()
        });
